window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s6-1236","number":1236,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما معنى اللام في قوله تعالى: ﴿ووهبنا له إسحاق ويعقوب﴾؟","answer":"تفيد الاختصاص والنفع؛ أي جعلنا إسحاق ويعقوب هبة خاصة لإبراهيم وقرة عين له وامتدادًا صالحًا لذريته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص282–283، تحت عنوان «معنى اللام في قوله: ﴿له﴾»","url":""}]},{"id":"s6-622","number":622,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما سرّ تقديم إسحاق ويعقوب على نوح مع أن نوحًا أسبق زمنًا؟","answer":"قُدم إسحاق ويعقوب لاتصالهما المباشر بإبراهيم الذي يساق الكلام في إنعام الله عليه، ثم استؤنف بنوح السابق زمنًا لبيان تأصل الهداية في أصول هذه السلسلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص284، تحت «الغرض من تقديم ذكر إسحاق ويعقوب في السياق».","url":""}]},{"id":"s6-623","number":623,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما نكتة الفصل في قوله تعالى: ﴿كلًّا هدينا﴾؟","answer":"استؤنفت الجملة لتقرير تمام نعمة الهداية لكل من إسحاق ويعقوب، فجاءت كحكم مستقل بعد ذكر الهبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص285، تحت عنوان «نكتة الفصل في قوله تعالى: ﴿كلًّا هدينا﴾»","url":""}]},{"id":"s6-1237","number":1237,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما بلاغة عطف جملة ﴿ونوحًا هدينا من قبل﴾ على ﴿كلًّا هدينا﴾؟","answer":"وصل هداية نوح بهداية إبراهيم وذريته مع التنبيه بـ﴿من قبل﴾ على سبق زمنه وتأصل طريق الهدى في أصولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص286–287، تحت عنوان «بلاغة عطف جملة: ﴿ونوحًا هدينا من قبل﴾ على جملة: ﴿كلًّا هدينا﴾»","url":""}]},{"id":"s6-624","number":624,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما فائدة التعبير بقبلية هداية نوح؟","answer":"أثبت أن سنة الهداية قديمة قبل إبراهيم وذريته، وربط السلسلة اللاحقة بأصل سابق ثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص288، تحت عنوان «فائدة التعبير بقبلية هداية نوح»","url":""}]},{"id":"s6-1238","number":1238,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما فائدة التعبير بالحال في قوله تعالى: ﴿ومن ذريته﴾؟","answer":"جاء ذكر الذرية في سياق تعداد نعم الله على إبراهيم، فبيّن أن الهداية امتدت في ذريته وصارت من وجوه تكريمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص288–289، تحت عنوان «فائدة التعبير بالحال في قوله: ﴿ومن ذريته﴾»","url":""}]},{"id":"s6-625","number":625,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"لماذا بدأ من الذرية بداود وسليمان؟","answer":"بدأ بداود وسليمان لأنهما زوج يجمع النبوة والملك مع علاقة الأب والابن، ثم نُظمت الأسماء في مجموعات تقوم على مناسبات كالحكم والابتلاء والقرابة، لا على التسلسل الزمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص301، تحت «السر بذكر الأنبياء بهذا الترتيب في مجمل الآية الكريمة».","url":""}]},{"id":"s6-626","number":626,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما بلاغة الاعتراض بأسلوب التشبيه في قوله تعالى: ﴿وكذلك نجزي المحسنين﴾؟","answer":"اعترض بين أسماء الأنبياء ليقرر أن مثل ذلك الجزاء والهداية سنة للمحسنين، فعمم الحكم بعد أمثلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص290، تحت عنوان «بلاغة الاعتراض بأسلوب التشبيه في ﴿وكذلك﴾»","url":""}]},{"id":"s6-1239","number":1239,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما دلالة حرف التشبيه في ﴿وكذلك نجزي المحسنين﴾؟","answer":"ربط الكاف جزاء كل محسن بالجزاء السابق للأنبياء؛ فكما أكرمهم الله بإحسانهم يكرم غيرهم من المحسنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص290–291، تحت عنوان «دلالة حرف التشبيه في ﴿وكذلك﴾»","url":""}]},{"id":"s6-627","number":627,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما دلالة العطف بالواو بين أسماء الأنبياء؟","answer":"الواو لمطلق الجمع ولا تقتضي ترتيبًا زمنيًا، فجمعت الأنبياء في أصل الهداية والفضل من غير أن تجعل تسلسل الأسماء تاريخًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص301، تحت عنوان «دلالة العطف بالواو بين أسماء الأنبياء مطلق الجمع»","url":""}]},{"id":"s6-1240","number":1240,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما السر في ذكر الأنبياء بهذا الترتيب في مجمل الآية؟","answer":"راعى السياق مناسبات من القرابة والزمن والملك والابتلاء والصلاح وتنوع أحوال الرسالة، فكان ترتيب المعاني لا ترتيب الأعمار وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص301–302، تحت عنوان «السر بذكر الأنبياء بهذا الترتيب في مجمل الآية الكريمة»","url":""}]},{"id":"s6-628","number":628,"surah":6,"verses":[85],"references":[{"surah":6,"verses":[85]}],"verseLabel":"الأنعام: 85","question":"ما وجه جمع زكريا ويحيى وعيسى وإلياس في نسق واحد؟","answer":"جمع الأربعة وصف الصلاح والزهد عن زخارف الدنيا، مع تقارب بعضهم في النسب والزمن وحال الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص295، تحت عنوان «وجه ذكر الأنبياء ﴿وزكريا ويحيى وعيسى وإلياس﴾ معًا»","url":""}]},{"id":"s6-1241","number":1241,"surah":6,"verses":[85],"references":[{"surah":6,"verses":[85]}],"verseLabel":"الأنعام: 85","question":"ما علة ترتيب زكريا ويحيى وعيسى وإلياس في الآية؟","answer":"قدم زكريا على ابنه يحيى، وجاءا قبل عيسى لقرب الزمن، وقدم عيسى على إلياس لكونه صاحب كتاب؛ فترتبوا بحسب مناسبات ظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص295–296، تحت عنوان «علة ترتيب ذكر الأنبياء في ﴿وزكريا ويحيى وعيسى وإلياس﴾»","url":""}]},{"id":"s6-629","number":629,"surah":6,"verses":[85],"references":[{"surah":6,"verses":[85]}],"verseLabel":"الأنعام: 85","question":"لم وصف هؤلاء الأنبياء بـ﴿الصالحين﴾ مع أن الصلاح قد يوصف به غيرهم؟","answer":"المراد كمال الصلاح، لا مجرد أصله؛ فاللام تبرز أنهم الكاملون في الإتيان بما ينبغي والتحرز عما لا ينبغي. وفي الوصف ثناء يبين نقاء نفوسهم وتمام استقامتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص296–297، تحت «معنى اللام في لفظ ﴿الصالحين﴾»","url":""}]},{"id":"s6-630","number":630,"surah":6,"verses":[86],"references":[{"surah":6,"verses":[86]}],"verseLabel":"الأنعام: 86","question":"لماذا جُمِع إسماعيل واليسع ويونس ولوط في نسق واحد؟","answer":"جُمع إسماعيل واليسع ويونس ولوط لأنهم لم يبق لهم أتباع وأشياع، وقيل: لأن كل واحد منهم أرسل إلى أمة صغيرة؛ فجعلهم السياق مجموعة ثالثة يجمعها أصل الهداية والرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص298–299، تحت عنوان «مناسبة اقتران الأنبياء في قوله: ﴿وإسماعيل واليسع ويونس ولوط﴾»","url":""}]},{"id":"s6-631","number":631,"surah":6,"verses":[86],"references":[{"surah":6,"verses":[86]}],"verseLabel":"الأنعام: 86","question":"ما فائدة الاعتراض بجملة ﴿وكلًّا فضلنا على العالمين﴾؟","answer":"قرر وسط تعداد الأسماء أن الجامع بينهم تفضيل الله، وفصل منزلة الاصطفاء عن مجرد ذكر الأشخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص298–299، تحت عنوان «فائدة الاعتراض بجملة ﴿وكلًّا فضلنا على العالمين﴾»","url":""}]},{"id":"s6-1242","number":1242,"surah":6,"verses":[86],"references":[{"surah":6,"verses":[86]}],"verseLabel":"الأنعام: 86","question":"ما دلالة إسناد الفعل إلى ضمير العظمة في ﴿فضلنا﴾؟","answer":"أسند التفضيل إلى الله بضمير العظمة للتنويه بعظم العطاء وعلو منزلة من اختارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص299–300، تحت عنوان «دلالة إسناد الفعل إلى ضمير العظمة في ﴿فضلنا﴾»","url":""}]},{"id":"s6-632","number":632,"surah":6,"verses":[86],"references":[{"surah":6,"verses":[86]}],"verseLabel":"الأنعام: 86","question":"لماذا عُمّم تفضيل كل واحد منهم على ﴿العالمين﴾؟","answer":"المراد تفضيل كل نبي على عالمي زمانه أو على من عدا الأنبياء، لا تفضيل كل واحد على جميع الأنبياء الآخرين؛ فالتعميم مقيد بما يليق بمقام النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص300–301، تحت «دلالة اللام في قوله: ﴿على العالمين﴾ على الاستغراق المقيد»","url":""}]},{"id":"s6-633","number":633,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما بلاغة عطف ﴿ومن آبائهم﴾ على قوله تعالى: ﴿وكلًّا فضلنا﴾؟","answer":"وسع العطف دائرة الاجتباء بعد الأنبياء المسمين لتشمل الصالحين من آبائهم وذرياتهم وإخوانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص304–305، تحت عنوان «بلاغة عطف جملة ﴿ومن آبائهم﴾ على جملة ﴿وكلًّا فضلنا﴾»","url":""}]},{"id":"s6-1243","number":1243,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿ومن آبائهم﴾؟","answer":"تفيد التبعيض مع البيان؛ فالمجتبى بعض الآباء والذريات والإخوان ممن صلح، لا كل من دخل في القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص305–306، تحت عنوان «إفادة ﴿من﴾ التبعيض والبيان في ﴿ومن آبائهم﴾»","url":""}]},{"id":"s6-634","number":634,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما بلاغة الحذف في قوله تعالى بعد ذكر ﴿آبائهم وذرياتهم وإخوانهم﴾؟","answer":"حذف بيان من اجتبي منهم اعتمادًا على ﴿واجتبيناهم﴾؛ فدل السياق على أن المصطفى بعض أهل القرابة ممن صلح، لا جميعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص304–305، تحت عنوان «بلاغة الحذف في قوله تعالى»","url":""}]},{"id":"s6-635","number":635,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿واجتبيناهم﴾، دون أن يقال: اخترناهم؟","answer":"الاجتباء جمع على طريق الاصطفاء مع تخصيص العبد بفيض من النعم من غير سعي سابق؛ وهو أنسب لجماعة مختارة جمعها الله بعد اصطفائها، وأخص من مطلق الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص303، تحت عنوان «شرح المفردات: ﴿واجتبيناهم﴾»","url":""}]},{"id":"s6-636","number":636,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما نكتة تعدية فعل الهداية بـ﴿إلى﴾ في قوله تعالى: ﴿وهديناهم إلى صراط مستقيم﴾؟","answer":"صورت الهداية إيصالًا إلى طريق معلوم يسلكونه، فجمعت الدلالة على الإرشاد والتمكين من بلوغ الصراط.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص307، تحت عنوان «نكتة تعدية فعل الهداية بـ﴿إلى﴾»","url":""}]},{"id":"s6-1244","number":1244,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"لماذا وصف الصراط بالاستقامة مع أن الصراط لا يكون إلا مستقيمًا؟","answer":"جاء الوصف للتنويه بكمال الطريق ونفي كل اعوجاج عنه، وتثبيت أن ما هدي إليه الأنبياء هو الطريق الواضح الموصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص307–308، تحت عنوان «نكتة وصف الصراط بالاستقامة مع كونه كذلك»","url":""}]},{"id":"s6-637","number":637,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما فائدة وصف الصراط بالاستقامة في قوله تعالى: ﴿وهديناهم إلى صراط مستقيم﴾؟","answer":"الصراط هو الطريق الواضح الخالي من العوج، فوصْفه بالاستقامة تصريح بالمعنى المفهوم منه وتأكيد له، لئلا يكتفى بدلالة اللفظ الضمنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص308، تحت «نكتة وصف الصراط بالاستقامة مع كونه كذلك»","url":""}]},{"id":"s6-638","number":638,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما فائدة التعبير عن هدى الله باسم الإشارة في قوله تعالى: ﴿ذلك هدى الله﴾؟","answer":"جمع اسم الإشارة ما تقدم من وجوه الهداية وجعلها كأمر حاضر متميز يشار إليه ويعتمد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص312، تحت عنوان «فائدة التعبير عن هدى الله باسم الإشارة»","url":""}]},{"id":"s6-1245","number":1245,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"لماذا أوثر اسم إشارة البعيد في قوله تعالى: ﴿ذلك هدى الله﴾؟","answer":"استعمل البعيد لرفع منزلة الهدى وتعظيم قدره، فكأنه في مرتبة عالية يشير إليها المتكلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص312، تحت عنوان «إيثار التعبير باسم إشارة البعد»","url":""}]},{"id":"s6-639","number":639,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"لماذا أضيف الهدى إلى الله: ﴿هدى الله﴾؟","answer":"أضيف الهدى إلى الله لتعظيمه وتشريفه، ولبيان اختصاص التوفيق الحقيقي به؛ فما ناله الأنبياء ليس مستقلًا عن مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص312، تحت «دلالة إضافة الهدى إلى الله تعالى»","url":""}]},{"id":"s6-640","number":640,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما دلالة الباء في قوله تعالى: ﴿يهدي به﴾؟","answer":"جعلت هدى الله سببًا وواسطة يوصل بها من يشاء إلى الحق، والضمير عائد إلى الهدى المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص313، تحت عنوان «دلالة الباء في يهدي به»","url":""}]},{"id":"s6-1246","number":1246,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما فائدة تعليق الهداية بمشيئة الله تعالى؟","answer":"بيّن أن التوفيق للهدى فضل يجري باختيار الله وحكمته، فلا يستقل به العبد ولا يفرضه نسب أو منزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص313–314، تحت عنوان «فائدة تعليق الهداية بمشيئة الله تعالى»","url":""}]},{"id":"s6-641","number":641,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما معنى ﴿من﴾ في قوله تعالى: ﴿من يشاء من عباده﴾؟","answer":"هي بيانية تبين أن من تعلقت بهم مشيئة الهداية أفراد من عباده، مع بقاء الاختيار له سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص315، تحت عنوان «معنى من في من عباده»","url":""}]},{"id":"s6-1247","number":1247,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما سر التعبير بلفظ ﴿عباد﴾ في مقام الهداية؟","answer":"اختير لفظ العباد لإظهار مقام الخضوع لله والانتساب إليه، وهو أنسب بمن قبلوا هدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص315، تحت عنوان «سر التعبير بلفظ عباد»","url":""}]},{"id":"s6-1248","number":1248,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما فائدة إضافة العباد إلى ضمير الجلالة؟","answer":"الإضافة تشريف وتكريم، وتبين أن هدايتهم عناية خاصة من الله بعباده الذين اختارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص315–316، تحت عنوان «فائدة إضافة العباد إلى ضمير الجلالة»","url":""}]},{"id":"s6-642","number":642,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما دلالة ذكر الشرك بعد ذكر الهدى في قوله تعالى: ﴿ولو أشركوا لحبط عنهم﴾؟","answer":"قابل أعلى الهداية بأشد ما يبطلها ليقرر أن الشرك يهدم العمل ولا تحمي منه منزلة صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص316، تحت عنوان «دلالة ذكر الشرك بعد ذكر الهدى»","url":""}]},{"id":"s6-1249","number":1249,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما دلالة الشرط بـ﴿لو﴾ في قوله تعالى: ﴿ولو أشركوا﴾؟","answer":"فرضت أمرًا ممتنع الوقوع من الأنبياء لتقرير قاعدة عامة: لو وقع الشرك ممن علا قدره لحبط عمله، فغيره أولى بالحذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص316، تحت عنوان «دلالة الشرط بلو في ولو أشركوا»","url":""}]},{"id":"s6-643","number":643,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما الصورة في التعبير بحبوط العمل في قوله تعالى: ﴿لحبط عنهم ما كانوا يعملون﴾؟","answer":"الحبط في أصله انتفاخ بطن الإبل من أكل يضرها ولا ينفعها. فصُوّر به بطلان الأعمال بالشرك وذهاب ثمرتها؛ إذ تشبه الأعمال التي أفسدها الشرك طعامًا أضر آكله ولم يحقق له النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص317–318، تحت «بلاغة المجاز في التعبير بالحبط»","url":""}]},{"id":"s6-644","number":644,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما المراد بالكتاب والحكم في قوله تعالى: ﴿أولئك الذين آتيناهم الكتاب والحكم والنبوة﴾؟","answer":"الكتاب جنس الكتب المنزلة، والحكم العلم والحكمة والفصل والقضاء بالحق؛ وهما مع النبوة وجوه تكريم للأنبياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص322–323، تحت عنوان «شرح المفردات: الكتاب والحكم»","url":""}]},{"id":"s6-1250","number":1250,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما براعة الاستئناف الابتدائي في قوله تعالى: ﴿أولئك الذين آتيناهم الكتاب والحكم والنبوة﴾؟","answer":"استأنف بعد تعداد الأنبياء حكمًا جامعًا لعطاياهم، فربط الأسماء السابقة بسبب رفعتها من غير عطف يضعف استقلال التقرير.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص323–324، تحت عنوان «براعة الاستئناف الابتدائي في الآية»","url":""}]},{"id":"s6-645","number":645,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما سرّ تقديم ﴿الكتاب﴾ على ﴿الحكم والنبوة﴾؟","answer":"قُدِّم الكتاب لأنه أعلى مراتب التفضيل المذكورة في هذا السياق، ثم ذُكر الحكم، ثم النبوة؛ فجاء الترتيب بحسب وجوه العطاء والتكريم التي خُص بها أولئك المهديون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص326–327، تحت «دلالة ذكر الكتاب والحكم والنبوة دون سواها على هذا الترتيب»","url":""}]},{"id":"s6-646","number":646,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما دلالة الإشارة إلى غير مذكور بلفظ ﴿هؤلاء﴾؟","answer":"استحضر كفار مكة المشاهدين من غير أن يسبق لهم اسم، تحقيرًا لاعتراضهم أمام موكب الأنبياء وتنبيهًا إلى حضورهم في مقام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص329، تحت عنوان «دلالة الإشارة إلى غير مذكور في هؤلاء»","url":""}]},{"id":"s6-1251","number":1251,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما دلالة دخول الفاء في قوله تعالى: ﴿فقد وكلنا بها قومًا﴾؟","answer":"ربطت الجواب بشرط كفر هؤلاء ربط النتيجة بسببها، وأفادت سرعة تحقق البديل وأن كفرهم لا يعطل حفظ الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص329–330، تحت عنوان «دلالة دخول الفاء في فقد وكلنا بها قومًا»","url":""}]},{"id":"s6-647","number":647,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد وكلنا بها قومًا﴾، فجعل الإيمان أمانة موكّلة؟","answer":"التوكيل هو إسناد الشيء إلى من يحفظه ويقوم به؛ فصور الإيمان بهذه الأصول أمانة قد أقام الله لها قومًا يحفظونها، فلا تضيع بكفر قوم آخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص330–331، تحت «بلاغة الاستعارة في فقد وكلنا بها قومًا»","url":""}]},{"id":"s6-648","number":648,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"من هم القوم الموكلون بالكتاب والحكم والنبوة في المعنى الإجمالي للآية؟","answer":"هم من قاموا بالإيمان بالوحي وحفظه، وفي مقدمتهم الأنبياء والمؤمنون ومن تبعهم بإحسان، فلا يضيع الحق بكفر قوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص323–324، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1252","number":1252,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"لماذا قيل ﴿قومًا﴾ منكرة دون ناس أو فئة؟","answer":"أفاد التنكير التعظيم والعموم، ولفظ القوم يدل على جماعة متماسكة تنهض بالحق، وفيه بشارة بانتشار الإيمان بين أقوام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص331–332، تحت عنوان «إيثار التعبير بقومًا منكرة دون ناس أو فئة»","url":""}]},{"id":"s6-649","number":649,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"لماذا دخلت الباء على ﴿بكافرين﴾؟","answer":"الباء زائدة في خبر ﴿ليس﴾ لتوكيد النفي؛ أي ثبت أنهم منزّهون عن الكفر بها، متمسكون بالإيمان لا يتطرق إلى وصفهم شك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص332، تحت «بلاغة الوصف بالجملة الاسمية في ليسوا بها بكافرين»","url":""}]},{"id":"s6-650","number":650,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما براعة الاستئناف في قوله تعالى: ﴿أولئك الذين هدى الله﴾؟","answer":"استأنف ثناء جديدًا بعد ذكر عطايا الأنبياء، فجعل هدايتهم حكمًا مستقلًا يمهد للأمر بالاقتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص335، تحت عنوان «براعة الاستئناف في أولئك الذين هدى الله»","url":""}]},{"id":"s6-1253","number":1253,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما دلالة الفاء في قوله تعالى: ﴿فبهداهم اقتده﴾؟","answer":"فرعت الأمر بالاقتداء على ثبوت هداية الأنبياء؛ فلأن الله هداهم كان هداهم جديرًا بالاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص335–336، تحت عنوان «دلالة الفاء على التفريع»","url":""}]},{"id":"s6-651","number":651,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما نكتة تقديم الجار والمجرور في قوله تعالى: ﴿فبهداهم اقتده﴾؟","answer":"قدم للاختصاص والعناية، فقصر الاقتداء المأمور به على هدى الأنبياء الحق، لا على أهواء المخالفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص337، تحت عنوان «نكتة تقديم الجار والمجرور في فبهداهم اقتده»","url":""}]},{"id":"s6-1254","number":1254,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما دلالة الأمر بالاقتداء في قوله تعالى: ﴿اقتده﴾؟","answer":"الأمر باتباع أصول توحيد الأنبياء وأخلاقهم وطرائق طاعتهم، لا الخصائص والشرائع التي تختلف بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص338، تحت عنوان «دلالة الأمر بالاقتداء في اقتده»","url":""}]},{"id":"s6-652","number":652,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما فائدة إضافة الهدى إلى الضمير ﴿هم﴾ في قوله تعالى: ﴿فبهداهم اقتده﴾؟","answer":"أشعرت الإضافة بتمكن الهدى في الأنبياء حتى صار صفة ملازمة لهم، وجمعت ما تفرق فيهم من وجوه الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص337، تحت عنوان «فائدة إضافة الهدى إلى الضمير هم»","url":""}]},{"id":"s6-1255","number":1255,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما فائدة تخصيص النبي ﷺ بالذكر في الأمر بالاقتداء؟","answer":"أفرده بالخطاب تشريفًا وتثبيتًا، وليكون اقتداؤه بالأنبياء قدوة لأمته في اتباع طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص338، تحت عنوان «فائدة تخصيص النبي بالذكر»","url":""}]},{"id":"s6-653","number":653,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"لماذا جاءت هاء السكت في ﴿اقتده﴾؟","answer":"الهاء في ﴿اقتده﴾ هاء السكت، تثبت في الوقف، وقد ثبتت في رسم المصحف. وهي تهيئ وقفًا ظاهرًا على كلمة جامعة لمسيرة الأنبياء، فيزداد التنبيه إلى أهمية الاقتداء بهداهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص338، تحت «بلاغة الوقف على هاء السكت في قوله: ﴿فبهداهم اقتده﴾»","url":""}]},{"id":"s6-654","number":654,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما دلالة نفي سؤال الأجر في قوله تعالى: ﴿لا أسألكم عليه أجرًا﴾؟","answer":"دل على صدق الرسول وتجرده في البلاغ، وأن دعوته ليست طلبًا لمال أو منفعة من قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص339، تحت عنوان «دلالة نفي سؤاله الأجر»","url":""}]},{"id":"s6-1256","number":1256,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما بلاغة التعبير في قوله تعالى: ﴿قل لا أسألكم عليه أجرًا﴾؟","answer":"جاء الأمر بالقول إعلانًا مباشرًا لنزاهة الدعوة، ووافق هدي الأنبياء الذين يبلغون بلا عوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص339–340، تحت عنوان «بلاغة التعبير في قل لا أسألكم عليه أجرًا»","url":""}]},{"id":"s6-655","number":655,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"لماذا حصر القرآن أو الهدى في قوله: ﴿إن هو إلا ذكرى للعالمين﴾؟","answer":"القصر بالنفي والاستثناء قصر إضافي: مهمة الرسول والقرآن تجاه المخاطبين التذكير لا طلب الأجر. ولا ينفي ما للقرآن من هداية وتشريع ووظائف أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص341، تحت «بلاغة أسلوب القصر»","url":""}]},{"id":"s6-656","number":656,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما فائدة الإخبار عن القرآن بالمصدر في قوله تعالى: ﴿إن هو إلا ذكرى للعالمين﴾؟","answer":"أُخبر بالمصدر ﴿ذكرى﴾ للمبالغة، فكأن القرآن هو التذكير نفسه لا مجرد كلام يذكّر أحيانًا، وإضافته للعالمين تدل على عموم الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص341، تحت «بلاغة الإخبار بالمصدر مضافًا للعالمين في ذكرى للعالمين»","url":""}]},{"id":"s6-657","number":657,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة المجاز في الفعل ﴿قدروا﴾ في قوله تعالى: ﴿وما قدروا الله حق قدره﴾؟","answer":"نقل التقدير من معرفة مقدار الأشياء إلى معرفة جلال الله وتعظيمه، فدل على أنهم لم يعرفوا حكمته وصفاته حق المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص350–351، تحت عنوان «بلاغة المجاز في الفعل قدروا»","url":""}]},{"id":"s6-1257","number":1257,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة ظرف الزمان ﴿إذ قالوا﴾؟","answer":"جعل قولهم: ﴿ما أنزل الله على بشر من شيء﴾ وقتًا ظهر فيه نقص تعظيمهم لله، فربط الحكم بدليله المكشوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص352، تحت عنوان «دلالة ظرف الزمان إذ قالوا»","url":""}]},{"id":"s6-658","number":658,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"لماذا أضيف ﴿حق﴾ إلى ﴿قدره﴾؟","answer":"إضافة ﴿حق﴾ إلى ﴿قدره﴾ تؤكد المقدار الواجب من المعرفة والتعظيم، وتفظع جهلهم؛ إذ لم ينقصوا بعض حقه فحسب، بل نفوا أصل ما يليق به من إرسال الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص351–352، تحت «سر إضافة الحق إلى القدر في حق قدره»","url":""}]},{"id":"s6-659","number":659,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة الكناية بنفي معرفتهم قدر الله؟","answer":"كنى عن نقص تعظيمهم لله بإنكارهم الوحي؛ فمن عرف حكمته ورحمته وصفة كلامه لم ينف إرسال الرسل وإنزال الكتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص350، تحت عنوان «دلالة الكناية بنفي معرفتهم قدر الله»","url":""}]},{"id":"s6-1258","number":1258,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة إسناد الإنزال إلى الله في قولهم: ﴿ما أنزل الله على بشر من شيء﴾؟","answer":"الإسناد صريح في أن دعواهم تنفي أصل الوحي من عند الله، ولذلك كان قولهم جهلًا بصفته وحكمته لا مجرد إنكار كتاب بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص354، تحت عنوان «دلالة إسناد الإنزال إلى الله»","url":""}]},{"id":"s6-660","number":660,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"لماذا عبر بلفظ ﴿بشر﴾ وعدل عن رجل أو رسول أو إنسان؟","answer":"حكى نظرهم إلى الأنبياء من جهة الجسد البشري بقصد الحط من شأنهم وتجريدهم من مزية الرسالة، وعم جنس البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص354، تحت عنوان «سر التعبير بقوله بشر والعدول عن رجل أو رسول أو إنسان»","url":""}]},{"id":"s6-1259","number":1259,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة دخول ﴿من﴾ على النكرة في سياق النفي؟","answer":"أكدت الاستغراق، فصار زعمهم نفي إنزال أي شيء على أي بشر من غير استثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص355، تحت عنوان «دخول من على النكرة في سياق النفي»","url":""}]},{"id":"s6-661","number":661,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما أثر دخول ﴿من﴾ على النكرة في قوله تعالى: ﴿من شيء﴾؟","answer":"نصت على استغراق النفي، فأبطلت دعواهم إنزال أدنى شيء فضلًا عن كتاب عظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص355، تحت عنوان «دخول من على النكرة في سياق النفي»","url":""}]},{"id":"s6-1260","number":1260,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما فائدة تنكير ﴿شيء﴾ في قوله تعالى: ﴿ما أنزل الله على بشر من شيء﴾؟","answer":"عم التنكير كل منزل قل أو كثر، فظهر غلو قولهم وشموله لما يعرفون من كتب الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص355، تحت عنوان «فائدة تنكير شيء للعموم»","url":""}]},{"id":"s6-662","number":662,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"لماذا كان الرد سؤالًا: ﴿قل من أنزل الكتاب الذي جاء به موسى﴾؟","answer":"جاء الرد سؤالًا ليُلزمهم بما يقرون به من كتاب موسى: إن أنكروا كل وحي فمن أنزل التوراة؟ فالدليل مأخوذ من أصل مسلم عندهم، ولا يسعهم دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص356–357، تحت «دلالة الاستفهام وغرضه في من أنزل الكتاب الذي جاء به موسى»","url":""}]},{"id":"s6-663","number":663,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة استعارة النور للوضوح والبيان في وصف كتاب موسى؟","answer":"شبه الكتاب بالنور لأنه يكشف الحق ويبدد ظلمة الباطل والجهل، فصور أثر الوحي في الإدراك والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص358، تحت عنوان «بلاغة استعارة النور للوضوح والبيان»","url":""}]},{"id":"s6-1261","number":1261,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة الجمع بين النور والهدى في قوله تعالى: ﴿نورًا وهدى للناس﴾؟","answer":"النور يكشف الطريق ويبين الحق، والهدى يدل عليه ويوصل إلى العمل؛ فجمع الوصفان البيان والإرشاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص359، تحت عنوان «دلالة الجمع بين النور والهدى»","url":""}]},{"id":"s6-1262","number":1262,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة التعريف في لفظ ﴿الناس﴾ في قوله تعالى: ﴿وهدى للناس﴾؟","answer":"حمل التعريف على الناس المعهودين في السياق، وهم قوم موسى بنو إسرائيل الذين نزل الكتاب لهدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص359، تحت عنوان «دلالة التعريف في لفظ الناس»","url":""}]},{"id":"s6-664","number":664,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿تجعلونه قراطيس﴾، فجعل الكتاب نفسه أوراقًا متفرقة؟","answer":"ليس الذم لمجرد كتابة الكتاب في أوراق، بل لأنهم جزؤوه قراطيس متفرقة ليظهروا ما وافق أغراضهم ويخفوا كثيرًا؛ فالتجزئة وسيلة للتلاعب بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص360–361، تحت «وجه ذم جعلهم الكتاب قراطيس في تجعلونه قراطيس»","url":""}]},{"id":"s6-665","number":665,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما وجه ذم جعلهم الكتاب قراطيس؟","answer":"ذم تفريقهم الكتاب الواحد في صحائف بما مكنهم من إظهار بعضه وإخفاء بعضه بدل عرضه كاملًا والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص360–361، تحت عنوان «وجه ذم جعلهم الكتاب قراطيس»","url":""}]},{"id":"s6-1263","number":1263,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما فائدة وصف القراطيس بجملتي ﴿تبدونها وتخفون كثيرًا﴾؟","answer":"كشفت الجملتان غرض التفريق ونتيجته: إبداء ما يوافق أهواءهم وإخفاء كثير من الحق، فصار الوصف توبيخًا عمليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص360–361، تحت عنوان «فائدة وصف القراطيس بجملتي تبدونها وتخفون كثيرًا»","url":""}]},{"id":"s6-666","number":666,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما سرّ إطلاق الإبداء وتقييد الإخفاء بالكثرة في قوله تعالى: ﴿تبدونها وتخفون كثيرًا﴾؟","answer":"دلّ قوله ﴿وتخفون كثيرًا﴾ على أن المخفي من الكتاب كثير، وأن ما أبدوه قليل لا يرفع عنهم ذم الكتمان والتلاعب؛ فالمقصود إبراز عظم ما أخفوه لا مجرد وقوع الإخفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص362، تحت «نكتة إطلاق الإبداء وتقييد الإخفاء بالكثرة»","url":""}]},{"id":"s6-667","number":667,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وعلمتم ما لم تعلموا أنتم ولا آباؤكم﴾، وأظهر ﴿أنتم﴾؟","answer":"أُظهر ضمير ﴿أنتم﴾ مع دلالة الفعل عليه لتوكيد اختصاص المخاطبين بالامتنان، ثم عطف الآباء لنفي أن يكون هذا العلم موروثًا عنهم؛ فهو من تعليم الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص365، تحت «فائدة الضمير المنفصل أنتم ودلالة عطف ولا آباؤكم»","url":""}]},{"id":"s6-668","number":668,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة المبادرة بالجواب عن الاستفهام التقريري في قوله تعالى: ﴿قل الله﴾؟","answer":"أمر الرسول أن يتولى الجواب لأن المسؤول لا يسعه إنكار الحقيقة وقد يعاند أو يتهرب، فحسم التقرير وألزمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص366، تحت عنوان «بلاغة المبادرة بالجواب عن الاستفهام التقريري»","url":""}]},{"id":"s6-1264","number":1264,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما نكتة الإيجاز في جواب ﴿قل الله﴾؟","answer":"اقتصر على اسم الجلالة لأن الجواب لا يحتمل غيره، فجمع كلمة واحدة حسم الحجة وتعجيل الفائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص366–367، تحت عنوان «نكتة الإيجاز في الجواب في قل الله»","url":""}]},{"id":"s6-669","number":669,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة العطف بـ﴿ثم﴾ في قوله تعالى: ﴿ثم ذرهم﴾؟","answer":"أفادت الترتيب الرتبي؛ فبعد إقامة الحجة وقطع المعاذير يأتي تركهم في باطلهم تهديدًا، لا ترك دعوتهم قبل البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص367، تحت عنوان «دلالة العطف بثم»","url":""}]},{"id":"s6-1265","number":1265,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة المجاز في الأمر بتركهم؟","answer":"ليس المراد إهمال الدعوة، بل التهديد واليأس من انتفاع المعاندين بعد البيان، فكأنهم يتركون لعاقبة خوضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص367–368، تحت عنوان «بلاغة المجاز في الأمر بتركهم»","url":""}]},{"id":"s6-670","number":670,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿في خوضهم﴾؟","answer":"شبه دخولهم في الكلام الباطل بالخوض في الماء؛ لما فيه من إحاطة واضطراب واندفاع من غير بصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص370، تحت عنوان «بلاغة الاستعارة في خوضهم»","url":""}]},{"id":"s6-1266","number":1266,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة التعبير عن عنادهم باللعب؟","answer":"صور فعلهم عملًا بلا غاية نافعة، يكشف عبثهم بالحق وانصرافهم عن الجد والحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص370، تحت عنوان «دلالة التعبير عن عنادهم باللعب»","url":""}]},{"id":"s6-671","number":671,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى عن أهل الكتاب: ﴿تخفون كثيرًا﴾، ويعبّر القرآن في مواضع أخرى عن صنيعهم بالكتمان؟","answer":"الكتمان سكوت عن المعاني والأخبار، أما الإخفاء فأعم، ويستعمل في المعاني والمحسوسات. وعُبّر هنا بالإخفاء لأن المخفي آيات متلوة في التوراة، لا مجرد معانٍ أو أسرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص373–374، تحت «الفروق المعجمية: الكتمان والإخفاء»","url":""}]},{"id":"s6-672","number":672,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿وهذا كتاب أنزلناه مبارك﴾ باسم الإشارة؟","answer":"اسم الإشارة للقريب يستحضر القرآن كأنه حاضر مشاهد، ولا سيما بعد جدالهم في نزول الوحي، ويزيد المشار إليه تمييزًا وتفخيمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص378–379، تحت «سر إيثار اسم الإشارة هذا»","url":""}]},{"id":"s6-673","number":673,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما الغرض من وصف الكتاب بأنه ﴿مبارك﴾؟","answer":"أكد كثرة خير القرآن وثبات نفعه ودوامه، وأن بركته لازمة له لأنه منزل من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص379، تحت عنوان «الغرض من وصف الكتاب بأنه مبارك»","url":""}]},{"id":"s6-1267","number":1267,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما علة التعبير عن الإنزال بالفعل وعن البركة بالاسم؟","answer":"جاء الإنزال فعلًا لأنه حدث وقع وتجددت آثاره، وجاءت البركة اسمًا لأنها صفة ثابتة ملازمة للكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص380–381، تحت عنوان «علة التعبير عن الإنزال بالفعل وعن البركة بالاسم في الآية»","url":""}]},{"id":"s6-674","number":674,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما وجه تصديق القرآن للكتب السابقة؟","answer":"وافق أصول الوحي ووعد الكتب السابقة بالنبي، وأظهر صدقها فيما بقي حقًا فيها مع هيمنته عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص383، تحت عنوان «وجه تصديق القرآن للكتب السابقة بقوله: ﴿مصدق الذي بين يديه﴾»","url":""}]},{"id":"s6-1268","number":1268,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما دلالة التعبير عن الكتب السابقة بقوله تعالى: ﴿بين يديه﴾؟","answer":"كنى عما تقدمه من الكتب القريبة المتداولة، وهو أخص من مطلق ما قبله الذي يشمل السابق القريب والبعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص383–384، تحت عنوان «التعبير عن الكتب السابقة بقوله تعالى: ﴿بين يديه﴾»","url":""}]},{"id":"s6-675","number":675,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"لماذا أفرد الموصول: ﴿الذي بين يديه﴾؟","answer":"أُفرد الموصول ﴿الذي﴾ مع أن المراد كتب الوحي السابقة لأن جمع غير العاقل يجوز التعبير عنه بالمفرد؛ والمقصود ما تقدم من كتب الأنبياء، وبخاصة التوراة والإنجيل والزبور والصحف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص383–384، تحت «التعبير بالموصول المفرد الذي عن الكتب»","url":""}]},{"id":"s6-676","number":676,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما بلاغة استعارة لفظ ﴿أم القرى﴾ لمكة؟","answer":"شبهت مكة بالأم لأنها أصل القرى ومرجعها وأعظمها شأنًا، وفيها أول بيت وقبلة الناس ومحجهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص384، تحت عنوان «بلاغة استعارة لفظ ﴿أم القرى﴾»","url":""}]},{"id":"s6-1269","number":1269,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"لماذا أوثر التعبير بـ﴿أم القرى﴾ دون مكة؟","answer":"أبرز الاسم مكانتها المركزية وعمق صلتها بما حولها، فناسب بدء الإنذار منها وامتداده إلى سائر البلاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص385، تحت عنوان «إيثار التعبير بأم القرى دون مكة»","url":""}]},{"id":"s6-677","number":677,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما دلالة الجمع بين عموم الرسالة وخصوص مبدئها في قوله تعالى: ﴿ومن حولها﴾؟","answer":"بدأ الإنذار بأم القرى وما حولها بحسب مكان النزول، لكن اللفظ لا يحصر الرسالة في المحيط القريب؛ فهو مبدأ البلاغ لا غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص386، تحت عنوان «الدلالة على عموم الرسالة وخصوصها في ومن حولها»","url":""}]},{"id":"s6-1270","number":1270,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما دلالة إيجاز القصر في قوله تعالى: ﴿أم القرى ومن حولها﴾؟","answer":"جمع التعبير القليل مركز الدعوة ومجال امتدادها، فدل على إنذار مكة وسائر البلاد المحيطة بها من غير تعداد طويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص386–387، تحت عنوان «دلالة إيجاز القصر»","url":""}]},{"id":"s6-678","number":678,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين يؤمنون بالآخرة يؤمنون به﴾، فجعل الإيمان بالآخرة سببًا للإيمان بالقرآن؟","answer":"من أيقن بالبعث والجزاء عظمت رغبته في الثواب ورهبته من العقاب، فحمله ذلك على النظر في دلائل النبوة والإيمان بالقرآن الذي أبرز مشاهد الآخرة وقررها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص388–389، تحت «تلازم الإيمان بالآخرة والقرآن»","url":""}]},{"id":"s6-679","number":679,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما وجه تخصيص الصلاة بالذكر بعد الإيمان بالآخرة؟","answer":"لأن الصلاة أعظم العبادات الظاهرة بعد الإيمان بالله، وهي صلة بالرب ووسيلة للفوز بالجنة، فكانت علامة جامعة للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص390، تحت عنوان «وجه تخصيص الصلاة بالذكر»","url":""}]},{"id":"s6-1271","number":1271,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما علة تقديم الجار والمجرور في قوله تعالى: ﴿وهم على صلاتهم يحافظون﴾؟","answer":"قدم للعناية والاختصاص، فبرزت الصلاة موضع محافظتهم الدائمة، ودل ذلك على شدة تعاهدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص390–391، تحت عنوان «علة تقديم الجار والمجرور»","url":""}]},{"id":"s6-680","number":680,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما الذي يفيده لفظ ﴿يحافظون﴾ زيادة على مجرد أداء الصلاة؟","answer":"المحافظة تعهّد ومداومة؛ فالصلاة عهد بين العبد وربه، والمحافظة عليها رعاية لهذا العهد وحفظ له. لذلك يدل اللفظ على عناية مستمرة تتجاوز مجرد وقوع الأداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص390–391، تحت «إيثار لفظ يحافظون دون غيره»","url":""}]},{"id":"s6-681","number":681,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما فائدة تكرار ﴿من﴾ في ﴿ومن قال سأنزل مثل ما أنزل الله﴾ بعد ﴿ممن افترى على الله كذبًا أو قال أوحي إلي﴾؟","answer":"يفيد التكرار استقلال هذا النوع من الافتراء بالذم؛ فلا يتوقف وصف الشخص بأنه من أظلم الناس على جمع الصفات المذكورة كلها، بل يكفي ارتكاب واحدة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص405، تحت «علة تكرار الموصول من في الآية الكريمة»","url":""}]},{"id":"s6-682","number":682,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا جُعل الظلم محور الاستفهام في قوله تعالى: ﴿ومن أظلم ممن افترى على الله كذبًا﴾؟","answer":"جعل الظلم محور الاستفهام ليقرر أنه لا أحد أشد ظلمًا ممن اختلق على الله كذبًا؛ لأن جنايته تجمع إفساد الاعتقاد والتقول على الخالق وتضليل الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص400، تحت عنوان «إيثار الظلم ليكون محور الاستفهام»","url":""}]},{"id":"s6-1272","number":1272,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا عُطفت جملة ﴿أو قال أوحي إلي ولم يوح إليه شيء﴾ على الافتراء؟","answer":"فصل العطف نوعًا خاصًا غليظًا من الافتراء العام، وهو ادعاء نزول الوحي مع انتفائه، فأفرده بالذكر لعظم جريمة ادعاء النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص401–402، تحت عنوان «بلاغة عطف جملة أو قال أوحي إلي»","url":""}]},{"id":"s6-683","number":683,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا بُني ﴿أوحي﴾ و﴿يوح﴾ للمجهول؟","answer":"بُني الفعلان للمجهول لأن موضع الإنكار هو وقوع الوحي أو انتفاؤه، لا تعيين الموحي؛ فالفاعل معلوم وهو الله، وذكره لا يضيف إلى مقصد تكذيب المدعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص403، تحت «دلالة بناء الفعلين للمفعول في أو قال أوحي إلي ولم يوح إليه شيء»","url":""}]},{"id":"s6-684","number":684,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما فائدة تعقيب دعوى ﴿أوحي إلي﴾ بجملة ﴿ولم يوح إليه شيء﴾؟","answer":"جاءت الجملة حالًا تكشف كذب الدعوى وتناقضها؛ فهي تقيد الذم بمن يدعي الوحي مع انتفائه عنه، وتمنع أن يدخل في هذا الوصف الأنبياء الصادقون الذين أوحى الله إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص403–404، تحت «علة تقييد الجملة بالحال»","url":""}]},{"id":"s6-685","number":685,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما دلالة نسبة المفتري الإنزال إلى نفسه في قوله: ﴿سأنزل مثل ما أنزل الله﴾؟","answer":"استعمل المفتري لفظ الإنزال ادعاء لمماثلة فعل الله والتعالي على القرآن؛ فهو يزعم أنه سيأتي بكلام منزل مثله، وفي العبارة كشف لعظم جرأته واستكباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص405–406، تحت «فائدة السين في سأنزل وإيثار التعبير بفعل الإنزال»","url":""}]},{"id":"s6-686","number":686,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا حُذف جواب ﴿لو﴾ في ﴿ولو ترى إذ الظالمون في غمرات الموت﴾؟","answer":"حُذف جواب ﴿لو﴾ لتهويل المشهد وترك النفس تقدر ما لا يحيط به وصف، وتقديره: لرأيت أمرًا عظيمًا أو فظيعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص411، تحت «بلاغة حذف جواب الشرط في قوله: ﴿ولو ترى إذ الظالمون﴾»","url":""}]},{"id":"s6-687","number":687,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿في غمرات الموت﴾؟","answer":"استعيرت الغمرات لشدائد الموت لأنها تغمر الإنسان وتحيط به كما يغمره الماء، فصورت تمكن الشدة منه وعجزه عن دفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص410، تحت عنوان «بلاغة الاستعارة في غمرات الموت»","url":""}]},{"id":"s6-1273","number":1273,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا جُمعت ﴿غمرات﴾ في قوله تعالى: ﴿في غمرات الموت﴾؟","answer":"دل الجمع على تعدد الشدائد وأصنافها، أو على تعدد من تنزل بهم، فزاد تصوير أهوال الموت قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص410، تحت عنوان «علة التعبير بصيغة الجمع»","url":""}]},{"id":"s6-688","number":688,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما الصورة التي يكشفها التعبير عن قبض الأرواح ببسط الأيدي في ﴿والملائكة باسطو أيديهم﴾؟","answer":"بسط الأيدي كناية عن العنف في قبض أرواح الظالمين؛ فيصور الأخذ الشديد وما يلقونه عند النزع من شدة، بما يلائم مقام الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص411–412، تحت «بلاغة التعبير عن شدة الموت ببسط الأيدي في الآية»","url":""}]},{"id":"s6-689","number":689,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما وجه الأمر في ﴿أخرجوا أنفسكم﴾ مع أن إخراج الروح ليس بأيديهم؟","answer":"الأمر في ﴿أخرجوا أنفسكم﴾ مجازي، لا أمر حقيقيًا بما يقدرون عليه؛ وهو تصوير لعنف الملائكة وإلحاحهم وتشديدهم في قبض الأرواح من غير تنفيس ولا إمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص412–413، تحت «دلالة الأمر على أغراض مجازية في أخرجوا أنفسكم»","url":""}]},{"id":"s6-690","number":690,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما نكتة إضافة العذاب إلى الهوان في قوله تعالى: ﴿عذاب الهون﴾؟","answer":"جعلت الإضافة الهوان ملازمًا للعذاب ومن صميم أثره؛ فهو يجمع الألم والذل جزاء الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص415، تحت عنوان «نكتة إضافة العذاب إلى الهوان»","url":""}]},{"id":"s6-1274","number":1274,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا قيل ﴿عذاب الهون﴾ بدل وصف العذاب بأنه مهين؟","answer":"الإضافة أبلغ في تمكن الهوان وثبوته في العذاب من مجرد الوصف، فناسبت شدة الجزاء لمن استكبر عن آيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص415، تحت عنوان «إيثار إضافة العذاب إلى الهوان على الوصف به»","url":""}]},{"id":"s6-691","number":691,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما سرّ التعبير بـ﴿غير الحق﴾ في ﴿بما كنتم تقولون على الله غير الحق﴾ بدل لفظ الباطل؟","answer":"التعبير ينفي عن أقوالهم موافقة الحق نفيًا شاملًا، فيتناول ضروب افترائهم وكفرهم. وذكر الحق مع نفيه عن كلامهم أبلغ في إبراز خلوه منه وثبوت ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص417–418، تحت «إيثار التعبير بغير الحق دون الباطل»","url":""}]},{"id":"s6-692","number":692,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما بلاغة عطف قوله تعالى: ﴿وكنتم عن آياته تستكبرون﴾ على القول غير الحق؟","answer":"أثبت العطف سببًا مستقلًا للعذاب: فالقول غير الحق فساد باللسان، والاستكبار رفض عملي لقبول الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص418، تحت عنوان «بلاغة العطف وكنتم عن آياته تستكبرون»","url":""}]},{"id":"s6-1275","number":1275,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما سر تكرار ﴿كنتم﴾ عند ذكر القول غير الحق والاستكبار؟","answer":"أكد التكرار استقلال كل خصلة واستمرارها فيهم، وأن كل واحدة منهما سبب قائم لاستحقاق العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص418–419، تحت عنوان «سر تكرار كنتم»","url":""}]},{"id":"s6-693","number":693,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد جئتمونا فرادى﴾، مع أن الخلق يُحشرون جميعًا؟","answer":"يجيئون منفردين عن الأموال والأولاد والأنصار وما تعلقوا به في الدنيا؛ فاجتماعهم في المحشر لا ينافي انفراد كل منهم عن أسباب قوته ومعونته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص429–430، تحت «العدول عن لفظ وحدكم إلى فرادى»","url":""}]},{"id":"s6-694","number":694,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما وجه المقابلة بين ضمير التعظيم في ﴿جئتمونا﴾ ووصف مجيئهم بـ﴿فرادى﴾؟","answer":"ضمير التعظيم يبرز جلال من يرجعون إليه وعظمة شأنه، في حين يصور ﴿فرادى﴾ ضعفهم وانفرادهم عما كانوا يستندون إليه؛ فتظهر مهابة المقام ومهانة المقبلين عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص430، تحت «نكتة التعبير بضمير الجمع مع إفراد لفظة فرادى»","url":""}]},{"id":"s6-695","number":695,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"لماذا شُبه الحشر بالخلق الأول: ﴿كما خلقناكم أول مرة﴾؟","answer":"شُبه حالهم عند الحشر بحالهم أول خلقهم: يجيئون منفردين عما كان لهم من مال وولد وخدم وأعوان. فوجه التشبيه تجردهم من تلك الأسباب في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص431، تحت «بلاغة التشبيه كما خلقناكم أول مرة»","url":""}]},{"id":"s6-696","number":696,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿وتركتم ما خولناكم وراء ظهوركم﴾، فجعل النعم وراء الظهر؟","answer":"التعبير كناية عن مفارقة النعم مفارقةً تامة؛ فما كان محيطًا بهم وفي أيديهم صار متروكًا خلفهم لا يملكون الرجوع إليه ولا الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص432–433، تحت «بلاغة الكناية في وراء ظهوركم»","url":""}]},{"id":"s6-697","number":697,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما الذي يضيفه لفظ ﴿خولناكم﴾ إلى معنى العطاء؟","answer":"التخويل أخص من مجرد العطاء؛ فهو إعطاء الشيء وتمليك صاحبه إياه مع التعهد والرعاية، وفيه تذكير بأن ما بأيديهم من مال ونعم إنما خوّلهم الله إياه ثم فارقوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–426، تحت «شرح المفردات: خولناكم»","url":""}]},{"id":"s6-698","number":698,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما بلاغة نفي رؤية الشفعاء في قوله تعالى: ﴿وما نرى معكم شفعاءكم﴾؟","answer":"جاء نفي الرؤية للتهكم وإظهار خيبة دعواهم؛ فالذين زعموا شفاعتهم لا أثر لهم في ذلك المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص433، تحت عنوان «بلاغة نفي رؤية شركائهم وشفعائهم»","url":""}]},{"id":"s6-1276","number":1276,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"لماذا عُبر بالمضارع ﴿نرى﴾ في قوله تعالى: ﴿وما نرى معكم شفعاءكم﴾؟","answer":"استحضر المضارع غياب الشفعاء في موقف الحساب وجدّد تقريع المشركين كلما التمسوا أثرهم فلم يجدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص433–434، تحت عنوان «إيثار التعبير بالفعل المضارع في قوله: ﴿وما نرى معكم شفعاءكم﴾»","url":""}]},{"id":"s6-699","number":699,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما نكتة وصف الآلهة بالاسم الموصول في قوله تعالى: ﴿الذين زعمتم﴾؟","answer":"عرّفهم بالصلة التي تفضح منشأ منزلتهم؛ فلم تثبت لهم شركة، وإنما قامت على زعم المشركين وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص435، تحت عنوان «نكتة وصف الآلهة بالاسم الموصول»","url":""}]},{"id":"s6-1277","number":1277,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما الغرض من جملة الصلة ﴿زعمتم أنهم فيكم شركاء﴾؟","answer":"سجلت الصلة دعواهم عليهم وقررت بطلانها في مشهد غاب فيه الشفعاء، فصارت سببًا مباشرًا لتقريعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص435–436، تحت عنوان «الغرض من جملة الصلة»","url":""}]},{"id":"s6-1278","number":1278,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما علة تقديم الجار والمجرور ﴿فيكم﴾ في قوله تعالى: ﴿زعمتم أنهم فيكم شركاء﴾؟","answer":"قدّم للاهتمام بموضع دعوى الشركة؛ أي في شأنكم وعبادتكم وما خصصتموه لهم من نصيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص436–437، تحت عنوان «علة تقديم الجار والمجرور في قوله: ﴿زعمتم أنهم فيكم شركاء﴾»","url":""}]},{"id":"s6-700","number":700,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما بلاغة استعارة التقطيع للبعد في قوله تعالى: ﴿لقد تقطع بينكم﴾؟","answer":"صوّرت الروابط الموهومة بين العابدين ومعبوداتهم شيئًا موصولًا ثم قطع، فدلّت على زوال الصلات والأسباب تمامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص437، تحت عنوان «بلاغة استعارة لفظ التقطيع للبعد في قوله: ﴿لقد تقطع بينكم﴾»","url":""}]},{"id":"s6-1279","number":1279,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما دلالة تأكيد الخبر في قوله تعالى: ﴿لقد تقطع بينكم﴾؟","answer":"أكد الخبر باللام و﴿قد﴾ لتثبيت وقوع الانقطاع ودفع ما رسخ في أوهامهم من بقاء صلة أو شفاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص437، تحت عنوان «دلالة تأكيد الخبر في قوله: ﴿لقد تقطع بينكم﴾»","url":""}]},{"id":"s6-701","number":701,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"لماذا خُتم بقوله: ﴿وضل عنكم ما كنتم تزعمون﴾؟","answer":"تؤكد الخاتمة انقطاع ما توهموه من صلات؛ فقد غاب عنهم ما كانوا يزعمونه من شفاعة وشركة، فلم يجدوا شيئًا من ذلك عند الحاجة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص439، تحت «فائدة التعبير بالضلال»","url":""}]},{"id":"s6-702","number":702,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما المعنى اللغوي لوصف الله تعالى بأنه ﴿فالق الحب والنوى﴾؟","answer":"الفالق هو الشاق؛ أي يشق الحب والنوى فيخرج منهما النبات مع صلابة الغلاف وضعف الخارج منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–444، تحت عنوان «شرح المفردات: فالق»","url":""}]},{"id":"s6-1280","number":1280,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما نكتة التعبير باسم الفاعل ﴿فالق﴾؟","answer":"دل اسم الفاعل على ثبوت القدرة وتجدد أثرها، واستحضر هيئة شق الحب والنوى كلما خرج النبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص447، تحت عنوان «نكتة التعبير باسم الفاعل فالق»","url":""}]},{"id":"s6-1281","number":1281,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما الفرق بين الفصل والفرق والفلق والفتق؟","answer":"الفصل إبانة بين شيئين، والفرق تمييز وانفصال، والفلق شق مع إظهار ما في الداخل، والفتق فتح ما كان ملتئمًا؛ فاختير الفلق لمشهد خروج النبات من الحب والنوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص455، تحت عنوان «الفروق المعجمية: الفصل والفرق والفلق والفتق»","url":""}]},{"id":"s6-703","number":703,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما المراد بالحب والنوى في قوله تعالى: ﴿فالق الحب والنوى﴾؟","answer":"الحب أصل الزروع والحبوب، والنوى أصل كثير من الأشجار والثمار، فجمعهما التعبير في دلائل الإنبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–444، تحت عنوان «شرح المفردات: الحب والنوى»","url":""}]},{"id":"s6-1282","number":1282,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما سر تقديم الحب على النوى في قوله تعالى: ﴿فالق الحب والنوى﴾؟","answer":"قدم الحب لكثرة تعلق أقوات الناس به وشدة حاجتهم إلى الزروع، ثم عطف عليه النوى المستخرج منه الأشجار والثمار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص448، تحت عنوان «تقديم الحب على النوى»","url":""}]},{"id":"s6-704","number":704,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما دلالة التنويع بين الفعلية والاسمية في قوله تعالى: ﴿يخرج الحي من الميت ومخرج الميت من الحي﴾؟","answer":"استحضر الفعل تجدد إخراج الحي، وأثبت اسم الفاعل صفة إخراج الميت ودوام القدرة عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص449–450، تحت عنوان «دلالة التنويع بين الفعلية والاسمية في ﴿يخرج﴾ و﴿ومخرج﴾»","url":""}]},{"id":"s6-1283","number":1283,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما بلاغة اقتران الفعل ﴿يخرج﴾ بالحي واسم الفاعل ﴿مخرج﴾ بالميت؟","answer":"ناسب الفعل الحياة بما فيها من حركة وتجدد، وناسب الاسم الموت بما فيه من ثبات وسكون، فتلاءم المبنى مع المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص450–451، تحت عنوان «بلاغة اقتران الفعل ﴿يخرج﴾ بالحي، والاسم ﴿مخرج﴾ بالميت»","url":""}]},{"id":"s6-705","number":705,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما سرّ تقديم إخراج الحي من الميت؟","answer":"قُدّم إخراج الحي من الميت لأن وقوعه أكثر والعناية به أكمل، ولأنه المشاهد المحسوس أولًا؛ ثم عطف عليه إخراج الميت من الحي استكمالًا لوجهي القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص451، تحت «بلاغة التقديم، وسر اختلاف الصيغة في الآية الكريمة»","url":""}]},{"id":"s6-706","number":706,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكم الله﴾ بعد عرض ظاهرة النبات؟","answer":"اسم الإشارة يلخّص الدليل ويعين صاحبه: الفاعل لهذه الخوارق المشاهدة هو الله وحده، وفي البعد تعظيم لشأنه ورفع لمنزلته عن الشركاء المزعومين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص453، تحت «بلاغة التعبير باسم الإشارة، بمجيئه جمعًا ﴿ذلكم﴾»","url":""}]},{"id":"s6-707","number":707,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما جزالة التعبير بـ﴿أنى﴾ في قوله تعالى: ﴿فأنى تؤفكون﴾؟","answer":"جمعت ﴿أنى﴾ سؤال الجهة والكيفية مع الإنكار والتعجب: من أي وجه وكيف ينصرفون عن الحق بعد ظهور دلائله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص454، تحت عنوان «جزالة التعبير بأنى»","url":""}]},{"id":"s6-1284","number":1284,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما سر بناء ﴿تؤفكون﴾ للمجهول؟","answer":"ركز البناء للمجهول على شدة الصرف عن الحق وفظاعته، مهما يكن سببه، وأشعر بأن حالهم بلغت حدًا يعجب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص454، تحت عنوان «سر التعبير بتؤفكون مبنيًا للمجهول»","url":""}]},{"id":"s6-708","number":708,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿فالق الإصباح﴾؟","answer":"صوّر انبثاق ضوء الصبح من ظلمة الليل بشق يكشف النور، فاستحضر هيئة ظهور الصباح شيئًا فشيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص460–461، تحت عنوان «بلاغة الاستعارة في فالق الإصباح»","url":""}]},{"id":"s6-1285","number":1285,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"ما الفرق بين ﴿فالق الإصباح﴾ و«خالق الصباح»؟","answer":"الخالق يدل على الإيجاد، أما الفالق فيضيف صورة شق الظلمة وانبثاق الضوء منها؛ فكان أدق في تصوير المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص466، تحت عنوان «الفروق المعجمية: فالق وخالق»","url":""}]},{"id":"s6-709","number":709,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"لماذا اختير ﴿الإصباح﴾، لا: الصبح؟","answer":"اختير ﴿الإصباح﴾ لأنه مصدر يدل على ضياء النهار وبياضه المنتشر، وهو أوسع وأعم دلالة من لفظ ﴿الصبح﴾ المقصور على الوقت المعروف المقابل لليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص460–461، تحت «سر إيثار لفظ الإصباح على الصبح»","url":""}]},{"id":"s6-710","number":710,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"كيف وُصف الليل بأنه ﴿سكنًا﴾ والذين يسكنون فيه هم الخلق؟","answer":"الليل ظرف السكون والراحة، فسُمي باسم ما يقع فيه على سبيل المجاز؛ وفي ذلك مبالغة في ملاءمته لسكون الخلق حتى كأنه السكون نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص462–463، تحت «فن المجاز في وجعل الليل سكنًا»","url":""}]},{"id":"s6-711","number":711,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"ما سرّ التعبير باسم الفاعل ﴿فالق﴾ ثم بالفعل ﴿جعل﴾ في وصف الإصباح والليل؟","answer":"عُبر عن فلق الإصباح باسم الفاعل ﴿فالق﴾ لأنه وصف ثابت دائم لا يتقيد بمنتفع، وعُبر عن الليل بـ﴿جعل﴾ لأن جعله سكنًا مقيد بمن ينتفع براحة الليل، وكذلك الانتفاع بالشمس والقمر في الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص462، تحت «فائدة التعبير باسم الفاعل فالق مقابل الفعل جعل»","url":""}]},{"id":"s6-712","number":712,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"ما فائدة وصف الشمس والقمر بالمصدر في ﴿والشمس والقمر حسبانًا﴾؟","answer":"جاء المصدر بمعنى اسم الفاعل، فكأن الشمس والقمر حاسبان، مع أن الناس هم الذين يحسبون بهما. وهذا إسناد مجازي؛ لأنهما سبب معرفة الحساب وضبط الأوقات، فأُسند الحساب إلى سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص463–464، تحت «بلاغة التعبير بالمجاز في لفظ الحسبان»","url":""}]},{"id":"s6-713","number":713,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"لماذا خُتمت الآية بـ﴿ذلك تقدير العزيز العليم﴾؟","answer":"﴿العزيز﴾ يناسب القدرة التي لا يعجزها ضبط هذه الأجرام، و﴿العليم﴾ يناسب إحكام مقاديرها ومساراتها؛ فالنظام الكوني تقدير صادر عن قوة وعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص465–466، تحت «نكتة التذييل بصفتي العزيز العليم»","url":""}]},{"id":"s6-714","number":714,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿جعل لكم النجوم﴾، فقدم منفعتها للناس؟","answer":"تقديم ﴿لكم﴾ يبرز الامتنان وتسخير النجوم لمصلحة الناس، ويهيئ لبيان منفعتها العملية في الاهتداء، مع بقاء سائر حكم خلقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص470، تحت «دلالة تقديم المتعلق لكم على المفعول به»","url":""}]},{"id":"s6-715","number":715,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿ظلمات البر والبحر﴾؟","answer":"استعيرت الظلمات لاشتباه الطرق والحيرة، إلى جانب حقيقتها في ظلمة الليل، فصورت حاجة المسافر إلى الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص471، تحت عنوان «بلاغة الاستعارة في الظلمات»","url":""}]},{"id":"s6-1286","number":1286,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما بلاغة إضافة الظلمات إلى البر والبحر؟","answer":"عممت الإضافة مواطن الحيرة في اليابسة والماء، وأظهرت شمول نعمة الاهتداء بالنجوم في كلا المجالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص471–472، تحت عنوان «بلاغة الإضافة في قوله: ﴿ظلمات البر والبحر﴾»","url":""}]},{"id":"s6-716","number":716,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما سرّ تقديم البر على البحر في ﴿ظلمات البر والبحر﴾؟","answer":"البر هو الأصل في استقرار الناس ومعيشتهم وأسفارهم، أما ركوب البحر فعارض بالنسبة إلى ذلك؛ فقدم ما هو أصل وأكثر ملازمة لأحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص472، تحت «سر تقديم البر على البحر»","url":""}]},{"id":"s6-717","number":717,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"كيف يوجَّه اختلاف الفواصل بين ﴿يعلمون﴾ و﴿يفقهون﴾ و﴿يؤمنون﴾؟","answer":"يناسب العلم العلامات الظاهرة كالنجوم، والفقه ما يحتاج إلى تدبر خفي كأطوار الإنسان، والإيمان ما يقتضي تصديقًا بدلالات القدرة؛ فتلائم كل فاصلة سياقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص473، تحت عنوان «توجيه المتشابه اللفظي في ﴿يعلمون﴾ و﴿يفقهون﴾ و﴿يؤمنون﴾»","url":""}]},{"id":"s6-1287","number":1287,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما بلاغة التذييل بقوله تعالى: ﴿لقوم يعلمون﴾ في آية النجوم؟","answer":"ختمت الآية بالعلم لأن الانتفاع بالنجوم قائم على معرفة مواقعها ومساراتها ودلالتها على الجهات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص473–474، تحت عنوان «بلاغة التذييل»","url":""}]},{"id":"s6-718","number":718,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما دلالة الفعل ﴿أنشأكم﴾ في قوله تعالى: ﴿وهو الذي أنشأكم من نفس واحدة﴾؟","answer":"يدل الإنشاء على الإيجاد مع التربية والتنمية والانتقال في أطوار التكوين، فناسب نشأة البشر وتدرجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص475، تحت عنوان «شرح المفردات: أنشأكم»","url":""}]},{"id":"s6-1288","number":1288,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما الفرق بين الإنشاء والخلق في هذا السياق؟","answer":"الخلق أعم في أصل الإيجاد والتقدير، والإنشاء يبرز بدء الشيء وتنميته حتى يقوم على حاله؛ لذلك كان أوفق بأطوار الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص484–485، تحت عنوان «الفروق المعجمية: أنشأ وخلق»","url":""}]},{"id":"s6-719","number":719,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما فائدة التنصيص على وحدة النفس في ﴿أنشأكم من نفس واحدة﴾ مع كثرة البشر واختلافهم؟","answer":"كثرة البشر وتنوعهم مع نشأتهم من أصل واحد تدل على عظيم القدرة. وفي تذكيرهم بوحدة أصلهم ما يبعث على التراحم والتآلف بدل الفرقة والتناكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص478، تحت «دلالة إنشاء البشر من نفس واحدة»","url":""}]},{"id":"s6-720","number":720,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما المعنى اللغوي للمستقر والمستودع؟","answer":"المستقر موضع الثبات وطول المكث، والمستودع موضع الإقامة المؤقتة كالوديعة التي ترد إلى غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص475–476، تحت عنوان «شرح المفردات: مستقر ومستودع»","url":""}]},{"id":"s6-1289","number":1289,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما دلالة الجمع بين لفظي المستقر والمستودع؟","answer":"صور اختلاف أحوال الإنسان بين مقام يثبت فيه ومرحلة يمر بها ثم ينتقل عنها، فاستوعب تقلبه في أطوار وجوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص479، تحت عنوان «دلالات لفظي المستقر والمستودع»","url":""}]},{"id":"s6-721","number":721,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما سرّ تقديم ﴿مستقر﴾ على ﴿مستودع﴾؟","answer":"من وجوه ذلك مراعاة الترتيب الزمني على تفسير المستقر بصلب الأب والمستودع برحم الأم؛ فالنطفة تكون في مستقرها أولًا، ثم تصير إلى الرحم، فقدم السابق على اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص481، تحت «بلاغة تقديم المستقر على المستودع»","url":""}]},{"id":"s6-722","number":722,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما نكتة التعبير بالفعل ﴿يفقهون﴾ في سياق نشأة الإنسان؟","answer":"دل على فهم يتجاوز ظاهر المشاهدة إلى تدبر خفايا التكوين وتقلب الإنسان بين المستقر والمستودع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص482، تحت عنوان «نكتة التعبير بالفعل يفقهون»","url":""}]},{"id":"s6-1290","number":1290,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"لماذا كان لفظ الفقه أبين من لفظ العلم في هذا الموضع؟","answer":"الفقه علم دقيق نافذ في المعنى، والسياق يعرض أحوالًا خفية تحتاج إلى تدبر أعمق من مجرد إدراك المعلومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص482–483، تحت عنوان «لفظ الفقه أبين في الدلالة من لفظ العلم»","url":""}]},{"id":"s6-723","number":723,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ تقديم ﴿من السماء﴾ على ﴿ماء﴾ في ﴿أنزل من السماء ماء﴾؟","answer":"في التقديم عناية بمصدر الإنزال وتشويق إلى ما أُنزل؛ فإذا جاء ذكر الماء بعد ترقبه كان أوقع في النفس وأمكن فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص490–491، تحت «بلاغة تقديم المتعلق من السماء على المفعول ماء»","url":""}]},{"id":"s6-724","number":724,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما بلاغة الالتفات من الغيبة في ﴿أنزل﴾ إلى التكلم في ﴿فأخرجنا﴾؟","answer":"انتقل إلى ضمير التعظيم لإبراز العناية بإخراج النبات وتعداد آثاره، وتنشيط السامع بعد جريان الكلام على الغيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص491، تحت عنوان «بلاغة الالتفات من الغيبة إلى التكلم»","url":""}]},{"id":"s6-1291","number":1291,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما نكتة العدول من الماضي ﴿فأخرجنا﴾ إلى المضارع ﴿نخرج﴾؟","answer":"دل الماضي على تحقق أصل الفعل، واستحضر المضارع تجدده وتكرره في أنواع النبات والثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص494، تحت عنوان «نكتة العدول من الماضي فأخرجنا إلى المضارع نخرج»","url":""}]},{"id":"s6-725","number":725,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما وجه العموم في ﴿نبات كل شيء﴾، مع أن الموجودات ليست كلها نباتًا؟","answer":"المعنى: أخرج بالماء نبات كل صنف مما ينبت، أو النبات الذي تتعلق به حاجات المخلوقات؛ فلا يراد أن كل موجود نبات، بل عموم أجناس النبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–487، تحت «شرح المفردات: نبات»","url":""}]},{"id":"s6-726","number":726,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير بـ﴿خضرًا﴾ دون أخضر في وصف النبات؟","answer":"﴿خضرًا﴾ يدل على النبات الغض وتمكن النضارة فيه، ولا يقتصر على مجرد اللون؛ أما أخضر فيصح وصف ما لونه أخضر به وإن لم يكن نباتًا حيًا نضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص492–493، تحت «سبب العدول من أخضر إلى خضر»","url":""}]},{"id":"s6-727","number":727,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿نخرج منه حبًّا متراكبًا﴾ بالمضارع؟","answer":"المضارع يستحضر إخراج الحب وتراكبه كأنه مشاهد الآن، ويفيد تجدد ذلك؛ فجاء بعد الماضي الذي حكى أصل الإنزال والإخراج ليعرض للسامع صورة حية متجددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص494، تحت «نكتة العدول من الماضي فأخرجنا إلى المضارع نخرج»","url":""}]},{"id":"s6-728","number":728,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما معنى وصف الحب بأنه ﴿متراكبًا﴾؟","answer":"يصوّر حبات السنبل وقد ركب بعضها فوق بعض، كما يشاهد في القمح والشعير.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–487، تحت عنوان «شرح المفردات: متراكبًا»","url":""}]},{"id":"s6-1292","number":1292,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما بلاغة أسلوب اللف والنشر في تعداد النبات والثمر؟","answer":"وزع الكلام أنواع الخارج من الماء وصفاتها في نظام يجمع الإجمال ثم التفصيل، فيستحضر تنوع النبات وتناسق أجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص493، تحت عنوان «بلاغة أسلوب اللف والنشر في المعنى»","url":""}]},{"id":"s6-729","number":729,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير بـ﴿ومن النخل من طلعها﴾ بدل الاقتصار على: ومن طلع النخل؟","answer":"ذُكرت النخل أولًا لاستحضار منافعها على وجه العموم، ثم خُص طلعها بما يخرج منه من القنوان. أما الاقتصار على إضافة الطلع إلى النخل فيوجه النظر إلى منافع الطلع وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص494، تحت «سر العدول من الإضافة إلى التفصيل»","url":""}]},{"id":"s6-730","number":730,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"لماذا أوثرت القنوان القريبة بالذكر على البعيدة؟","answer":"لأن الدانية أسهل تناولًا وأظهر في مقام الامتنان بالثمر الميسر للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص496، تحت عنوان «إيثار ذكر القنوان القريبة على البعيدة»","url":""}]},{"id":"s6-1293","number":1293,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سر حذف القنوان البعيدة اختصارًا؟","answer":"دل ذكر الدانية على مقابلها، فاكتفى القرآن بما هو أنسب لمقام النعمة مع إيجاز لا يخل بالمعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص496–497، تحت عنوان «سر حذف القنوان البعيدة اختصارًا»","url":""}]},{"id":"s6-1294","number":1294,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما دلالة لفظ ﴿دانية﴾ في وصف القنوان؟","answer":"يشعر بقرب العذوق وسهولة الوصول إليها، فيزيد تصوير تيسير النعمة والانتفاع بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص497، تحت عنوان «دلالة لفظ دانية»","url":""}]},{"id":"s6-731","number":731,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير عن الأعناب بقوله ﴿جنات من أعناب﴾ بدل الاكتفاء بذكر أشجارها؟","answer":"الأعناب ذات أغصان كثيفة تلتف حتى تستر الأرض تحتها؛ فناسبها لفظ الجنات المأخوذ من الستر. والتعبير يستحضر هيئة أشجارها مجتمعة وما تحدثه من ظلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص498، تحت «نكتة التعبير عن الأعناب بالجنات»","url":""}]},{"id":"s6-732","number":732,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿مشتبهًا وغير متشابه﴾، فجمع بين الإثبات والنفي من مادة واحدة؟","answer":"جمع بين ﴿مشتبهًا﴾ و﴿غير متشابه﴾ لأن الثمار تتقارب في بعض الصفات والصور حتى تلتبس، ثم تختلف في صفات أخرى كالطعم واللون؛ فاجتمع التشابه والاختلاف في المخلوق الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص498–499، تحت «دلالات الاشتباه والتشابه في مشتبهًا وغير متشابه»","url":""}]},{"id":"s6-733","number":733,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما الدلالات المتوالية التي يستدعيها فعل الأمر ﴿انظروا﴾؟","answer":"دعا إلى نظر حسي في الثمر، ثم إلى تأمل عقلي في انتقاله من الظهور إلى النضج، ثم إلى الاستدلال بقدرة منشئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص500، تحت عنوان «توالي الدلالات في الفعل انظروا»","url":""}]},{"id":"s6-1295","number":1295,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما بلاغة عطف الينع على الثمر في قوله تعالى: ﴿انظروا إلى ثمره إذا أثمر وينعه﴾؟","answer":"خص الينع بعد عموم أحوال الثمر لأنه حال كماله وصلاحيته للانتفاع، فهو عطف خاص على عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص501، تحت عنوان «بلاغة عطف الخاص على العام»","url":""}]},{"id":"s6-734","number":734,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير بالفعل في ﴿إذا أثمر﴾ وبالاسم في ﴿وينعه﴾؟","answer":"بدء الإثمار ظهور حادث تتبدل فيه أحوال الثمر، فناسبه الفعل. أما الينع فهو حال بلوغ الثمرة كمال نضجها واستقرار صلاحها للانتفاع، فناسب التعبير عنه بالاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص500–501، تحت «سر التغاير بين الفعل والاسم في إذا أثمر وينعه»","url":""}]},{"id":"s6-735","number":735,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"لماذا خُتمت الآية بـ﴿لقوم يؤمنون﴾ بعد ﴿يعلمون﴾ و﴿يفقهون﴾؟","answer":"هذه الآية تذكر إنزال الماء وإحياء النبات وتنوع الثمر، وهي دلائل تذكّر بالبعث وتدعو إلى التصديق بالله؛ فناسبها ﴿يؤمنون﴾ بعد ﴿يعلمون﴾ و﴿يفقهون﴾. والإيمان أصل الشكر على هذه النعم، فجيء بما يستدعي الشكر ويؤسسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص502–503، تحت «توجيه المتشابه اللفظي بين فواصل الآي»","url":""}]},{"id":"s6-736","number":736,"surah":6,"verses":[99,141],"references":[{"surah":6,"verses":[99,141]}],"verseLabel":"الأنعام: 99، 141","question":"ما سرّ التعبير في قوله تعالى في الآية 99: ﴿مشتبهًا وغير متشابه﴾، وفي الآية 141: ﴿متشابهًا وغير متشابه﴾؟","answer":"من توجيه الفرق أن آية 99 تدعو إلى النظر في الثمار، فناسبها ﴿مشتبهًا﴾. أما آية 141 ففي سياق الأكل وأحكامه؛ فعدل فيها إلى ﴿متشابهًا﴾ لئلا يقترن الأمر بالأكل بلفظ قد يوهم الشبهة بين الحلال والحرام، مع أن التشابه المذكور في هيئة الثمار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص306–307، تحت «توجيه متشابه آيتي سورة الأنعام 141 و99»","url":""}]},{"id":"s6-737","number":737,"surah":6,"verses":[99,141],"references":[{"surah":6,"verses":[99,141]}],"verseLabel":"الأنعام: 99، 141","question":"ما سرّ التعبير في قوله تعالى في الآية 99: ﴿انظروا إلى ثمره﴾، وفي الآية 141: ﴿كلوا من ثمره﴾ مع تشابه المذكورات؟","answer":"آية 99 في سياق نصب دلائل الوحدانية والقدرة، فناسبها الأمر بالنظر والاعتبار. وآية 141 في سياق إبطال تحريم الأطعمة وبيان أحكامها وحقها، فناسبها ﴿كلوا﴾ و﴿آتوا حقه﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص503، تحت «وجه التناسب بين الفعلين انظروا وكلوا»","url":""}]},{"id":"s6-738","number":738,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما سر كون ﴿الجن﴾ مفعولًا أولًا مؤخرًا في قوله تعالى: ﴿وجعلوا لله شركاء الجن﴾؟","answer":"على هذا الإعراب يكون الجن هم المجعولين، وتأخيرهم يجعل الإنكار منصبًا أولًا على أصل اتخاذ شريك لله قبل تعيينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص508، تحت عنوان «سر كون الجن مفعولًا أولًا وأثر ذلك في المعنى»","url":""}]},{"id":"s6-1296","number":1296,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما بلاغة التقديم والتأخير في قوله تعالى: ﴿شركاء الجن﴾؟","answer":"قدم ﴿شركاء﴾ للعناية بإنكار الشركة مطلقًا، ثم ذكر الجن لبيان نوع الشرك الواقع منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص509–510، تحت عنوان «بلاغة التقديم والتأخير في شركاء الجن»","url":""}]},{"id":"s6-739","number":739,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما سرّ تقديم ﴿لله﴾ على ﴿شركاء﴾؟","answer":"قُدّم ﴿لله﴾ للاهتمام بمن جُعل له الشريك ولزيادة التشنيع؛ إذ يظهر من أول التركيب أنهم سوّوا مخلوقًا بالله الذي انفرد بالخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص510، تحت «سر تقديم المجرور لله على المفعول»","url":""}]},{"id":"s6-740","number":740,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما دلالة مجيء قوله تعالى: ﴿وخلقهم﴾ عقب اتخاذهم الجن شركاء؟","answer":"جملة ﴿وخلقهم﴾ حال أو اعتراض يقرر التناقض: جعلوا الجن شركاء لله مع أن الله خالقهم وخالق من عبدهم، والمخلوق لا يكون شريكًا لخالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص511، تحت «فائدة إيراد الفعل وخلقهم»","url":""}]},{"id":"s6-741","number":741,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما بلاغة المجاز في لفظ ﴿خرقوا﴾؟","answer":"استعمل الخرق، وهو القطع على فساد، في اختلاق دعوى البنين والبنات بلا علم؛ فصور فظاعة الافتراء واضطرابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص511، تحت عنوان «بلاغة المجاز في لفظ وخرقوا»","url":""}]},{"id":"s6-1297","number":1297,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما الفرق بين الخرق والخلق؟","answer":"الخلق إيجاد على تقدير ونظام، أما الخرق ففيه معنى القطع والفساد والاختلاق بلا تقدير؛ فناسب وصف دعواهم الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص515، تحت عنوان «الفروق المعجمية: خرق وخلق»","url":""}]},{"id":"s6-742","number":742,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما سرّ تقديم البنين على البنات في ﴿وخرقوا له بنين وبنات﴾؟","answer":"من وجوه التقديم أن نسبة البنين إلى الله كانت دعوى طوائف أكثر، كاليهود والنصارى، فقدم الأوسع وقوعًا. وذكر المصدر أيضًا مراعاة تقديم الذكر على الأنثى باعتبار أصل الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص512، تحت «بلاغة تقديم البنين على البنات»","url":""}]},{"id":"s6-743","number":743,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"إذا كانت دعوى البنين والبنات افتراءً، فما فائدة زيادة ﴿بغير علم﴾؟","answer":"هي بيان وتوكيد لفساد افترائهم؛ فلا يقوم قولهم على شيء يصح أن يسمى علمًا. وتنكير ﴿علم﴾ في سياق النفي يستأصل دعوى أن لهم فيه دليلًا، فيزيد تقريعهم على الجهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص512–513، تحت «سر تنكير لفظ علم من قوله تعالى بغير علم»","url":""}]},{"id":"s6-744","number":744,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"لماذا جمع بين ﴿سبحانه وتعالى﴾؟","answer":"التسبيح تنزيه لله عما لا يليق به، أما التعالي فإثبات أنه متعالٍ في ذاته عن النقائص، سواء نزهه الناس أم لم يفعلوا. فجمع التعبير بين تنزيهه والإخبار بكماله الذاتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص514، تحت «الفرق بين التسبيح والتعالي في سبحانه وتعالى»","url":""}]},{"id":"s6-745","number":745,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما دلالة ختام التنزيه بقوله ﴿عما يصفون﴾؟","answer":"دعواهم الشريك والولد تتضمن نسبة صفات إلى الله؛ فجاء ﴿يصفون﴾ ليتناول تلك الأوصاف الباطلة كلها، وينزه الله عن أن يكون شيء منها وصفًا حقيقيًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص514، تحت «علة الختام بالفعل يصفون»","url":""}]},{"id":"s6-746","number":746,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما فائدة التعبير بلفظ ﴿بديع﴾ في قوله تعالى: ﴿بديع السماوات والأرض﴾؟","answer":"دل على إنشاء السماوات والأرض من غير مثال سابق، وهو أبلغ في نفي الحاجة إلى ولد أو معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص518، تحت عنوان «فائدة التعبير بلفظ بديع في الآية»","url":""}]},{"id":"s6-1298","number":1298,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما الفرق بين البديع والخالق؟","answer":"الخالق يقدر ويوجد، والبديع يزيد معنى الإيجاد من غير مثال سابق؛ فكل بديع خالق وليس كل استعمال للخالق مبرزًا لهذا القيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص522–523، تحت عنوان «الفروق المعجمية: بديع وخالق»","url":""}]},{"id":"s6-747","number":747,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"لماذا جاء نفي الولد في صورة سؤال: ﴿أنى يكون له ولد﴾؟","answer":"﴿أنى﴾ استفهام إنكاري تعجبي ينفي كل وجه يمكن أن يتوهم لوجود الولد؛ كيف ومن أين يكون له ولد وهو بديع الخلق ولم تكن له صاحبة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص520، تحت «دلالة الاستفهام في أنى»","url":""}]},{"id":"s6-748","number":748,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما فائدة إيراد ﴿ولم تكن له صاحبة﴾ بعد إنكار أن يكون لله ولد؟","answer":"جاءت الجملة حالًا تؤكد استحالة ما ادعوه؛ فالولادة المعهودة تستلزم صاحبة، وقد نُفيت عنه. أما إيجاده المخلوقات فمنشؤه الخلق والإبداع، لا التولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص520–521، تحت «فائدة جملة ولم تكن له صاحبة»","url":""}]},{"id":"s6-749","number":749,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"لماذا عطف ﴿وخلق كل شيء﴾ على نفي الصاحبة والولد؟","answer":"عطف ﴿وخلق كل شيء﴾ برهانًا جامعًا: كل ما سواه مخلوق له، والولد لو وُجد لكان من جملة الخلق، فلا يصح أن يكون جزءًا من الخالق أو شريكًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص521، تحت «جملة وخلق كل شيء بين الاستئناف والحالية»","url":""}]},{"id":"s6-750","number":750,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما بديع الختام بقوله تعالى: ﴿وهو بكل شيء عليم﴾؟","answer":"أتمت الفاصلة دليل القدرة بالعلم الشامل، فقررت كمال الله واستغناءه وأبطلت نسبة الولد والصاحبة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص521، تحت عنوان «بديع الختام بالفاصلة»","url":""}]},{"id":"s6-1299","number":1299,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما بلاغة الاستئناف في قوله تعالى: ﴿وهو بكل شيء عليم﴾؟","answer":"جاءت الجملة مستقلة لتقرير أصل جامع: إحاطة علمه بكل شيء، فكانت تعليلًا لما سبق وتثبيتًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص521–522، تحت عنوان «بلاغة الاستئناف في الفاصلة»","url":""}]},{"id":"s6-751","number":751,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكم الله ربكم﴾ باسم الإشارة للبعيد؟","answer":"الإشارة للبعيد للتعظيم، وتعود إلى الموصوف بالخلق والإبداع والعلم في الآيات السابقة؛ أي ذلك المتفرد بهذه الصفات العظيمة هو الله ربكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص525–526، تحت «فائدة استعمال اسم الإشارة في ذلكم الله ربكم»","url":""}]},{"id":"s6-752","number":752,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما فائدة الإخبار بلفظ ﴿ربكم﴾ بعد اسم الله في قوله تعالى: ﴿ذلكم الله ربكم﴾؟","answer":"انتقل من الاسم الجامع للألوهية إلى وصف الرعاية والتدبير المتصل بالمخاطبين، فأقام موجب عبادته عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص527، تحت عنوان «فائدة الإخبار بقول ربكم بعد الإخبار باسم الله الأحسن»","url":""}]},{"id":"s6-1300","number":1300,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما براعة ترتيب قوله تعالى: ﴿ذلكم الله ربكم لا إله إلا هو خالق كل شيء﴾؟","answer":"رتب المعاني من تعيين المعبود الحق، إلى ربوبيته، ثم نفي الشريك، ثم برهان الخلق؛ فتكامل تقرير التوحيد والحجة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص528–529، تحت عنوان «براعة الترتيب في ذلكم الله ربكم لا إله إلا هو خالق كل شيء»","url":""}]},{"id":"s6-753","number":753,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"لماذا فُرعت العبادة بالفاء: ﴿فاعبدوه﴾؟","answer":"الفاء تفيد أن العبادة نتيجة لازمة لما ثبت من وحدانيته وربوبيته وخلقه كل شيء؛ فمن كان كذلك استحق أن يعبد وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص529–530، تحت «دلالة الفاء في فاعبدوه»","url":""}]},{"id":"s6-754","number":754,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما مناسبة ختم الأمر بالعبادة بقوله ﴿وهو على كل شيء وكيل﴾؟","answer":"الوكيل هنا القائم على الخلق بالحفظ والرعاية؛ فذكره يبين أن عنايته بهم مستمرة، ويعلل استحقاقه العبادة وحده، إذ لا يستغنون عن حفظه وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص532، تحت «سر اختيار اسم الله الوكيل»","url":""}]},{"id":"s6-755","number":755,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما سر استعمال مفردة ﴿تدركه﴾ في قوله تعالى: ﴿لا تدركه الأبصار﴾؟","answer":"الإدراك بلوغ الشيء والإحاطة به، فنفت الآية إحاطة الأبصار بالله، وهو معنى أخص من مطلق الرؤية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص534–535، تحت عنوان «سر استعمال مفردة تدركه»","url":""}]},{"id":"s6-1301","number":1301,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما دلالة استعمال ﴿تدركه﴾ مع الأبصار؟","answer":"أسند الإدراك إلى الأبصار ليعم نفي إحاطتها به في جميع الأوقات، مع بقاء الفرق بين نفي الإحاطة ونفي أصل الرؤية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص535–536، تحت عنوان «دلالة استعمال مفردة تدركه مع الأبصار»","url":""}]},{"id":"s6-756","number":756,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"لماذا جُمعت ﴿الأبصار﴾؟","answer":"جُمعت الأبصار لاستغراق أبصار الخلق كلها؛ فلا يحيط به بصر مهما تعدد أصحابه أو اختلفت قواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص536، تحت «دلالة الجمع ودخول أل في الأبصار»","url":""}]},{"id":"s6-757","number":757,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما بلاغة المقابلة بين ﴿لا تدركه الأبصار﴾ و﴿هو يدرك الأبصار﴾؟","answer":"أظهرت المقابلة كمال إحاطته وقصور خلقه: أبصارهم لا تحيط به، وهو يحيط بها وبما تبصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص537، تحت عنوان «بلاغة المقابلة بين لا تدركه الأبصار وهو يدرك الأبصار»","url":""}]},{"id":"s6-1302","number":1302,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما بلاغة المجاز بالحذف في قوله تعالى: ﴿وهو يدرك الأبصار﴾؟","answer":"أطلق الأبصار وأريد أصحابها وما يتعلق بها، فدل الكلام بإيجازه على إحاطته بالبصر والمبصر والباصرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص538، تحت عنوان «بلاغة المجاز بالحذف»","url":""}]},{"id":"s6-758","number":758,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"كيف أثر اشتقاق اسم الله ﴿اللطيف﴾ في تنوع معناه البلاغي؟","answer":"احتمل معنى التنزه عن إدراك الأبصار لدقة شأنه، واحتمل معنى الرفق والإحسان؛ فتسع دلالته للسياقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص539، تحت عنوان «أثر اشتقاق اسم الله اللطيف في التنوع البلاغي»","url":""}]},{"id":"s6-1303","number":1303,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما نكتة اللف والنشر في قوله تعالى: ﴿وهو اللطيف الخبير﴾؟","answer":"ناسب ﴿اللطيف﴾ نفي إحاطة الأبصار به، وناسب ﴿الخبير﴾ إحاطته بالأبصار وأصحابها، فجاءت الخاتمة موزعة على طرفي الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص540، تحت عنوان «نكتة اللف والنشر»","url":""}]},{"id":"s6-759","number":759,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما غرض الجناس بين البصائر والأبصار في سياق الآيتين؟","answer":"قارب اللفظان واختلف المعنى، فربط دلائل القلب بأداة النظر الحسي ونبه إلى أن المقصود إبصار الحق لا مجرد رؤية العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص544، تحت عنوان «غرض الجناس بين البصائر والأبصار»","url":""}]},{"id":"s6-1304","number":1304,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة الاستعارة المكنية في لفظ ﴿بصائر﴾؟","answer":"صُورت الحجج والهدايات بوسائل إبصار للقلوب تكشف بها مواقع الحق، فاشتق لها اسم البصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص544–545، تحت عنوان «الاستعارة المكنية في بصائر»","url":""}]},{"id":"s6-760","number":760,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"لماذا جُمعت ﴿بصائر﴾ مع وحدة القرآن؟","answer":"جُمعت لتعدد الآيات والحجج ووجوه الدلالة التي جاء بها القرآن، وإن كان الكتاب واحدًا؛ فكل حجة بصيرة تهدي إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص545، تحت «نكتة جمع البصائر في قد جاءكم بصائر»","url":""}]},{"id":"s6-761","number":761,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿فمن أبصر فلنفسه﴾؟","answer":"استعير الإبصار لقبول الحجة والاهتداء بها، لأن المهتدي يرى الحق بقلبه كما يرى المبصر الطريق بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص547، تحت عنوان «الاستعارة في فمن أبصر»","url":""}]},{"id":"s6-1305","number":1305,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة الاستعارة التصريحية في قوله تعالى: ﴿ومن عمي فعليها﴾؟","answer":"صرح بالعمى بدل الإعراض والضلال، فصور المعرض فاقدًا لبصيرة تهديه مع قيام الدليل أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص548–549، تحت عنوان «بلاغة الاستعارة التصريحية في عمي»","url":""}]},{"id":"s6-1306","number":1306,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة المقابلة بين ﴿فمن أبصر﴾ و﴿ومن عمي﴾؟","answer":"قابل الهدى بالعمى والنفع بالضرر، فبين أن ثمرة الاختيار تعود إلى صاحبه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص550، تحت عنوان «بلاغة المقابلة»","url":""}]},{"id":"s6-762","number":762,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة الاستعارة التبعية في اللام من قوله تعالى: ﴿فلنفسه﴾؟","answer":"استعملت اللام للاختصاص والنفع، فدلّت على أن ثمرة الإبصار راجعة إلى صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص547، تحت عنوان «الاستعارة التبعية في حرف اللام»","url":""}]},{"id":"s6-1307","number":1307,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة استعمال حرف الاستعلاء ﴿على﴾ في قوله تعالى: ﴿فعليها﴾؟","answer":"صور ضرر العمى وتبعته حملًا واقعًا على النفس، فناسب حرف الاستعلاء معنى الثقل والضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص548–549، تحت عنوان «بلاغة استعمال حرف الاستعلاء على»","url":""}]},{"id":"s6-763","number":763,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]},{"surah":11,"verses":[86]}],"verseLabel":"الأنعام: 104؛ هود: 86","question":"ما غرض التتميم في قوله تعالى: ﴿وما أنا عليكم بحفيظ﴾ في الأنعام؟","answer":"أتمت الجملة المعنى بنفي أن يكون الرسول رقيبًا يحفظ أعمالهم أو يتحمل تبعتها؛ فوظيفته البلاغ، ونفع الهدى وضرر الضلال عائدان إلى صاحبهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص551، تحت «غرض فن التتميم»","url":""}]},{"id":"s6-1408","number":1408,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]},{"surah":11,"verses":[86]}],"verseLabel":"الأنعام: 104؛ هود: 86","question":"ما بلاغة ختم موعظة شعيب بقوله: ﴿وما أنا عليكم بحفيظ﴾؟","answer":"يلائم الختم مقام النصح بعد بيان الحلال والحرام؛ فهو يقرر أن شعيبًا ناصح مبلِّغ، وأن تبعة الاختيار والحساب على المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص518، تحت «بلاغة الختم: ﴿وما أنا عليكم بحفيظ﴾»","url":""}]},{"id":"s6-1409","number":1409,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]},{"surah":11,"verses":[86]}],"verseLabel":"الأنعام: 104؛ هود: 86","question":"ما دلالة النفي في قول شعيب: ﴿وما أنا عليكم بحفيظ﴾؟","answer":"ينفي أن يكون متسلطًا عليهم أو موكَّلًا بإحصاء أعمالهم ومجازاتهم؛ فلا يبقى بعد البلاغ إلا مسؤوليتهم أمام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص518–519، تحت «دلالة النفي في: ﴿وما أنا عليكم بحفيظ﴾»","url":""}]},{"id":"s6-1410","number":1410,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]},{"surah":11,"verses":[86]}],"verseLabel":"الأنعام: 104؛ هود: 86","question":"ما نكتة اختيار لفظ ﴿حفيظ﴾ في قول شعيب؟","answer":"يجمع لفظ ﴿حفيظ﴾ معنى الإحصاء والمراقبة ومعنى المنع والحراسة؛ فنفى عن نفسه كلا المعنيين ليخلص مقامه للنصح والبلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص519، تحت «نكتة اختيار التعبير بـ﴿حفيظ﴾»","url":""}]},{"id":"s6-764","number":764,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما الذي يفيده لفظ ﴿نصرف الآيات﴾ زيادة على مجرد بيانها؟","answer":"التصريف تنويع وجوه البيان؛ فتُعرض الحجة مرة في مثال، ومرة في قصة أو غيرهما، وتُنقل من وجه إلى وجه حتى تبلغ الفهم. فاللفظ يجمع البيان وتعدد طرائقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص557–558، تحت «سر استعمال مفردة نصرف بدلًا من نفصل أو نبين»","url":""}]},{"id":"s6-765","number":765,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿وليقولوا درست﴾، فجعل قول المعاندين غاية لتصريف الآيات؟","answer":"اللام للعاقبة لا لأن قولهم غرض محبوب؛ فتصريف الآيات يؤدي، مع عنادهم، إلى أن يقولوا ﴿درست﴾، بينما يؤدي عند أهل العلم إلى البيان والهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص559–560، تحت «معنى اللام في وليقولوا درست»","url":""}]},{"id":"s6-766","number":766,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما بلاغة التعبير بمفردة ﴿درست﴾؟","answer":"حكت اللفظة شبهة المعاندين بأن النبي قرأ الأخبار وتعلمها من غيره، فجاءت قصيرة كاشفة لطبيعة اتهامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص561، تحت عنوان «بلاغة التعبير بمفردة درس»","url":""}]},{"id":"s6-1308","number":1308,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"كيف توجه القراءات القرآنية في لفظ ﴿درست﴾؟","answer":"قراءة ﴿دَرَسْتَ﴾ تعني قرأت وتعلمت، و﴿دارست﴾ تعني ذاكرت غيرك، و﴿دَرَسَتْ﴾ تعني قدمت وعفت آثارها؛ فتكشف وجوه شبهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص561–562، تحت عنوان «توجيه القراءات القرآنية في درست»","url":""}]},{"id":"s6-767","number":767,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما موقع جملة ﴿وليقولوا درست﴾ بين ما قبلها وما بعدها؟","answer":"جاءت بين تصريف الآيات وبيانها لتكشف أن مادة واحدة تقيم الحجة للمنصف، ويتخذها المعاند شبهة يصرف بها الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص562، تحت عنوان «موقع جملة وليقولوا درست بين السابقة واللاحقة»","url":""}]},{"id":"s6-1309","number":1309,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما معنى اللام، وما الفرق بينها في ﴿وليقولوا درست﴾ و﴿ولنبينه لقوم يعلمون﴾؟","answer":"الأولى لام العاقبة أو التعليل بحسب التوجيه، فقولهم نتيجة عنادهم، والثانية لام الغرض الصريح؛ إذ المقصود بيان الآيات لأهل العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص562–563، تحت عنوان «معنى اللام والتفريق بينهما في الموضعين»","url":""}]},{"id":"s6-768","number":768,"surah":6,"verses":[106],"references":[{"surah":6,"verses":[106]}],"verseLabel":"الأنعام: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿اتبع ما أوحي إليك﴾، دون أن يقال: اتبع القرآن؟","answer":"الوحي أعم من اسم القرآن من جهة ما يبلغه الله لنبيه، وفي التعبير تأكيد مصدر التكليف ووجوب اتباع كل ما أوحاه ربه، لا التعامل معه بوصفه كلامًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص573، تحت «نكتة إيثار لفظ الإيحاء على الإنزال»","url":""}]},{"id":"s6-769","number":769,"surah":6,"verses":[106],"references":[{"surah":6,"verses":[106]}],"verseLabel":"الأنعام: 106","question":"ما وظيفة جملة ﴿لا إله إلا هو﴾ بين الأمر باتباع الوحي والأمر بالإعراض عن المشركين؟","answer":"هي اعتراض يؤكد الوحدانية ويزيد تقريرها؛ فالمعبود الحق واحد، ووحيه هو المتبع. وإيرادها بين الأمرين يرسخ اتباع الوحي والإعراض عما يناقض التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص574، تحت «غرض إيراد لا إله إلا هو بين الأمرين»","url":""}]},{"id":"s6-770","number":770,"surah":6,"verses":[106],"references":[{"surah":6,"verses":[106]}],"verseLabel":"الأنعام: 106","question":"ما غرض الأمر في قوله تعالى: ﴿وأعرض عن المشركين﴾؟","answer":"الغرض تثبيت الرسول على الوحي وترك الالتفات إلى عناد المشركين ومطالبهم التعنتية بعد قيام البيان، لا ترك دعوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص575، تحت عنوان «غرض الأمر في وأعرض»","url":""}]},{"id":"s6-1310","number":1310,"surah":6,"verses":[106],"references":[{"surah":6,"verses":[106]}],"verseLabel":"الأنعام: 106","question":"ما بلاغة إيثار الأمر بالإعراض بدل النهي عن طاعة المشركين؟","answer":"الأمر بالإعراض أبلغ في قطع الالتفات إلى شبهاتهم وأذاهم، ويصور المضي في طريق الوحي دون اشتغال بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص575–576، تحت عنوان «بلاغة إيثار الأمر بالإعراض دون النهي عن طاعة المشركين»","url":""}]},{"id":"s6-771","number":771,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"ما المعنى الإجمالي لقوله تعالى: ﴿ولو شاء الله ما أشركوا﴾؟","answer":"الله قادر على منع الشرك لو شاء أن يخلقهم مجبرين على الإيمان، لكنه كلفهم مع الاختيار؛ فوقع شركهم باختيارهم تحت مشيئته الكونية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص578، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1311","number":1311,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"ما مقصد عطف ﴿ولو شاء الله ما أشركوا﴾ على الأمر بالإعراض؟","answer":"سلّى الرسول بأن الله قادر على منع شركهم، وأن مهمته البلاغ لا حملهم على الإيمان قهرًا، فليمض في اتباع الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص579، تحت عنوان «مقصد عطف ولو شاء الله ما أشركوا على الأمر بالإعراض»","url":""}]},{"id":"s6-772","number":772,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"ما الفرق بين الحفيظ والوكيل؟","answer":"الحفيظ يراقب ويحفظ من المخالفة، والوكيل يتولى شؤون غيره ومصالحه؛ ولكل لفظ جهة خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص552–553، تحت عنوان «الفروق المعجمية: الحفيظ والوكيل»","url":""}]},{"id":"s6-1312","number":1312,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"ما سر الجمع بين نفي كون الرسول حفيظًا ووكيلًا؟","answer":"نفى أن يكون رقيبًا يجبرهم أو متوليًا لنتائج اختيارهم؛ فوظيفته البلاغ، وكل نفس تتحمل عملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص584، تحت عنوان «سر الجمع بين نفي كونه حفيظًا ووكيلًا»","url":""}]},{"id":"s6-773","number":773,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"لماذا تكرر ﴿عليهم﴾ في الجملتين؟","answer":"تكرار ﴿عليهم﴾ يثبت استقلال النفيين ويقوي تعلق كل من الحفظ والوكالة بالمشركين؛ فلا هو حفيظ عليهم، ولا هو وكيل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص583، تحت «نكتة تكرار وما وعليهم للتوكيد»","url":""}]},{"id":"s6-774","number":774,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما المعنى الإجمالي للنهي عن سب معبودات المشركين؟","answer":"نهي المسلمون عن سبها لأن ذلك يفضي إلى مفسدة أعظم، وهي سب المشركين لله بجهل وعدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص586–587، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1313","number":1313,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما أغراض النهي في قوله تعالى: ﴿ولا تسبوا﴾؟","answer":"جاء للإرشاد الملزم إلى مراعاة المآلات وسد الذريعة، وتهذيب خطاب الدعوة حتى لا يقود إلى زيادة المنكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص588–589، تحت عنوان «أغراض النهي في ولا تسبوا»","url":""}]},{"id":"s6-775","number":775,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما فائدة استعمال الاسم الموصول في قوله تعالى: ﴿الذين يدعون من دون الله﴾؟","answer":"جمع كل ما اتخذوه معبودًا من دون الله ولم يقصر النهي على صنف بعينه، وعرّفهم بفعل عابديهم الذي هو موطن الإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص591–592، تحت عنوان «فائدة استعمال الاسم الموصول»","url":""}]},{"id":"s6-1314","number":1314,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما دلالة حذف مفعول ﴿يدعون﴾؟","answer":"أفاد الحذف العموم، ويقدر العائد: الذين يدعونهم؛ فشمل كل ما يدعونه من دون الله مع إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص592–593، تحت عنوان «دلالة حذف مفعول يدعون»","url":""}]},{"id":"s6-776","number":776,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"لماذا كانت النتيجة: ﴿فيسبوا الله عدوًا بغير علم﴾؟","answer":"الفاء تبين سببية المفسدة وترتبها: إذا سُبت معبوداتهم حملهم التعصب والجهل على مقابلة السب بسب الله، فالنهي يسد هذا الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص593، تحت «دلالة الفاء في فيسبوا»","url":""}]},{"id":"s6-777","number":777,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما الذي يضيفه وصف السب بأنه ﴿عدوًا﴾ في ﴿فيسبوا الله عدوًا بغير علم﴾؟","answer":"﴿عدوًا﴾ مصدر يدل على تجاوز الحد من الحق إلى الباطل؛ فوصف به سبهم ليكشف أنه اعتداء وجور، وليس ردًا يملكون به حقًا. وفيه تقبيح لفعلهم وتعريض بفساد موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص594–595، تحت «فن التعريض في عدوًا»","url":""}]},{"id":"s6-778","number":778,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما دلالة إسناد فعل التزيين إلى الضمير العائد على الله تعالى؟","answer":"الإسناد إلى سنته ومشيئته في الخلق؛ فقد خلق في النفوس الاستحسان وترك المعاندين لاختيارهم بعد قيام الحجة، ولا يعني أنه أمر بالباطل أو رضي به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص596–597، تحت عنوان «دلالة إسناد فعل التزيين إلى الضمير العائد على الله تعالى»","url":""}]},{"id":"s6-1315","number":1315,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما مفهوم الأمم بين خصوص الكافرين والعموم في قوله تعالى: ﴿لكل أمة عملهم﴾؟","answer":"يشمل اللفظ الأمم من حيث خضوعها لسنة استحسان ما ألفته، والسياق يخص الكافرين بالذم لأنهم استمروا على الباطل بعد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص597–598، تحت عنوان «مفهوم الأمم بين خصوص الكافرين والعموم»","url":""}]},{"id":"s6-779","number":779,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم إلى ربهم مرجعهم﴾ بتقديم ﴿إلى ربهم﴾؟","answer":"تقديم ﴿إلى ربهم﴾ يفيد الاختصاص والتهديد: لا مرجع لهم في النهاية إلا إلى ربهم الذي يعلم أعمالهم ويحكم بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص600، تحت «نكتة تقديم الجار والمجرور على المسند إليه»","url":""}]},{"id":"s6-780","number":780,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما دلالة استعمال ﴿فينبئهم﴾ دون مرادفاته في قوله تعالى: ﴿فينبئهم بما كانوا يعملون﴾؟","answer":"الإنباء إخبار بأمر عظيم الشأن تظهر به حقيقة ما عملوه وعاقبته؛ فليس مجرد إعلام، بل كشفٌ مقرون بالتقريع والجزاء يوم الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص602، تحت عنوان «دلالة استعمال مفردة (الإنباء) دون مرادفاتها»","url":""}]},{"id":"s6-1316","number":1316,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"لماذا قيل ﴿بما كانوا يعملون﴾ ولم يقل: «بأعمالهم»؟","answer":"أبرز الموصولُ والفعلُ أعمالهم مفصلةً متجددة، ودلت ﴿كانوا﴾ على رسوخها واستمرارها؛ فالتعبير أبلغ في إحاطة العلم بها وفي إقامة الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص603، تحت عنوان «نكتة التعبير بقوله ﴿بما كانوا يعملون﴾ دون (بأعمالهم)»","url":""}]},{"id":"s6-781","number":781,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿وأقسموا بالله جهد أيمانهم﴾، وما صورة بذل الجهد في اليمين؟","answer":"الجهد غاية الطاقة والمبالغة؛ أي بالغوا في توكيد أيمانهم حتى بذلوا أقصى ما يعرفونه من الحلف، مع أن امتناعهم لم يكن لنقص الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص608–609، تحت «فن الإطناب في جهد أيمانهم»","url":""}]},{"id":"s6-782","number":782,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما بلاغة تقييد الإيمان بالآية في قوله تعالى: ﴿ليؤمنن بها﴾؟","answer":"قيّدوا الإيمان بالآية المقترحة بعينها، لا بمطلق دلائل الله؛ فكشف القيد أن دعواهم معلقة على طلب مخصوص، لا ناشئة عن تجرد لاتباع الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص611، تحت عنوان «بلاغة تقييد الإيمان بالآية»","url":""}]},{"id":"s6-783","number":783,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما غرض القصر في قوله تعالى: ﴿إنما الآيات عند الله﴾؟","answer":"قصر أمر الآيات على الله وحده؛ فهو الذي يملك إنزالها ويختارها بحكمته، وليس للنبي ولا للمقترحين التحكم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص611، تحت عنوان «غرض القصر في إنما الآيات»","url":""}]},{"id":"s6-1317","number":1317,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما بلاغة المجاز المرسل في قوله تعالى: ﴿الآيات عند الله﴾؟","answer":"ليست العندية مكانية، وإنما هي مجاز عن الاختصاص والاستئثار بالقدرة والعلم؛ أي إن أمر الآيات وإنزالها مختص بالله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص612، تحت عنوان «بلاغة المجاز المرسل في الآيات عند الله»","url":""}]},{"id":"s6-784","number":784,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما سرّ التعبير بالشعور في ﴿وما يشعركم﴾؟","answer":"الإشعار إعلام بأمر خفي دقيق؛ والآية تكشف ما تخفيه نفوس المقترحين من العناد وراء ظاهر أيمانهم. فناسب الشعورُ أمرًا لا يطلع عليه الناس من سرائرهم، وإنما يعلمه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص613، تحت «سر التعبير بالشعور في يشعركم»","url":""}]},{"id":"s6-785","number":785,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"لماذا قيل ﴿إذا جاءت لا يؤمنون﴾ بعد حكاية قولهم ﴿لئن جاءتهم آية ليؤمنن بها﴾؟","answer":"حُكي اقتراحهم بـ﴿إن﴾ التي تعرض المجيء على وجه الاحتمال، ثم جاء الرد بـ﴿إذا﴾؛ فحتى مع فرض تحقق مجيء الآية لا يؤمنون. وبذلك يقطع تعلقهم باحتمال نزول الآية ذريعة لتأخير الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص614، تحت «نكتة استعمال إذا دون إن»","url":""}]},{"id":"s6-786","number":786,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما المعنى الإجمالي لقوله تعالى: ﴿ونقلب أفئدتهم وأبصارهم كما لم يؤمنوا به أول مرة﴾؟","answer":"يبين السياق أن المعاندين، لما أعرضوا عن الإيمان أول مرة، يعاقبون بصرف قلوبهم وأبصارهم عن الانتفاع بالحق، ويتركون في طغيانهم مترددين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص621، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1318","number":1318,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما بلاغة المجاز في قوله تعالى: ﴿ونقلب أفئدتهم وأبصارهم﴾؟","answer":"صوّر صرف القلوب والأبصار عن إدراك الحق بالتقليب؛ فاستحضر اضطرابهم وتحولهم من حال إلى حال من غير استقرار على هدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص622–623، تحت عنوان «بلاغة المجاز في ونقلب أفئدتهم وأبصارهم»","url":""}]},{"id":"s6-787","number":787,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما سرّ تقديم الأفئدة على الأبصار؟","answer":"قُدّمت الأفئدة لأنها محل الفهم والقصد والتصديق، ثم الأبصار لأنها طريق مشاهدة الآيات؛ ففساد الباطن أصلٌ في عدم الانتفاع بالمشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص622–623، تحت «نكتة تقديم الأفئدة على الأبصار»","url":""}]},{"id":"s6-788","number":788,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"لماذا أُضمر ما لم يؤمنوا به في ﴿كما لم يؤمنوا به أول مرة﴾ بدل التصريح باسمه؟","answer":"المقصود القرآن، وهو معلوم حاضر في الكلام وعظيم الشأن فلا يخفى المراد بالإشارة إليه. وفي الإضمار توبيخ لهم: أعرضوا عن الدليل الذي كان ينبغي أن يبادروا إلى الإيمان به من أول سماعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص624–625، تحت «بلاغة إضمار التصريح بالمؤمن به»","url":""}]},{"id":"s6-789","number":789,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ونذرهم في طغيانهم يعمهون﴾، فجعل الطغيان ظرفًا؟","answer":"جُعل الطغيان ظرفًا محيطًا بهم لتصوير استغراقهم فيه، فهم متروكون داخله يتحيرون لا يهتدون إلى مخرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص626–627، تحت «بلاغة المجاز في استعمال حرف في»","url":""}]},{"id":"s6-790","number":790,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما العلاقة بين الطغيان والعمه، وما أثرها في تصوير تمكن ضلال المشركين؟","answer":"الطغيان تجاوز الحد والإمعان في العصيان، والعمه حيرة البصيرة الناشئة عنه؛ فجمعهما يصور سبب الضلال وأثره، مع استمرارهم مترددين فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص627–628، تحت عنوان «العلاقة بين الطغيان والعمه وأثرها في تصوير تمكن ضلال المشركين»","url":""}]},{"id":"s6-1319","number":1319,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما الفرق بين العمه والحيرة؟","answer":"العمه حيرة في البصيرة والرأي تجعل صاحبها يتردد في الضلال، والحيرة أعم من ذلك؛ فاختير العمه لتصوير عمى القلب واضطراب صاحبه عن الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص628–629، تحت عنوان «الفروق المعجمية: العمه والحيرة»","url":""}]},{"id":"s6-791","number":791,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"لماذا ترتبت الآيات المفترضة من نزول الملائكة إلى كلام الموتى ثم حشر كل شيء؟","answer":"جاء الترتيب في تصاعد: فنزول الملائكة آية عظيمة، ثم كلام الموتى الذين يعرفونهم أبلغ في المشافهة، ثم حشر كل شيء يجمع أقصى ما يتصورونه من الشواهد. ومع هذا الفرض البالغ يبقى عنادهم مانعًا من الإيمان إلا أن يشاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص642–643، تحت «بلاغة ترتيب الجمل الثلاث في الآية»","url":""}]},{"id":"s6-792","number":792,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿نزلنا إليهم الملائكة﴾ بتشديد الفعل؟","answer":"التشديد في ﴿نزّلنا﴾ يفيد التكثير أو التدرج؛ أي لو أنزلت الملائكة إنزالًا ظاهرًا متكررًا كما اقترحوا، لما حملهم ذلك على الإيمان مع عنادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص637، تحت «سر التعبير بصيغة التنزيل لا الإنزال»","url":""}]},{"id":"s6-793","number":793,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"لماذا أُسند التكليم إلى الموتى في ﴿وكلمهم الموتى﴾ مع إسناد التنزيل والحشر إلى الله؟","answer":"لأن مقترحهم كان أن يشافههم أموات يعرفونهم ويشهدوا لهم بصدق الرسول؛ فأبرز إسناد التكليم إلى الموتى نفس الصورة التي طلبوها، بدل الاكتفاء بذكر إحيائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص638–639، تحت «سر إسناد التكليم إلى الموتى لا إلى الله»","url":""}]},{"id":"s6-794","number":794,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما سر التعبير بالحشر لا بالجمع في قوله تعالى: ﴿وحشرنا عليهم كل شيء﴾؟","answer":"الحشر جمعٌ مع سوق وإزعاج إلى جهة واحدة، فهو أبلغ من مطلق الجمع في تصوير إحضار كل شيء عليهم وإحاطته بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص640–641، تحت عنوان «سر التعبير بالحشر لا بالجمع»","url":""}]},{"id":"s6-1320","number":1320,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما دلالة تعدية فعل الحشر بحرف ﴿على﴾؟","answer":"أفادت ﴿على﴾ الاستعلاء والإحاطة؛ فكأن المحشورات تتوارد عليهم من فوق وتحيط بهم، وفي ذلك تقوية لصورة العجز عن الإفلات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص641، تحت عنوان «دلالة تعدية فعل الحشر بحرف على»","url":""}]},{"id":"s6-1321","number":1321,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"كيف توجَّه القراءات القرآنية في قوله تعالى: ﴿قُبُلًا﴾؟","answer":"تتنوع دلالة القراءة بين المقابلة والمعاينة، وبين معنى الجماعات أو الكفلاء؛ فتلتقي الوجوه في تصوير مجيء الأشياء مواجهةً لهم وعلى أتم أنحاء الشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص644، تحت عنوان «توجيه القراءات القرآنية»","url":""}]},{"id":"s6-1322","number":1322,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما بلاغة اختيار مفردة ﴿قُبُلًا﴾ في الدلالة على المقصود؟","answer":"اختيرت لتصور حضور الأشياء قبالتهم وعيانًا، فلا يبقى عذر ناشئ عن خفاء الدليل أو بعده، ومع ذلك لا يقع إيمانهم إلا بمشيئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص644–645، تحت عنوان «بلاغة اختيار مفردة قبلا»","url":""}]},{"id":"s6-795","number":795,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كانوا ليؤمنوا﴾ باللام؟","answer":"لام الجحود بعد ﴿ما كانوا﴾ تفيد شدة انتفاء الإيمان وعدم استقامتِه منهم مع رسوخ العناد؛ أي لم يكن من شأنهم أن يؤمنوا بهذه المقترحات إلا أن يشاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص645، تحت «فائدة التعبير بقوله تعالى: ﴿ما كانوا ليومنوا﴾»","url":""}]},{"id":"s6-796","number":796,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"لماذا استثنى: ﴿إلا أن يشاء الله﴾؟","answer":"الاستثناء يرد الأمر كله إلى مشيئة الله النافذة؛ فنفي إيمانهم معلق بحال عنادهم، ولا يعجز الله أن يخلق الإيمان فيهم أو يوفق من يشاء منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص646–647، تحت «معنى الاستثناء في إلا أن يشاء الله»","url":""}]},{"id":"s6-797","number":797,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما الجهل الذي تكشفه خاتمة ﴿ولكن أكثرهم يجهلون﴾ مع كثرة ما يقترحونه من الآيات؟","answer":"هو الجهل بحقيقة الهداية وبالله وقدرته وحكمته؛ فلا تنفع كثرة المقترحات من لا يعرف هذه الحقيقة. وقد يكون الإنسان عالمًا بأمور الدنيا مع بقائه جاهلًا بما يوصله إلى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص650–651، تحت «غرض التعبير بمفردة يجهلون»","url":""}]},{"id":"s6-798","number":798,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما المعنى الإجمالي لقوله تعالى: ﴿وكذلك جعلنا لكل نبي عدوًا شياطين الإنس والجن﴾؟","answer":"تقرر الآية سنة الابتلاء: يكون لكل نبي أعداء من مردة الإنس والجن، يزيّن بعضهم لبعض القول الباطل؛ وفي ذلك تسلية للنبي وتثبيت له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص654، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-799","number":799,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما بلاغة استعمال مفردة ﴿عدوًّا﴾ دون «أعداء»؟","answer":"جاء ﴿عدوًّا﴾ مفردًا على إرادة الجنس، فشمل كل صور العداوة وأهلها، وصوّرهم مع كثرتهم كأنهم كتلة واحدة في معاداة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص657، تحت عنوان «بلاغة استعمال مفردة عدوا دون أعداء»","url":""}]},{"id":"s6-1323","number":1323,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما سر إفراد لفظ ﴿عدوًّا﴾ ومجيء ﴿شياطين﴾ جمعًا؟","answer":"وحّد الإفراد حقيقة العداوة وغايتها، بينما كشف جمع ﴿شياطين﴾ كثرة أفرادها وتنوعهم من الإنس والجن؛ فاتحد المقصد وتعدد القائمون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص658، تحت عنوان «سر إفراد لفظ عدوا ومجيء شياطين جمعا»","url":""}]},{"id":"s6-800","number":800,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما سرّ تقديم شياطين الإنس على الجن؟","answer":"قُدّم شياطين الإنس لأن عداوتهم أشد ظهورًا ومباشرةً للرسل، ولأن السياق يتحدث عن مجرمي البشر الذين يصدون عن الدعوة، ثم أُلحق بهم شياطين الجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص659، تحت «نكتة تقديم الإنس على الجن»","url":""}]},{"id":"s6-801","number":801,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"لماذا عبّر عن تواصلهم بقوله: ﴿يوحي بعضهم إلى بعض﴾؟","answer":"الوحي إلقاء خفي سريع؛ فاستعير لتناقلهم الباطل سرًا، بعضهم يمد بعضًا بوسائل التضليل كما يوحى الكلام الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص660–661، تحت «بلاغة اختيار مفردة يوحي»","url":""}]},{"id":"s6-802","number":802,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما بلاغة التعبير المجازي في قوله تعالى: ﴿زخرف القول﴾؟","answer":"نقل الزخرف من تزيين الأجسام إلى تزيين الكلام؛ فدل على قول يلمع ظاهره ويستحسن لفظه، مع فساد حقيقته ومقصده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص661–662، تحت عنوان «بلاغة التعبير المجازي»","url":""}]},{"id":"s6-1324","number":1324,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿زخرف القول﴾؟","answer":"شُبّه القول الباطل بشيء مزخرف حسن الظاهر يخفي رداءة باطنه، فصورت الاستعارة طريقة الشياطين في تمويه الباطل وإغرائه للسامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص662–663، تحت عنوان «بلاغة الاستعارة في زخرف القول»","url":""}]},{"id":"s6-803","number":803,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما الذي يكشفه لفظ ﴿غرورًا﴾ عن غاية ﴿زخرف القول﴾؟","answer":"يكشف أن تزيين القول وسيلة للخداع؛ فإما أن المعنى أنهم يوحي بعضهم إلى بعض ليغروا الناس، وإما أنه إيحاء قائم على التغرير. وفي الوجهين لا تنفصل الزينة الظاهرة عن قصد الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص663، تحت «إعراب غرورا وأثره في بيان المعنى»","url":""}]},{"id":"s6-804","number":804,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما نكتة المجيء بعنوان الربوبية دون الألوهية في قوله تعالى: ﴿ولو شاء ربك﴾؟","answer":"ناسبت الربوبية مقام التسلية والرعاية؛ فهي تذكّر النبي بأن ربه يتولاه بالتربية والحفظ، وأن ما يقع من العداوة جارٍ بحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص664، تحت عنوان «نكتة المجيء بعنوان الربوبية دون الألوهية»","url":""}]},{"id":"s6-1325","number":1325,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما غرض إضافة الرب إلى ضمير المخاطب في قوله تعالى: ﴿ربك﴾؟","answer":"الإضافة تشريف وتطمين وإظهار لعناية خاصة بالنبي؛ فربه الذي يرعاه قادر على منع أعدائه، وإنما يمهلهم لحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص665، تحت عنوان «غرض إضافة الرب إلى ضمير المخاطب»","url":""}]},{"id":"s6-805","number":805,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما غرض الأمر في قوله تعالى: ﴿فذرهم﴾؟","answer":"ليس أمرًا بترك دعوتهم مطلقًا، بل هو تهديد وإعراض عن جدال المعاندين بعد البلاغ، مع تفويض أمرهم وجزائهم إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص667، تحت عنوان «غرض الأمر»","url":""}]},{"id":"s6-806","number":806,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتصغى إليه أفئدة﴾، فصوّر القلوب تميل؟","answer":"أصل الصغو الميل؛ فصوّر القلوب مائلة نحو زخرف القول لاستحسانه وقبوله، وفي الصورة كشف لانحرافها عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص674–675، تحت «سر التعبير بمفردة ولتصغى»","url":""}]},{"id":"s6-807","number":807,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما معنى ﴿أفئدة﴾ في قوله تعالى: ﴿ولتصغى إليه أفئدة الذين لا يؤمنون بالآخرة﴾؟","answer":"الأفئدة جمع فؤاد، وهو القلب من جهة تأثره وتوقد مشاعره؛ والمقصود هنا قلوبهم التي تميل إلى زخرف القول وتقبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص671–672، تحت عنوان «شرح المفردات: أفئدة»","url":""}]},{"id":"s6-1326","number":1326,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما الفرق بين الفؤاد والقلب؟","answer":"يبرز الفؤاد جانب المشاعر والوجدان المتوقد، بينما يبرز القلب جهة التقلب والإدراك والتفكير؛ فاختير الفؤاد هنا لميلهم النفسي إلى القول المزخرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص681، تحت عنوان «الفروق المعجمية: الفؤاد والقلب»","url":""}]},{"id":"s6-808","number":808,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"لماذا قُيدوا بـ﴿الذين لا يؤمنون بالآخرة﴾؟","answer":"خُصوا لأن الإيمان بالآخرة يردع القلب عن الاغترار بالباطل خوف الحساب؛ فمن أنكرها خلا من هذا الرادع فمال إلى الزخرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص677–678، تحت «فائدة ذكر قيد بالآخرة والاقتصار عليه»","url":""}]},{"id":"s6-809","number":809,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"لماذا ترتبت الأفعال: ﴿لتصغى... وليرضوه... وليقترفوا﴾ بهذا الترتيب؟","answer":"التدرج يرسم طريق الضلال: تميل القلوب أولًا إلى الزخرف، ثم ترضاه بعد الميل، ثم تتحول القناعة إلى اقتراف فعلي للذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص675–676، تحت «دلالة ترتيب الأفعال»","url":""}]},{"id":"s6-810","number":810,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما نكتة التعبير بالجملة الاسمية في قوله تعالى: ﴿هم مقترفون﴾؟","answer":"أفادت الجملة الاسمية ثبوت الاقتراف ورسوخه فيهم، لا وقوع فعل عابر؛ فناسبت إصرارهم على اكتساب الإثم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص679، تحت عنوان «نكتة التعبير بالجملة الاسمية»","url":""}]},{"id":"s6-1327","number":1327,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما بلاغة جناس الاشتقاق بين ﴿ليقترفوا﴾ و﴿مقترفون﴾؟","answer":"جمع اللفظين أصل اشتقاقي واحد، فربط الغاية بالفعل المتحقق منهم، وأكّد بتآلف الصوت والمعنى أنهم ماضون في اقتراف ما اختاروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص680، تحت عنوان «جناس الاشتقاق»","url":""}]},{"id":"s6-811","number":811,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿أفغير الله أبتغي حكمًا﴾ بتقديم ﴿غير الله﴾؟","answer":"قُدّم ﴿غير الله﴾ ليقع عليه الإنكار والحصر: أأطلب سواه حكمًا؟ فالمقصود نفي التحاكم إلى غيره مع قيام الدليل على انفراده بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص686–687، تحت «نكتة تقديم أفغير على الفعل أبتغي»","url":""}]},{"id":"s6-812","number":812,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"لماذا اختير ﴿حكمًا﴾، لا: حاكمًا؟","answer":"الحَكَم أبلغ من الحاكم، إذ يدل على من يصلح أن يُرجع إليه في الفصل ويرضى بحكمه، ويقتضي العدل؛ أما الحاكم فقد يعدل وقد يجور. فناسب المقام الذي يقرر انفراد الله بالحكم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص687–688، تحت «سر التعبير بصيغة حكما لا حاكما»","url":""}]},{"id":"s6-813","number":813,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما معنى ﴿مفصلًا﴾ في قوله تعالى: ﴿وهو الذي أنزل إليكم الكتاب مفصلًا﴾؟","answer":"أي مبينًا مميزًا بعضه من بعض، فُصلت فيه الأحكام والدلائل والحق من الباطل بما يغني عن طلب حكم غير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص683–684، تحت عنوان «شرح المفردات: مفصلا»","url":""}]},{"id":"s6-1328","number":1328,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما المعنى الإجمالي لقوله تعالى: ﴿أفغير الله أبتغي حكمًا وهو الذي أنزل إليكم الكتاب مفصلًا﴾؟","answer":"ينكر أن يطلب النبي حكمًا غير الله، وقد أنزل الكتاب واضحًا مفصلًا، وأهل الكتاب يعلمون أنه منزل بالحق؛ فلا موضع للارتياب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص685، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-814","number":814,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما غرض التأكيد في قوله تعالى: ﴿أنه منزل من ربك بالحق﴾؟","answer":"أكد الخبر بـ﴿أن﴾ لمواجهة الإنكار وتثبيت أن مصدر الكتاب هو الله وأن نزوله ملتبس بالحق، مع قيام شهادة أهل الكتاب بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص695، تحت عنوان «غرض التأكيد أنه منزل»","url":""}]},{"id":"s6-815","number":815,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما دلالة الالتفات في قوله تعالى: ﴿فلا تكونن من الممترين﴾؟","answer":"انتقل من الحديث عن أهل الكتاب إلى خطاب النبي مباشرة، فجدّد نشاط السامع وقوى معنى التثبيت واليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص697، تحت عنوان «دلالة الالتفات»","url":""}]},{"id":"s6-1329","number":1329,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما غرض النهي في قوله تعالى: ﴿فلا تكونن من الممترين﴾؟","answer":"النهي للتثبيت والدوام على اليقين، لا لوقوع الشك من النبي؛ وفيه تقوية للحجة بعد شهادة أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص698، تحت عنوان «غرض النهي»","url":""}]},{"id":"s6-1330","number":1330,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما بلاغة التعريض في قوله تعالى: ﴿فلا تكونن من الممترين﴾؟","answer":"وُجه الخطاب إلى النبي وهو منزّه عن الشك، والمراد التعريض بالممترين وتحذير غيره؛ فإذا نُهي الكامل كان غيره أولى بالحذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص699، تحت عنوان «بلاغة التعريض»","url":""}]},{"id":"s6-816","number":816,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما فائدة نون التوكيد في ﴿فلا تكونن من الممترين﴾ بعد شهادة أهل الكتاب بصدق التنزيل؟","answer":"جاء التوكيد لتثبيت الخبر السابق: أنهم يعلمون أنه منزل من الله بالحق؛ فثبوت هذه الحقيقة يقتضي القطع بها وترك الامتراء. ويقوى بذلك التعريض بمن يجادل في القرآن مع وضوح حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص700، تحت «دلالة التوكيد في قوله تعالى: فلا تكونن من الممترين»","url":""}]},{"id":"s6-817","number":817,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما المعنى الإجمالي لقوله تعالى: ﴿وتمت كلمة ربك صدقًا وعدلًا﴾؟","answer":"بلغ كلام الله غايته في الصدق فيما أخبر ووعد، وفي العدل فيما حكم وأمر؛ فلا مبدل لكلماته وهو السميع العليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص703، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1331","number":1331,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما سر استعمال ﴿وتمت﴾ دون «كملت»؟","answer":"كلمة الله كاملة في ذاتها أزلًا، ثم تواصل نزولها حتى تم إبلاغها للناس بلا انقطاع؛ فاختير التمام لبلوغ الغاية واتصال النزول، لا لإفادة زوال نقص سابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص704، تحت عنوان «سر استعمال وتمت دون كملت»","url":""}]},{"id":"s6-1332","number":1332,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما معنى ﴿وتمت﴾ بين الحقيقة والمجاز؟","answer":"يستعمل التمام حقيقةً في وفرة أجزاء الشيء وبلوغها حدها، ويستعار لتحقق الوعد وظهور صدقه؛ فتدل الآية على استيفاء الكلمة كمالها ووقوع مضمونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص705، تحت عنوان «معنى وتمت بين الحقيقة والمجاز»","url":""}]},{"id":"s6-818","number":818,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما توجيه المخصوص بالذكر في قوله تعالى: ﴿صدقًا وعدلًا﴾؟","answer":"خص الصدق والعدل لأن كلام الله يدور على الأخبار والمواعيد وهي صدق، وعلى الأحكام والأوامر وهي عدل؛ فاستوعب الوصفان مقاصد الكلمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص707، تحت عنوان «توجيه المخصوص بالذكر في قوله تعالى: صدقًا وعدلًا»","url":""}]},{"id":"s6-1333","number":1333,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما بلاغة مراعاة النظير بين لفظي ﴿صدقًا﴾ و﴿عدلًا﴾؟","answer":"قرن اللفظان المتناسبان؛ فالصدق كمال الخبر، والعدل كمال الحكم، فجمعهما في نسق واحد يبرز تمام كلمة الله في جانبيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص707–708، تحت عنوان «مراعاة النظير بين لفظي صدقا وعدلا»","url":""}]},{"id":"s6-819","number":819,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما سرّ تقديم الصدق على العدل؟","answer":"لأن الاقتناع بالحجة يسبق العمل بالحكم؛ فإذا ثبت صدق القرآن وأنه من عند الله، ثبتت عدالة أحكامه. فجاء الصدق أولًا لبناء اليقين الذي يُقبل به التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص708، تحت «نكتة تقديم الصدق على العدل»","url":""}]},{"id":"s6-820","number":820,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما نكتة إفراد ﴿الكلمة﴾ في قوله تعالى: ﴿وتمت كلمة ربك﴾؟","answer":"أفاد الإفراد أن كلمات الله، على كثرتها، تنتظم في وحدة لا تناقض فيها، وتصدر عن أمر واحد محكم؛ فكأنها كلمة واحدة في الاتساق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص705–706، تحت عنوان «نكتة إفراد الكلمة»","url":""}]},{"id":"s6-1334","number":1334,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"كيف توجَّه القراءات القرآنية في قوله تعالى: ﴿كلمة﴾؟","answer":"قراءة الإفراد تحمل الكلمة على الجنس أو الوحدة الجامعة، وقراءة الجمع تراعي تعدد كلمات الله؛ والمعنيان يلتقيان في تمامها وصدقها وعدلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص706، تحت عنوان «توجيه القراءات القرآنية في قوله تعالى: كلمت»","url":""}]},{"id":"s6-821","number":821,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"لماذا خُتمت بـ﴿وهو السميع العليم﴾؟","answer":"﴿السميع﴾ يناسب أقوال المكذبين ومحاولات التحريف، و﴿العليم﴾ يحيط بأحوالهم ونياتهم وبصدق كلماته؛ فلا يخفى عليه قول ولا باعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص712–713، تحت «بلاغة جملة التذييل: وهو السميع العليم»","url":""}]},{"id":"s6-822","number":822,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"لماذا حذّر من طاعة ﴿أكثر من في الأرض﴾؟","answer":"حذّر من الأكثرية لأن كثرة أهل الأرض ليست معيارًا للحق؛ فالغالب يومئذ يتبع الشرك والعادات، وطاعته تصرف عن سبيل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص719–720، تحت «دلالة ذكر الأكثرية»","url":""}]},{"id":"s6-823","number":823,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿يضلوك عن سبيل الله﴾، فعُدّي الإضلال بـ﴿عن﴾؟","answer":"تعدية الإضلال بـ﴿عن﴾ تفيد الصرف والإبعاد؛ فكأن سبيل الله طريق مستقيم يحاولون تحويل السائر عنه إلى جهة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص723–724، تحت «بلاغة التمثيل في قوله تعالى: يضلوك عن سبيل الله»","url":""}]},{"id":"s6-824","number":824,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما غرض القصر في قوله تعالى: ﴿إن يتبعون إلا الظن﴾؟","answer":"قصر اتباعهم على الظن بطريق النفي والاستثناء، فنفى أن يكون لهم علم أو حجة، وشدد في كشف فساد مصدر اعتقادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص725، تحت عنوان «غرض القصر في قوله تعالى: إن يتبعون إلا الظن»","url":""}]},{"id":"s6-825","number":825,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما غرض القصر في قوله تعالى: ﴿وإن هم إلا يخرصون﴾؟","answer":"حصر حالهم في الخرص، أي القول بالتخمين من غير علم؛ فليس ما يصدر عنهم تحقيقًا ولا حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص726، تحت عنوان «غرض القصر في وإن هم إلا يخرصون»","url":""}]},{"id":"s6-826","number":826,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما سر التعبير بمفردة الخرص وبالفعل المضارع في قوله تعالى: ﴿يخرصون﴾؟","answer":"الخرص قول مبني على الظن والتقدير لا على العلم، والمضارع يصور تجدده واستمرارهم فيه كلما تكلموا في الدين بغير حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص726–727، تحت عنوان «سر التعبير بمفردة الخرص وبالفعل المضارع»","url":""}]},{"id":"s6-1335","number":1335,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما الفرق بين الخرص والكذب؟","answer":"الخرص حكم بالتخمين من غير علم، فقد يوافق الواقع اتفاقًا أو يخالفه، أما الكذب فهو الإخبار بخلاف الواقع؛ ولما كان قولهم بلا بينة أطلق عليه الخرص.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص728–729، تحت عنوان «الفروق المعجمية: الخرص والكذب»","url":""}]},{"id":"s6-827","number":827,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ربك هو أعلم من يضل﴾ بضمير الفصل؟","answer":"ضمير الفصل ﴿هو﴾ يقصر كمال العلم على الله ويؤكد أن الحكم على الضال والمهتدي ليس للأكثرية ولا للظنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص732، تحت «نكتة استعمال ضمير الفصل هو»","url":""}]},{"id":"s6-828","number":828,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"لماذا قُدّم ذكر علم الله بمن يضل على ذكر علمه بالمهتدين؟","answer":"لأن السياق يعالج الضلال ويحذر من اتباع أهله؛ فجاء البدء بهم أنسب بالمقام. ثم ذُكر المهتدون ليكتمل بيان إحاطة علم الله بالفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص733، تحت «بلاغة تقديم علمه بمن يضل عن سبيله على علمه بالمهتدين»","url":""}]},{"id":"s6-829","number":829,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿من يضل عن سبيله﴾؟","answer":"استعير السبيل للدين الحق، وصُوّر الضال بمسافر حاد عن الطريق الواضح؛ فحوّل الضلال المعنوي إلى مشهد محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص733، تحت عنوان «بلاغة الاستعارة في قوله تعالى: من يضل عن سبيله»","url":""}]},{"id":"s6-1336","number":1336,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"ما بلاغة اختلاف المقابلة بين جملتي ﴿أعلم من يضل﴾ و﴿أعلم بالمهتدين﴾؟","answer":"جاء الضلال فعلًا مضارعًا مفردًا لتجدد طرائقه، وجاءت الهداية اسمًا مجموعًا لثبات أهلها؛ وذُكر السبيل مع الضلال لكثرة سبله، بينما سبيل الهدى واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص734، تحت عنوان «بلاغة اختلاف المقابلة بين جملتي أعلم من يضل وأعلم بالمهتدين»","url":""}]},{"id":"s6-830","number":830,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"لماذا عُدّي العلم في الأولى بلا باء وفي الثانية ﴿بالمهتدين﴾؟","answer":"يذكر المصدر أن في ﴿أعلم من يضل﴾ إيجازًا بالحذف: إما حذف الباء، أي أعلم بمن يضل، وإما تقدير فعل يعلم تعلق به ﴿من يضل﴾. ثم جاء ﴿بالمهتدين﴾ مصرحًا بالباء؛ فاختلف التعبير مع بقاء إحاطة العلم بالفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص732–733، تحت «بلاغة الإيجاز بالحذف في قوله تعالى: أعلم من يضل»","url":""}]},{"id":"s6-831","number":831,"surah":6,"verses":[118],"references":[{"surah":6,"verses":[118]}],"verseLabel":"الأنعام: 118","question":"لماذا فُرع الأمر بالأكل بالفاء: ﴿فكلوا مما ذكر اسم الله عليه﴾؟","answer":"الفاء تفرع الأمر على ثبوت علم الله بالمهتدين وعلى إبطال ظنون المشركين؛ فإذا كان حكمه هو الحق فكلوا مما أباحه وذُكر اسمه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص737، تحت «معنى الفاء في قوله تعالى: ﴿فكلوا﴾»","url":""}]},{"id":"s6-832","number":832,"surah":6,"verses":[118],"references":[{"surah":6,"verses":[118]}],"verseLabel":"الأنعام: 118","question":"لماذا عُبّر عن الذبائح بـ﴿ما ذُكر اسم الله عليه﴾ بدل تسميتها مباشرة؟","answer":"لإبراز الوصف المقصود في مقام الرد على المشركين: ذكر اسم الله عليها، وفيه تشريف وتعريض بما يذبحونه على غير اسمه. فالتعبير بالموصول يجعل هذه الصفة موضع الانتباه، بدل مجرد اسم المأكول.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص739، تحت «نكتة استعمال الموصول في قوله تعالى: مما ذكر اسم الله عليه»","url":""}]},{"id":"s6-833","number":833,"surah":6,"verses":[118],"references":[{"surah":6,"verses":[118]}],"verseLabel":"الأنعام: 118","question":"لماذا قُيّد الإيمان بـ﴿بآياته﴾ في ﴿إن كنتم بآياته مؤمنين﴾؟","answer":"لأن السياق في آيات الله وحججه وكتابه المفصل؛ فجاء القيد ليربط امتثال الحكم بالإيمان بتلك الآيات. فمن صدقها أخذ بما بيّنته، ولم يجعل ظنون المشركين مرجعًا لحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص741، تحت «نكتة ذكر قيد بآياته»","url":""}]},{"id":"s6-834","number":834,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما بلاغة التركيب في قوله تعالى: ﴿وما لكم ألا تأكلوا﴾ وغرضه البياني؟","answer":"سأل عن الشيء الثابت لهم الذي يمنعهم من الأكل، بدل النهي المباشر عن الترك؛ فكان أبلغ في نفي كل مسوغ وفي تقريعهم على الامتناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص745–746، تحت عنوان «بلاغة التركيب في قوله وما لكم ألا تأكلوا وغرضه البياني»","url":""}]},{"id":"s6-835","number":835,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما أثر البناء للمجهول في قراءة ﴿وقد فُصِّل لكم ما حُرِّم عليكم﴾؟","answer":"يوجه العناية إلى حصول البيان وعموم ما فُصِّل، بينما تبرز قراءة البناء للفاعل الامتنان بإسناد التفصيل إلى الله. فتتكامل القراءتان في بيان النعمة وشمول البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص750، تحت «توجيه القراءات القرآنية في قوله: ﴿وقد فصل لكم ما حرم عليكم﴾»","url":""}]},{"id":"s6-836","number":836,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"لماذا ذُكر استثناء الاضطرار في سياق الإنكار على من يمتنع عن الحلال؟","answer":"يزيد الاستثناء معنى الإباحة وضوحًا: فالمحرّم نفسه يباح عند الاضطرار، فكيف يُترك ما أباحه الله في حال الاختيار؟ وفي هذا إبراز لسعة الرحمة وقطع لشبهة الامتناع عن الحلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص751–752، تحت «دلالة إلا الاستثنائية في قوله: إلا ما اضطررتم إليه»","url":""}]},{"id":"s6-837","number":837,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿ليضلون بأهوائهم بغير علم﴾، فجمع الأهواء؟","answer":"جُمعت الأهواء لتعدد شهواتهم ومذاهبهم الباطلة في التحليل والتحريم، وكلها صادرة بلا علم ولا وحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص756–757، تحت «دلالة جمع الهوى في قوله تعالى: بأهوائهم»","url":""}]},{"id":"s6-838","number":838,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما دلالة تذييل الآية بقوله تعالى: ﴿إن ربك هو أعلم بالمعتدين﴾؟","answer":"ذيلت الآية بحكم عام يقرر إحاطة علم الله بمن يتجاوز حدوده؛ وفيه وعيد لمن يضل الناس أو يحرم بغير سلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص757–758، تحت عنوان «دلالة تذييل الآية بقوله إن ربك هو أعلم بالمعتدين»","url":""}]},{"id":"s6-1337","number":1337,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما غرض التوكيد في قوله تعالى: ﴿إن ربك هو أعلم بالمعتدين﴾؟","answer":"أكد الخبر بـ﴿إن﴾ وضمير الفصل ﴿هو﴾ لتثبيت كمال علم الله بالمعتدين واختصاصه بالإحاطة التامة بحالهم وجزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص757–758، تحت عنوان «غرض التوكيد»","url":""}]},{"id":"s6-1338","number":1338,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما دلالة استعمال وصف ﴿المعتدين﴾ دون غيره؟","answer":"وصفهم بالاعتداء لأنهم تجاوزوا حدود الله في التشريع والعمل والإضلال؛ فجمع الوصف صور تجاوزهم وربط الوعيد بسبب استحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص758–759، تحت عنوان «دلالة استعمال وصف المعتدين دون غيره»","url":""}]},{"id":"s6-839","number":839,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"ما معنى التعريف في لفظ ﴿الإثم﴾ في قوله تعالى: ﴿وذروا ظاهر الإثم وباطنه﴾؟","answer":"التعريف للجنس والاستغراق، فيشمل كل ما يصدق عليه اسم الإثم، ظاهرًا كان أو باطنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص765، تحت عنوان «معنى التعريف في لفظ الإثم»","url":""}]},{"id":"s6-1339","number":1339,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"ما بلاغة الاستعارة في مقابلة ظاهر الإثم بباطنه؟","answer":"صُوّر الإثم بشيء له ظاهر يبدو وباطن يخفى، فاستوعبت المقابلة أفعال الجوارح وما تستتر به القلوب والنيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص766، تحت عنوان «بلاغة الاستعارة في مقابلة ظاهر الإثم بباطنه»","url":""}]},{"id":"s6-840","number":840,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"ما سرّ تقديم ظاهر الإثم على باطنه؟","answer":"لأن التخلص مما ظهر من الإثم بداية عملية للتدرج إلى ترك باطنه؛ فالظاهر أشد انتشارًا وتأثيرًا في النفس والمجتمع، وتركه يعين على إصلاح الداخل. وجمعهما في الأمر يمنع الاكتفاء بإصلاح الظاهر وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص764–765، تحت «حكمة تقديم لفظ ظاهر على باطنه»","url":""}]},{"id":"s6-841","number":841,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"لماذا جاء اكتساب الإثم بصيغة المضارع في ﴿إن الذين يكسبون الإثم﴾؟","answer":"يصور المضارع تجدّد اكتساب الإثم واستمراره، فيربط الوعيد بالفعل الذي يزاولونه. وفيه تنبيه إلى أن الإثم قد يتدرج ويتكرر حتى يستحكم، فينبغي قطعه من بدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص767، تحت «نكتة التعبير بالفعل المضارع في إن الذين يكسبون الإثم»","url":""}]},{"id":"s6-842","number":842,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"ما سرّ التعبير في قوله تعالى في الجزاء: ﴿بما كانوا يقترفون﴾، لا: بما كانوا يكسبون؟","answer":"الكسب يستعمل في الخير والشر، أما الاقتراف فيغلب في اكتساب السيئات، وفي صيغته مبالغة تلائم ذم الفعل. فناسب ذكره في الجزاء أن يبرز قبح ما اكتسبوه ومخالفتهم للفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص769، تحت «سر استعمال يقترفون بدلا من يكسبون»","url":""}]},{"id":"s6-843","number":843,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"لماذا قال ﴿لم يُذكر اسم الله عليه﴾ ولم يقل: ذُكر عليه غير اسم الله؟","answer":"لأن النهي يبرز ترك اسم الله، فلا يقتصر على التصريح باسم غيره. أما التعبير بذكر اسم آخر فقد يوهم خروج ما تُركت تسميته أصلًا من الكلام. وبهذا يظهر الفرق الذي قرره المصدر بين العبارتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص774–775، تحت «سر النفي بقوله لم يذكر دون غيره من التعبيرات»","url":""}]},{"id":"s6-844","number":844,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"لماذا أكد: ﴿وإنه لفسق﴾؟","answer":"اجتمع ﴿إن﴾ واللام لتقرير وصف الفسق بقوة وتنفير المخاطب من الإقدام عليه. فالتوكيد يحسم التردد ويجعل النهي أشد وقعًا من خبر يلقى بلا توكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص776، تحت «بلاغة التوكيد في قوله تعالى: وإنه لفسق»","url":""}]},{"id":"s6-845","number":845,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"إلى ماذا يعود الضمير في ﴿وإنه لفسق﴾؟","answer":"الضمير يعود إلى الأكل المفهوم من النهي، أو إلى ما لم يذكر اسم الله عليه؛ والمعنى في الوجهين أن تناول هذه الذبيحة فسق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص776، تحت «تعيين مرجع الضمير في قوله تعالى: وإنه لفسق»","url":""}]},{"id":"s6-846","number":846,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"لماذا وصف وسوسة الشياطين بأنها ﴿يوحون إلى أوليائهم﴾؟","answer":"سميت وسوستهم وحيًا لأنها إلقاء خفي سريع إلى أوليائهم، يمدونهم بحجج باطلة ليجادلوا المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص778، تحت «سر استعمال الإيحاء دون مرادفاته»","url":""}]},{"id":"s6-847","number":847,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"ما نكتة استعمال المجادلة في قوله تعالى: ﴿ليجادلوكم﴾؟","answer":"المجادلة محاولة فتل الخصم عن رأيه وردّه عنه بالحجاج؛ فدل اللفظ على أنهم لا يطلبون الحق، بل يريدون التمويه وإرجاع المؤمنين عن حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص779، تحت عنوان «نكتة استعمال المجادلة في قوله تعالى: ليجادلوكم»","url":""}]},{"id":"s6-1340","number":1340,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"ما الفرق بين الجدال والمراء؟","answer":"الجدال مراجعة الخصم بقوة بقصد رده عن رأيه، وأصله من شدة الفتل؛ والمراء مخاصمة في الحق بعد ظهوره ناشئة عن اللجاج والشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص781، تحت عنوان «الفروق المعجمية: الجدال والمراء»","url":""}]},{"id":"s6-848","number":848,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"ما غرض حذف متعلق فعل الشرط في قوله تعالى: ﴿وإن أطعتموهم﴾؟","answer":"حذف المتعلق اعتمادًا على السياق، أي إن أطعتموهم في استحلال ما حرمه الله؛ وفي الحذف إيجاز وتركيز على خطورة أصل الطاعة في هذا التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص780، تحت عنوان «غرض حذف متعلق فعل الشرط وإن أطعتموهم»","url":""}]},{"id":"s6-1341","number":1341,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"ما بلاغة التوكيد في جملة ﴿إنكم لمشركون﴾؟","answer":"أكد جواب الشرط بـ﴿إن﴾ واللام لأن تحريم الإسلام أو تحليله على خلاف حكم الله يساوي الشرك، وهو حكم شديد يحتاج إلى تثبيت وقطع للالتباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص781، تحت عنوان «بلاغة التوكيد في جملة إنكم لمشركون»","url":""}]},{"id":"s6-849","number":849,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"لماذا شبّه الكافر بالميت والمؤمن بمن أحياه الله؟","answer":"شُبه الكفر بالموت لأنه يعطل القلب عن إدراك الحق والانتفاع به، وشُبه الإيمان بالإحياء لأنه يعيد إليه البصيرة والحركة في طريق الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص784–785، تحت «براعة الاستعارة في استعمال لفظ الموت والإحياء»","url":""}]},{"id":"s6-850","number":850,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما بلاغة الإطناب في جملة ﴿وجعلنا له نورًا يمشي به في الناس﴾؟","answer":"فصلت الجملة أثر الإحياء بعد الموت، فبينت أن المهتدي مُنح نور الإيمان والوحي وصار يعمل به بين الناس؛ فزاد التفصيل صورة الهداية وضوحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص785، تحت عنوان «بلاغة الإطناب في جملة وجعلنا له نورا يمشي به في الناس»","url":""}]},{"id":"s6-1342","number":1342,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما بلاغة الاستعارة في استعمال ﴿يمشي﴾؟","answer":"استعير المشي للتصرف في الحياة على بصيرة؛ فالمؤمن ينتقل في أعماله ومعاملاته مستضيئًا بنور الإيمان كما يمشي المرء بضوء محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص786، تحت عنوان «بلاغة الاستعارة في استعمال يمشي»","url":""}]},{"id":"s6-1343","number":1343,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما دلالة استعمال حرف الظرفية في قوله تعالى: ﴿في الناس﴾؟","answer":"صورت ﴿في﴾ صاحب النور منغمسًا في مجتمع الناس مؤثرًا فيهم؛ ولو قيل «بين الناس» لأفاد مجرد الحركة في وسطهم دون هذه الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص787، تحت عنوان «دلالة استعمال حرف الظرفية في الناس»","url":""}]},{"id":"s6-851","number":851,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"لماذا عُدّي المشي بالنور بالباء؟","answer":"الباء سببية؛ أي إن النور الذي جعله الله له كان سبب هدايته المعبر عنها بالمشي بين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص786، تحت «معنى حرف الباء الداخل على الضمير به»","url":""}]},{"id":"s6-852","number":852,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما براعة التمثيل في قوله تعالى: ﴿كمن مثله في الظلمات﴾؟","answer":"قابل التمثيل هيئة من أحياه الله وجعل له نورًا بهيئة مشرك باق في ظلمات لا يخرج منها، فنفى الاستفهام الإنكاري مساواة الحالين في صورة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص787، تحت عنوان «براعة التمثيل في قوله تعالى: كمن مثله في الظلمات»","url":""}]},{"id":"s6-1344","number":1344,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما بلاغة المجاز بالحذف في قوله تعالى: ﴿كمن مثله في الظلمات﴾؟","answer":"حذف المشبه وقدّر: «كمن مثله مثل ميت»؛ لأن الفريقين اشتركا أولًا في حال الشرك، ثم أحيا الله أحدهما بالإيمان وبقي الآخر في الظلمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص787، تحت عنوان «بلاغة المجاز بالحذف في قوله تعالى: كمن مثله في الظلمات»","url":""}]},{"id":"s6-853","number":853,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"لماذا جُمعت ﴿الظلمات﴾ وأُفرد ﴿نورًا﴾؟","answer":"أُفرد النور لأن الحق واحد متسق، وجُمعت الظلمات لتعدد طرق الكفر والجهل والشهوة والشبهات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص788، تحت «نكتة إفراد نورا وجمع الظلمات»","url":""}]},{"id":"s6-854","number":854,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"لماذا قوبل ﴿فأحييناه﴾ بقوله ﴿ليس بخارج منها﴾؟","answer":"كلاهما كان في ضلال، لكن الأول انتقل منه إلى حياة الإيمان بإنقاذ الله له، والثاني بقي غارقًا في الظلمات. فتبرز المقابلة الفرق بين نعمة الانتقال إلى الهدى وشدة البقاء في الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص788–789، تحت «فائدة مقابلة فأحييناه بقوله ليس بخارج منها»","url":""}]},{"id":"s6-855","number":855,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما وجه التشبيه في ﴿وكذلك جعلنا في كل قرية أكابر مجرميها﴾؟","answer":"يربط حال أكابر المجرمين في مكة بنظرائهم في القرى الأخرى؛ فما يلقاه الرسول من تصدرهم للصد والمكر قد واجهته دعوات الرسل قبله. وفي هذا تسلية له وتحذير لهم من مآل من سبقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص795، تحت «بلاغة التشبيه وتعيين المشار إليه باسم الإشارة في قوله كذلك»","url":""}]},{"id":"s6-856","number":856,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما سرّ تقديم ﴿في كل قرية﴾ على ﴿أكابر مجرميها﴾؟","answer":"قُدّم الظرف لإفادة العموم والاهتمام بانتشار السنة: في كل قرية يوجد هذا الصنف، لا في قرية مخصوصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص796، تحت «نكتة تقديم في كل قرية على أكابر مجرميها»","url":""}]},{"id":"s6-857","number":857,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما معنى الجعل ودلالة إسناده إلى ضمير العظمة في قوله تعالى: ﴿وكذلك جعلنا في كل قرية أكابر مجرميها﴾؟","answer":"الجعل هنا تصيير بحسب سنن الابتلاء والاجتماع، وإسناده إلى ضمير العظمة يبرز نفاذ القدرة والحكمة في تدبير أحوال القرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص795–796، تحت عنوان «معنى الجعل ودلالة إسناده إلى ضمير العظمة»","url":""}]},{"id":"s6-1345","number":1345,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"لماذا خُص الأكابر بالذكر دون الأصاغر في قوله تعالى: ﴿أكابر مجرميها﴾؟","answer":"لأن الأكابر أقدر بمالهم ونفوذهم على تدبير المكر، وأشد حرصًا على بقاء رئاستهم، والأصاغر تبع لهم؛ فكان أثر فسادهم أوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص796–797، تحت عنوان «توجيه تخصيص الأكابر بالذكر دون الأصاغر»","url":""}]},{"id":"s6-858","number":858,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿ليمكروا فيها﴾، فجعل المكر غاية لمكانتهم؟","answer":"من وجوهها أنها لام العاقبة: آل ما أُعطوه من مكانة إلى المكر بسبب اختيارهم. ويذكر المصدر وجه التعليل ضمن حكمة الابتلاء والصراع الذي يظهر به الحق، ولا يلزم منه حصر حكمة الجعل في المكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص798–799، تحت «نوع اللام في قوله تعالى: ليمكروا فيها»","url":""}]},{"id":"s6-859","number":859,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يمكرون إلا بأنفسهم﴾ بطريق القصر؟","answer":"القصر يقلب أثر المكر عليهم: يظنون أنهم يضرون الدعوة، والحقيقة أن وباله وعقوبته لا يعودان إلا إلى أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص799–800، تحت «دلالة القصر وبلاغته في قوله تعالى: وما يمكرون إلا بأنفسهم»","url":""}]},{"id":"s6-861","number":861,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"ما دلالة بناء الفعل للمجهول في قولهم: ﴿لن نؤمن حتى نؤتى مثل ما أوتي رسل الله﴾؟","answer":"البناء للمجهول يعكس قصر نظرهم على نيل العطاء الحسي والمنزلة، دون التفكر في واهب الرسالة وحكمته؛ فجعلوا غايتهم أن يُؤتوا مثل الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص14–15، تحت «نكتة إسناد الفعل إلى المفعول في قوله تعالى حتى نؤتى؛ نكتة إسناد الفعل إلى المفعول في مثل ما أوتي رسل الله»","url":""}]},{"id":"s6-862","number":862,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"ما دلالة الرد بقوله تعالى: ﴿الله أعلم حيث يجعل رسالته﴾؟","answer":"الرد يبين أن الرسالة اصطفاء إلهي قائم على العلم بمن يصلح لحملها، لا مرتبة تُنال بالزعامة أو المال أو الحسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص17–18، تحت «بلاغة البدء بلفظ الجلالة في قوله تعالى الله أعلم حيث يجعل رسالته»","url":""}]},{"id":"s6-863","number":863,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"لماذا اختير لفظ ﴿صغار﴾ لعقوبة المستكبرين؟","answer":"الصغار ذلّ يصحبه إقرار بالهوان واستسلام له؛ فناسب من تكبروا وطلبوا منزلة الرسل أن يكون جزاؤهم ذلةً تهدم استعلاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص21، تحت عنوان «سر استعمال لفظ صغار دون مرادفاته»","url":""}]},{"id":"s6-1346","number":1346,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"ما الفرق بين الصغار والذلة؟","answer":"الذلة انقياد وقهر قد يقعان من غير اعتراف، أما الصغار فيضم إلى الذل اعتراف صاحبه به وإظهاره صغيرًا حقيرًا؛ لذلك كان أشد في تقريع المستكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص24، تحت عنوان «الفروق المعجمية: الصغار والذلة»","url":""}]},{"id":"s6-864","number":864,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"ما دلالة ﴿كانوا﴾ في قوله تعالى: ﴿بما كانوا يمكرون﴾؟","answer":"دل الفعل الماضي الناقص على أن مكرهم لم يكن عارضًا، بل حالًا مستمرةً مستقرةً فيهم؛ فاستحقوا العقاب على ما داوموا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص23، تحت عنوان «بلاغة ذكر كانوا»","url":""}]},{"id":"s6-1347","number":1347,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"لماذا عبّر عن عملهم بالمكر لا بمجرد الإجرام؟","answer":"لأن المكر يكشف تدبير الشر في خفاء، ويصور حيلهم لصد الناس عن الحق وإيذاء الدعوة؛ فهو أخص بحالهم وأشد كشفًا لخطرهم من لفظ الإجرام العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص23، تحت عنوان «بلاغة التعبير بالمكر دون يجرمون»","url":""}]},{"id":"s6-865","number":865,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما الصورة التي يرسمها قوله تعالى: ﴿يشرح صدره للإسلام﴾؟","answer":"صوّر تهيئة القلب لقبول الإيمان بانشراح جسم يتسع بعد ضيق؛ فاستحضر ما يجده المهتدي من قبول وطمأنينة ورغبة في الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص29، تحت عنوان «بلاغة الاستعارة التمثيلية في جملة يشرح صدره»","url":""}]},{"id":"s6-866","number":866,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"لماذا أُتبع وصف الصدر بالضيق بوصفه ﴿حرجًا﴾؟","answer":"لأن الحرج غاية الضيق، فجاء بعد الضيق ليؤكده ويزيده حتى يصور صدرًا لا يجد الإيمان فيه منفذًا ولا متسعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص32، تحت عنوان «نكتة إتباع وصف الضيق بالحرج»","url":""}]},{"id":"s6-1348","number":1348,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما الصورة التي يرسمها وصف الصدر بأنه ﴿حرج﴾؟","answer":"استُعير الحرج من الشجر الكثيف المتشابك الذي لا يُوصل إليه، فصوّر قلب المعرض منغلقًا لا يتسع للإيمان ولا يستقر فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص33، تحت عنوان «بلاغة الاستعارة في لفظ حرجا»","url":""}]},{"id":"s6-867","number":867,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما بلاغة تشبيه الضال بمن ﴿يصعد في السماء﴾؟","answer":"حوّل التشبيه نفوره من الإيمان وضيق صدره به إلى مشهد إنسان يتكلف صعود السماء فيعجز ويشتد نفسه؛ فصار الضيق المعنوي عناءً محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص33، تحت عنوان «بلاغة التشبيه في قوله تعالى كأنما يصعد»","url":""}]},{"id":"s6-1349","number":1349,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما أثر التضعيف في قراءة ﴿يصّعّد﴾؟","answer":"زاد التضعيف معنى التكلف والمبالغة وتكرر المحاولة؛ فصوّر صعودًا شاقًا ممتنعًا، وشدد بذلك صورة نفور الكافر وعجزه عن قبول الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص33–34، تحت عنوان «فائدة التضعيف في يصعد»","url":""}]},{"id":"s6-868","number":868,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"لماذا أوثر لفظ ﴿الرجس﴾ على لفظ العذاب؟","answer":"الرجس ما تستقذره النفوس، فيجمع معنى العقوبة مع الخبث والنفور؛ فاختياره يصور ما يلابسهم من ضلال وعذاب شيئًا مستقذرًا يناسب إصرارهم على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص38، تحت عنوان «نكتة إيثار لفظ الرجس على العذاب»","url":""}]},{"id":"s6-1350","number":1350,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما الصورة التي أفادها حرف ﴿على﴾ في قوله تعالى: ﴿يجعل الله الرجس على الذين لا يؤمنون﴾؟","answer":"أفاد الاستعلاء والتمكن، فكأن الرجس قد علاهم وأحاط بهم واستقر فوقهم؛ فاشتدت صورة لزوم العقوبة وغلبتها لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص38، تحت عنوان «بلاغة المجاز في حرف الاستعلاء»","url":""}]},{"id":"s6-869","number":869,"surah":6,"verses":[126],"references":[{"surah":6,"verses":[126]}],"verseLabel":"الأنعام: 126","question":"ما فائدة ﴿مستقيمًا﴾ بعد إضافة الصراط إلى الرب في ﴿وهذا صراط ربك مستقيمًا﴾؟","answer":"هي حال مؤكدة؛ فإضافة الصراط إلى الله تقتضي استقامته، ثم صُرّح بها تثبيتًا لهذا المعنى. وليست استقامة عارضة تزول، بل صفة ثابتة للطريق الذي يهدي إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص46، تحت «بيان التعبير بالحال المؤكدة»","url":""}]},{"id":"s6-870","number":870,"surah":6,"verses":[126],"references":[{"surah":6,"verses":[126]}],"verseLabel":"الأنعام: 126","question":"لماذا ناسب لفظ الربوبية الحديث عن الهداية في قوله تعالى: ﴿صراط ربك﴾؟","answer":"لأن الربوبية تتضمن التربية والرعاية والإنعام؛ والهداية إلى الصراط المستقيم من أعظم آثار هذه العناية، فناسبها اسم الرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص45، تحت عنوان «نكتة اصطفاء الربوبية دون غيرها»","url":""}]},{"id":"s6-871","number":871,"surah":6,"verses":[126],"references":[{"surah":6,"verses":[126]}],"verseLabel":"الأنعام: 126","question":"لماذا خُتمت بـ﴿لقوم يذكرون﴾؟","answer":"لأنهم المنتفعون بالتفصيل: يتأملون الحجج ويتذكرونها ويقبلون الموعظة، فتثمر فيهم هداية. فتخصيصهم لا يعني حجب البيان عن غيرهم، بل إبراز من يستفيد منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص49، تحت «نكتة تخصيص القوم بالذكر»","url":""}]},{"id":"s6-872","number":872,"surah":6,"verses":[127],"references":[{"surah":6,"verses":[127]}],"verseLabel":"الأنعام: 127","question":"ما دلالة إضافة الدار إلى اسم الله ﴿السلام﴾؟","answer":"إذا كان السلام اسمًا لله فإضافة الدار إليه تشريف وتعظيم، وتدل على أنها في حفظه ورعايته وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص53، تحت عنوان «إضافة الدار إلى اسم الله السلام»","url":""}]},{"id":"s6-1351","number":1351,"surah":6,"verses":[127],"references":[{"surah":6,"verses":[127]}],"verseLabel":"الأنعام: 127","question":"لماذا أوثر اسم ﴿السلام﴾ في قوله تعالى: ﴿لهم دار السلام﴾؟","answer":"لأنه يجمع سلامة الجنة من الفناء والآفات، وسلام أهلها بعضهم على بعض، وما فيها من تحية الملائكة؛ فكان أوسع من مجرد الأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص53، تحت عنوان «علة إيثار اسم السلام على غيره»","url":""}]},{"id":"s6-873","number":873,"surah":6,"verses":[127],"references":[{"surah":6,"verses":[127]}],"verseLabel":"الأنعام: 127","question":"ما سر التعبير بقوله تعالى: ﴿عند ربهم﴾؟","answer":"ليست العندية مكانية، بل تفيد قرب التكريم وعلو المنزلة وضمان الجزاء؛ فدار السلام ثابتة لهم في جوار رحمة ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص54، تحت عنوان «بديع التعبير بلفظ العندية»","url":""}]},{"id":"s6-874","number":874,"surah":6,"verses":[127],"references":[{"surah":6,"verses":[127]}],"verseLabel":"الأنعام: 127","question":"ما دلالة الإخبار بأن الله ﴿وليهم﴾؟","answer":"دل على أنه يتولى حفظهم ونصرهم وإيصال الخير ودفع الآفات عنهم؛ فالولاية قرب ورعاية وتشريف، لا مجرد جزاء عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص56، تحت عنوان «نكتة الإخبار بكونه تعالى ﴿وليهم﴾»","url":""}]},{"id":"s6-875","number":875,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"لماذا نادى الجن وحدهم أولًا: ﴿يا معشر الجن قد استكثرتم من الإنس﴾؟","answer":"بدأ بالجن لأنهم أصل الإغواء في هذا السياق، ولأن الخطاب السابق تناول استكثارهم من إضلال الإنس الذين اتخذوهم أولياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص65، تحت «دلالة نداء المعشر»","url":""}]},{"id":"s6-876","number":876,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"لماذا عبّر عن علاقة الجن والإنس بلفظ ﴿الاستمتاع﴾؟","answer":"لأن الاستمتاع يدل على طلب المنفعة واللذة؛ فكشف أن ما جمع الفريقين لم يكن حقًا ولا هداية، بل مصالح وشهوات عاجلة انتهت إلى الحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص71، تحت عنوان «قصدية التعبير بلفظ الاستمتاع»","url":""}]},{"id":"s6-1352","number":1352,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"ما فائدة قوله: ﴿استمتع بعضنا ببعض﴾؟","answer":"أظهر التبادل بين الفريقين: انتفع الجن بطاعة الإنس وتعظيمهم، وانتفع الإنس بما توهموه من حماية وخبر وقضاء شهوة؛ فاشتركا في علاقة الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص71، تحت عنوان «فائدة التعبير باستمتاع بعضهم ببعض»","url":""}]},{"id":"s6-877","number":877,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"ما بلاغة قولهم: ﴿وبلغنا أجلنا﴾؟","answer":"كَنَوا به عن بلوغ وقت البعث والحساب، وفي اعترافهم حسرة على زمن الدنيا الذي استنفدوه في الاستمتاع والضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص72، تحت عنوان «بلاغة الكناية في وبلغنا أجلنا»","url":""}]},{"id":"s6-878","number":878,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿النار مثواكم﴾، لا: مأواكم؟","answer":"المثوى مقام الإقامة الطويلة المستقرة، وهو أنسب بخلودهم في النار من لفظ المأوى الذي قد يطلق على مجرد موضع اللجوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص78–79، تحت «الفروق المعجمية: المثوى والمآل والمقام والمنزل والمصير والمقر»","url":""}]},{"id":"s6-879","number":879,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"ما دلالة الاستثناء في قوله: ﴿إلا ما شاء الله﴾ بعد ذكر الخلود في الأنعام؟","answer":"يبين أن الخلود جارٍ بمشيئة الله ولا يخرج عن قدرته، ويحتمل استثناء من شاء الله من عصاة أهل الإيمان فلا يخلدون خلود الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص75، تحت «دلالة الاستثناء، وفائدته»","url":""}]},{"id":"s6-1411","number":1411,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"عمَّ تكني جملة الاستثناء ﴿إلا ما شاء الله﴾ في سياق الخلود؟","answer":"تكني عن دوام سلطان الله ونفوذ مشيئته؛ فالخلود ليس أمرًا خارجًا عن قدرته، وإنما يقع ويستمر بإرادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص76، تحت «بلاغة الكناية في جملة الاستثناء»","url":""}]},{"id":"s6-1412","number":1412,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"ما معنى الاستثناء في قوله: ﴿إلا ما شاء ربك﴾ في سورة هود؟","answer":"يُحمل على استثناء عصاة الموحّدين الذين يعذبون مدة ثم تدركهم رحمة الله، فلا تكون إقامتهم في النار أبدية كإقامة الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص727، تحت «معنى الاستثناء»","url":""}]},{"id":"s6-1413","number":1413,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"ما بلاغة الاستئناف بقوله: ﴿إن ربك فعال لما يريد﴾ بعد الاستثناء؟","answer":"جاء جوابًا عما قد يثيره الاستثناء من سؤال، فقرر أن الحكم كله تابع لإرادة الله النافذة، وأنه يفعل في عباده ما تقتضيه حكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص727–728، تحت «بلاغة الاستئناف البياني»","url":""}]},{"id":"s6-1414","number":1414,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"ما دلالة صيغة ﴿فعال﴾ في قوله: ﴿إن ربك فعال لما يريد﴾؟","answer":"صيغة المبالغة تدل على كمال نفاذ إرادته وكثرة ما يقع منها؛ فلا يعجزه شيء يريده ولا يخرج حكم عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص728، تحت «دلالة صيغة ﴿فعال﴾»","url":""}]},{"id":"s6-880","number":880,"surah":6,"verses":[129],"references":[{"surah":6,"verses":[129]}],"verseLabel":"الأنعام: 129","question":"لماذا وصف طرفا الولاية في قوله تعالى: ﴿نولي بعض الظالمين بعضًا﴾ بأنهما ظالمان؟","answer":"لأن المتبوع ظلم بقيادته إلى الفساد، والتابع ظلم بقبول ولايته ومشاركته؛ فاجتماعهما نتيجة تشابه اختيارهما، والظلم المتكرر يفضي إلى ظلم عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص83، تحت عنوان «علة جعل الفريقين ظالمين»","url":""}]},{"id":"s6-881","number":881,"surah":6,"verses":[129],"references":[{"surah":6,"verses":[129]}],"verseLabel":"الأنعام: 129","question":"لماذا كرر ﴿بعض﴾؟","answer":"تكرار ﴿بعض﴾ يبين تبادل الولاية بين فريقين من جنس الظالمين: بعضهم يتولى بعضًا، فلا تختص العلاقة بطرف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص82، تحت «توجيه تعدية فعل التولية»","url":""}]},{"id":"s6-882","number":882,"surah":6,"verses":[129],"references":[{"surah":6,"verses":[129]}],"verseLabel":"الأنعام: 129","question":"ما بلاغة التعبير عن الكسب بالمضارع في قوله تعالى: ﴿يكسبون﴾؟","answer":"صوّر المضارع تجدد كسبهم للظلم والمعاصي واستمرارهم فيه مرة بعد مرة؛ فناسب تجدد الجزاء عليهم بهذا الكسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص84، تحت عنوان «بلاغة التعبير عن الكسب بالمضارع»","url":""}]},{"id":"s6-883","number":883,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا وُجه نداء واحد إلى ﴿معشر الجن والإنس﴾؟","answer":"لأن الفريقين اشتركا في التكليف والتكذيب والجزاء، وبلغتهما الرسالة؛ فجمعهما النداء في موقف واحد تقريعًا وإقامةً للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص89، تحت عنوان «توجيه نداء الجن والإنس»","url":""}]},{"id":"s6-884","number":884,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"كيف وُصف الرسل بأنهم ﴿منكم﴾ مع أن الرسل من الإنس؟","answer":"لأن الخطاب جمع الإنس والجن جماعتين، والرسل من أحد الفريقين، ولأن رسل الإنس بلغوا الجميع وقام من الجن منذرون ينقلون دعوتهم؛ فصح الوصف باعتبار المجموع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص90، تحت عنوان «بديع وصف الرسل بمنكم»","url":""}]},{"id":"s6-885","number":885,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا جُمع الرسل في قوله تعالى: ﴿رسل منكم يقصون عليكم آياتي﴾؟","answer":"لأن دعوة الرسل واحدة وآيات الله التي يبلغونها يصدق بعضها بعضًا؛ فجمعهم أبرز وحدة الرسالة وإقامة الحجة على الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص91، تحت عنوان «علة جمع الرسل بقوله تعالى: ﴿يقصون عليكم آياتي﴾»","url":""}]},{"id":"s6-1353","number":1353,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا اختير لفظ ﴿ينذرونكم﴾ في الحديث عن لقاء يوم القيامة؟","answer":"الإنذار إخبار مقرون بالتخويف والتحذير؛ فناسب لقاء يوم يحمل عاقبة التكذيب، وجمع مع قص الآيات بين بيان الحجة والتنبيه إلى جزائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص93، تحت عنوان «علة اصطفاء لفظ الإنذار»","url":""}]},{"id":"s6-886","number":886,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا عبّروا عن إقرارهم بقولهم ﴿شهدنا على أنفسنا﴾؟","answer":"لأن الشهادة تفيد تحقق الخبر وثبوته؛ فقد أقروا بأن الرسل بينوا لهم، وأنهم خالفوا هذا البيان. فصار اعترافهم شهادة ثابتة عليهم تقطع الاعتذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص96، تحت «دلالة استعمال الشهادة بمعنى الإقرار»","url":""}]},{"id":"s6-887","number":887,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا تكرر: ﴿وشهدوا على أنفسهم أنهم كانوا كافرين﴾؟","answer":"الجملة الأولى جوابهم عند السؤال وإقرارهم بقيام الحجة، والثانية حكاية من الله تثبت حقيقة شهادتهم وكفرهم بعد أن غرتهم الحياة الدنيا؛ فليست تكرارًا خاليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص98، تحت «سر تكرار ذكر شهادتهم على أنفسهم»","url":""}]},{"id":"s6-888","number":888,"surah":6,"verses":[131],"references":[{"surah":6,"verses":[131]}],"verseLabel":"الأنعام: 131","question":"إلى ماذا يشير اسم الإشارة ﴿ذلك﴾، وما أثر افتتاح الآية به؟","answer":"يشير إلى إرسال الرسل وإنذار الأمم وإقامة الحجة؛ فجمع ما سبق في أمر عظيم، ثم بين أن ذلك من عدل الله كيلا يهلك قومًا قبل البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص103، تحت عنوان «توجيه الافتتاح باسم الإشارة ﴿ذلك﴾»","url":""}]},{"id":"s6-889","number":889,"surah":6,"verses":[131],"references":[{"surah":6,"verses":[131]}],"verseLabel":"الأنعام: 131","question":"لماذا اختير اسم الفاعل ﴿مهلك﴾؟","answer":"اسم الفاعل ﴿مهلك﴾ يدل على ثبوت الشأن والصفة في المقام، وينفي أن يكون من سنته إهلاك القرى على تلك الحال دون إنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص106، تحت «براعة التعبير باسم الفاعل مهلك»","url":""}]},{"id":"s6-890","number":890,"surah":6,"verses":[131],"references":[{"surah":6,"verses":[131]}],"verseLabel":"الأنعام: 131","question":"لماذا قُيّد نفي الإهلاك بحال ﴿وأهلها غافلون﴾؟","answer":"لأن الغفلة هنا عدم بلوغ إنذار الرسل؛ فلا يكون الهلاك قبل إقامة الحجة. فإذا جاءهم البيان زالت هذه الحال، فلا يبقى التعلل بالغفلة عذرًا للإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص110، تحت «وجه التعبير عن الفاصلة باسم الفاعل المجموع»","url":""}]},{"id":"s6-891","number":891,"surah":6,"verses":[132],"references":[{"surah":6,"verses":[132]}],"verseLabel":"الأنعام: 132","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكل درجات مما عملوا﴾، فجمع الدرجات للفريقين؟","answer":"الدرجات تشمل مراتب الثواب والعقاب صعودًا وهبوطًا تغليبًا، فلكل من الإنس والجن منزلة تناسب عمله، ولا يستوي المحسن والمسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص117–118، تحت «سر استعمال لفظ درجات مقابل لفظ دركات»","url":""}]},{"id":"s6-892","number":892,"surah":6,"verses":[132],"references":[{"surah":6,"verses":[132]}],"verseLabel":"الأنعام: 132","question":"ما الذي يضيفه ربط الدرجات بالأعمال في ﴿ولكل درجات مما عملوا﴾؟","answer":"يجعل العمل منشأ المرتبة وسببها؛ فـ﴿من﴾ هنا للتعليل: لكل فريق درجات بسبب أعماله. وبذلك يرتبط التفاوت في الجزاء بما قدموه، فلا تكون المنازل اعتباطًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص118، تحت «دلالة من في قوله تعالى مما عملوا»","url":""}]},{"id":"s6-893","number":893,"surah":6,"verses":[132],"references":[{"surah":6,"verses":[132]}],"verseLabel":"الأنعام: 132","question":"لماذا نُفيت الغفلة باسم الفاعل في قوله تعالى: ﴿وما ربك بغافل﴾؟","answer":"أفاد اسم الفاعل ثبات نفي الغفلة ودوامه، فليس علم الله بأعمالهم علمًا عارضًا؛ وفي ذلك ضمان للجزاء ووعيد لمن ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص119، تحت عنوان «سر التعبير عن نفي الغفلة باسم الفاعل»","url":""}]},{"id":"s6-1354","number":1354,"surah":6,"verses":[132],"references":[{"surah":6,"verses":[132]}],"verseLabel":"الأنعام: 132","question":"كيف أكدت جملة ﴿وما ربك بغافل عما يعملون﴾ إحاطة علم الله؟","answer":"اجتمع فيها النفي والجملة الاسمية والباء الزائدة في خبرها واسم الرب المضاف إلى النبي؛ فاشتد نفي الغفلة وثبت أن أعمالهم كلها محصاة للجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص123، تحت عنوان «بلاغة التوكيد في جملة الفاصلة»","url":""}]},{"id":"s6-894","number":894,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"ما بلاغة الاحتراس بقوله تعالى: ﴿ذو الرحمة﴾ بعد وصف الله بالغنى؟","answer":"منع هذا الوصف أن يُفهم من غناه عن الخلق أنه يهملهم أو يمنع فضله؛ فهو غني عنهم ومع ذلك يعاملهم برحمة وإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص129، تحت عنوان «بلاغة الاحتراس في قوله ذو الرحمة»","url":""}]},{"id":"s6-1355","number":1355,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"لماذا اقترنت صفتا ﴿الغني﴾ و﴿ذو الرحمة﴾ في هذا الموضع؟","answer":"الغنى يثبت أنه لا يحتاج إلى طاعتهم، والرحمة تبين أن إمهالهم وإحسانه إليهم فضل خالص؛ فاجتمعت القدرة على الاستبدال مع فتح باب التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص132–133، تحت عنوان «نكتة اختيار صفتي الغنى والرحمة واقترانهما في هذا الموضع»","url":""}]},{"id":"s6-895","number":895,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"لماذا قيل ﴿يذهبكم﴾ ولم يقل: يهلككم؟","answer":"الإذهاب أوسع؛ فقد يكون بالإهلاك أو بإزالة سلطان قوم واستخلاف غيرهم، ويصور زوالهم حتى يغيب أثرهم، فناسب سياق القدرة على الاستبدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص137، تحت عنوان «علة التعبير بلفظ يذهبكم دون غيره»","url":""}]},{"id":"s6-896","number":896,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿ويستخلف من بعدكم ما يشاء﴾، واستعمل ﴿ما﴾؟","answer":"استُعملت ﴿ما﴾ لتعميم المستخلَف وإبهام جنسه وصفته؛ فالله قادر أن يأتي بعدهم بما يشاء من خلق لا يحيطون به، وفي ذلك تهديد أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص140، تحت «إيثار الموصول ما المستعمل لغير العاقل»","url":""}]},{"id":"s6-897","number":897,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"ما بلاغة التشبيه في قوله تعالى: ﴿كما أنشأكم من ذرية قوم آخرين﴾؟","answer":"جعل نشأتهم بعد أمم سابقة شاهدًا محسوسًا على إمكان إذهابهم واستخلاف غيرهم؛ فما وقع في أصل وجودهم دليل على تحقق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص141، تحت عنوان «بلاغة التشبيه في الإنشاء»","url":""}]},{"id":"s6-898","number":898,"surah":6,"verses":[134],"references":[{"surah":6,"verses":[134]}],"verseLabel":"الأنعام: 134","question":"لماذا كثرت أدوات التوكيد في قوله تعالى: ﴿إن ما توعدون لآت﴾؟","answer":"أكد الخبر بإن واللام والجملة الاسمية لأن المخاطبين ينكرون البعث والجزاء؛ فجاء التوكيد لمواجهة إنكارهم وتثبيت حتمية الموعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص150، تحت عنوان «بلاغة التوكيد بإن واللام والجملة الاسمية»","url":""}]},{"id":"s6-1356","number":1356,"surah":6,"verses":[134],"references":[{"surah":6,"verses":[134]}],"verseLabel":"الأنعام: 134","question":"ما الصورة التي يرسمها قوله تعالى: ﴿إن ما توعدون لآت﴾؟","answer":"صوّر الموعود بشيء آتٍ يتجه إليهم لا محالة؛ فانتقل الوعد من معنى مؤجل إلى مشهد يقترب ويقع يقينًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص151، تحت عنوان «بلاغة الاستعارة في قوله لآت»","url":""}]},{"id":"s6-899","number":899,"surah":6,"verses":[134],"references":[{"surah":6,"verses":[134]}],"verseLabel":"الأنعام: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أنتم بمعجزين﴾، دون أن يقال: ولن تفلتوا؟","answer":"المعجز هو الذي يفوت طالبه ويجعله عاجزًا عن إدراكه؛ فنفى أن يستطيعوا الإفلات من قدرة الله أينما كانوا، وهو أبلغ من مجرد نفي الفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص154، تحت «بلاغة المجاز في لفظ معجزين»","url":""}]},{"id":"s6-900","number":900,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"ما دلالة الأمر في قوله تعالى: ﴿قل يا قوم اعملوا﴾ في الأنعام؟","answer":"الأمر للتهديد لا للإباحة؛ أي امضوا في طريقكم إن أصررتم، فستكشف العاقبة من تكون له الدار ومن يكون على الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص158–159، تحت «دلالة الأمر في المطلع، بقوله تعالى: ﴿قل يا قوم اعملوا﴾»","url":""}]},{"id":"s6-1415","number":1415,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"ما الكناية في قوله تعالى: ﴿اعملوا على مكانتكم﴾؟","answer":"كُنّي بالمكانة عن الحال والطريقة التي تمكنوا منها؛ فالمعنى: اثبتوا على أقصى ما تستطيعون من شأنكم، وستظهر العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص161، تحت «بلاغة الكناية في قوله تعالى: ﴿اعملوا على مكانتكم﴾»","url":""}]},{"id":"s6-1416","number":1416,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"ما غرض الأمر في قول شعيب: ﴿اعملوا﴾؟","answer":"هو تهديد بعد استنفاد النصح، لا إذن بالمعصية؛ أي استمروا على طريقكم إن أبيتم، فستعلمون من يأتيه الخزي ومن هو كاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص614، تحت «غرض الأمر في قوله تعالى: ﴿اعملوا﴾»","url":""}]},{"id":"s6-1417","number":1417,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"كيف يجمع التعبير بـ﴿مكانتكم﴾ بين الاستعارة والكناية؟","answer":"صوّر حالتهم وطريقتهم في الضلال كأنها مكان ثابت يقفون عليه، وكُنّي بذلك عن تمكنهم منها وإصرارهم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص615، تحت «التعبير بـ﴿مكانتكم﴾ بين الاستعارة والكناية»","url":""}]},{"id":"s6-1418","number":1418,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"ما سر التعبير باسم الفاعل في قوله: ﴿إني عامل﴾؟","answer":"يفيد ثبات شعيب على عمله واستمراره فيه، ويقابل إصرار قومه بإظهار رسوخ عزمه ويقينه بالعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص617، تحت «سر التعبير باسم الفاعل»","url":""}]},{"id":"s6-901","number":901,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"ما أثر توكيد قول الرسول: ﴿إني عامل﴾؟","answer":"ثبت بإن مضيه في العمل بما أمره الله به، وأزال توهم أن تهديد المعاندين قد يثنيه؛ فجمع ثباته مع تخويفهم من العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص163، تحت عنوان «توكيد العمل بإن في قوله إني عامل»","url":""}]},{"id":"s6-1357","number":1357,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"لماذا عبّر الرسول عن عمله باسم الفاعل فقال: ﴿إني عامل﴾؟","answer":"دل اسم الفاعل على ثبوت العمل واستمراره، فكأن ملازمته طريق الله صفة راسخة فيه لا قرارًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص164، تحت عنوان «توجيه صيغة التعبير عن العمل باسم الفاعل»","url":""}]},{"id":"s6-902","number":902,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"لماذا لم يُصرح بالعذاب في قوله تعالى: ﴿فسوف تعلمون﴾؟","answer":"حذف ما سيعلمونه لأن المقام يدل عليه، فزاد الإبهام رهبةً وترك النفس تتوقع ألوان الوعيد، مع بقاء العبارة موجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص165، تحت عنوان «سر عدم التصريح بالعذاب»","url":""}]},{"id":"s6-1358","number":1358,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"لماذا سيقت العاقبة في صورة محتملة: ﴿من تكون له عاقبة الدار﴾؟","answer":"جاءت العبارة في صورة منصفة لا تصرح من أولها بالفائز، مع يقين الرسول بالنتيجة؛ فجمعت حسن المحاورة والثقة بأن الواقع سيكشف الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص167، تحت عنوان «بلاغة الترديد»","url":""}]},{"id":"s6-1359","number":1359,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"لماذا قيل ﴿إنه لا يفلح الظالمون﴾ بدل: لا تفلحون؟","answer":"عدل إلى الاسم الظاهر ليجعل الحكم قاعدة عامة معللة بالظلم، وليدخل المخاطبون فيها بوصفهم لا بمجرد خطابهم؛ فكان أبلغ في التعريض والوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص172، تحت عنوان «نكتة العدول عن المضمر إلى المظهر في جملة الفاصلة»","url":""}]},{"id":"s6-903","number":903,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"ما بلاغة التعريض في قوله تعالى: ﴿إنه لا يفلح الظالمون﴾؟","answer":"لم يقل لهم مباشرة إنكم لا تفلحون، بل قرر قاعدة عامة تشمل كل ظالم؛ فدخلوا فيها من طريق وصفهم، وكان ذلك أبلغ في تقريعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص170، تحت عنوان «بلاغة التعريض في إنه لا يفلح الظالمون»","url":""}]},{"id":"s6-1360","number":1360,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"كيف عللت جملة ﴿إنه لا يفلح الظالمون﴾ الوعيد السابق؟","answer":"بينت أن عاقبة الدار ليست لهم لأن الشرك والتكذيب ظلم، وسنة الله أن الظالم لا يبلغ الفلاح؛ فربطت النتيجة بسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص172، تحت عنوان «دلالة التعليل في جملة التذييل»","url":""}]},{"id":"s6-904","number":904,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"لماذا اختير لفظ ﴿ذرأ﴾ في قوله تعالى: ﴿مما ذرأ من الحرث والأنعام﴾؟","answer":"الذرء خلق مع إظهار وإكثار وبث؛ فذكّرهم اللفظ بأن الحرث والأنعام التي قسموها خلقها الله ونشرها لهم، فلا حق لهم في التشريع من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص179، تحت عنوان «إيثار لفظ ذرأ من الآية الكريمة»","url":""}]},{"id":"s6-1361","number":1361,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"ما بلاغة قوله تعالى: ﴿مما ذرأ من الحرث والأنعام﴾ بدل الاكتفاء بذكر الحرث والأنعام؟","answer":"أضاف الوصف تذكيرًا بأن المقسوم من خلق الله وملكه، ففضح تناقضهم حين جعلوا لبعض ما خلقه نصيبًا لشركائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص180، تحت عنوان «بلاغة الإطناب في عبارة مما ذرأ»","url":""}]},{"id":"s6-905","number":905,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"ما دلالة قولهم: ﴿هذا لله بزعمهم وهذا لشركائنا﴾ مع تكرار اسم الإشارة؟","answer":"تكرار اسم الإشارة يفصل النصيبين فصلًا حسيًا كأنهما موضوعان أمامهم، ويكشف اصطناعهم قسمة بين الله وشركائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص183، تحت «علة التعبير باسمي الإشارة في الآية الكريمة»","url":""}]},{"id":"s6-906","number":906,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"لماذا قُيّد نصيب الله وحده بـ﴿بزعمهم﴾؟","answer":"قُيّد نصيب الله بـ﴿بزعمهم﴾ لأن أصل جعل نصيب لله على هذا الوجه تشريع باطل من عندهم، أما نسبة القسم الآخر لشركائهم فهي حكاية مباشرة لمقصودهم الفاسد، والزعم ينسحب على القسمة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص185–186، تحت «نكتة مجيء لفظ الزعم إثر قولهم هذا لله دون قولهم وهذا لشركائنا»","url":""}]},{"id":"s6-907","number":907,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"ما المحذوف في قوله تعالى: ﴿فما كان لشركائهم فلا يصل إلى الله﴾، ولماذا حُذف؟","answer":"حُذف جواب صورة اختلاط نصيب الشركاء بنصيب الله، أي أبقوه للشركاء ولم يردوه؛ دل عليه السياق، فكان الحذف أوجز وأشد كشفًا لانحيازهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص187، تحت عنوان «بيان الحذف في فما كان لشركائهم»","url":""}]},{"id":"s6-908","number":908,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"لماذا أوثر ﴿ساء﴾ على ﴿بئس﴾ في قوله تعالى: ﴿ساء ما يحكمون﴾؟","answer":"لأن ﴿ساء﴾ تجري مجرى الفعل وتستدعي حكمًا متجددًا قبيحًا، فناسبت تقريعهم على فعل الحكم نفسه، مع شمولها ذم حكمهم ونتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص189، تحت عنوان «علة إيثار ساء على بئس»","url":""}]},{"id":"s6-1362","number":1362,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"ما بلاغة تذييل الآية بقوله تعالى: ﴿ساء ما يحكمون﴾؟","answer":"ختمت القصة بحكم جامع يذم قسمة المشركين كلها؛ فهي تشريع بلا إذن، وجور في التطبيق، وإساءة إلى أنفسهم ودينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص190، تحت عنوان «بلاغة التذييل»","url":""}]},{"id":"s6-909","number":909,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"لماذا أُسند تزيين قتل الأولاد إلى ﴿شركائهم﴾؟","answer":"لأن الشياطين والكهنة وسدنة الأصنام هم الذين حسّنوا لهم الجريمة وشرعوها وأشاعوا مبرراتها؛ فكشف الإسناد أن الشرك كان طريقهم إلى هذا الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص199، تحت عنوان «نكتة إسناد التزيين إلى الشركاء»","url":""}]},{"id":"s6-910","number":910,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"لماذا قُدّم ﴿قتل أولادهم﴾ على فاعل التزيين ﴿شركاؤهم﴾؟","answer":"لأن القتل هو موضع العناية والتعجيب: كيف يزيّن لهم قتل أحب الناس إليهم؟ فإبرازه أولًا يكشف بشاعة ما أقدموا عليه، ثم يأتي ذكر الشركاء الذين زينوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص198–199، تحت «نكتة تقديم المفعول قتل على الفاعل شركاؤهم»","url":""}]},{"id":"s6-911","number":911,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"لماذا قُدّم الإرداء على إلباس الدين في قوله تعالى: ﴿ليردوهم وليلبسوا عليهم دينهم﴾؟","answer":"لأن الإرداء يصور الغاية الأشد، وهي إهلاكهم وإسقاطهم، ثم جاء إلباس الدين لبيان الطريق المؤدي إليها من خلط الحق بالباطل؛ فرتب الغاية الخطرة قبل وسيلتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص201، تحت عنوان «سر تقديم (الإرداء) على (الإلباس)»","url":""}]},{"id":"s6-1363","number":1363,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"ما الصورة التي يرسمها الجمع بين ﴿ليردوهم﴾ و﴿ليلبسوا عليهم دينهم﴾؟","answer":"يجمع التعبيران بين إسقاط الإنسان في الهلاك وإلباس دينه حتى يختلط عليه؛ فصُوّر إفساد النفس والدين معًا، بما في الإرداء من استعارة للسقوط وفي الإلباس من تصوير للخلط والستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص202، تحت عنوان «توجيه لفظي: (الإرداء)، و(الإلباس) بين التورية، والاستعارة، والمجاز»","url":""}]},{"id":"s6-912","number":912,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"هل يعني قوله تعالى: ﴿فذرهم وما يفترون﴾ ترك دعوتهم إلى الحق؟","answer":"المراد الإعراض عن باطلهم وترك الاهتمام بغرورهم، مع وعيدهم على افترائهم؛ وليس المراد الكف عن دعوتهم إلى الحق، فالإعراض عن الافتراء لا يلغي البلاغ والتذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص205، تحت «اصطفاء كلمة: ﴿فذرهم﴾، ودلالته في الجملة الإنشائية»","url":""}]},{"id":"s6-913","number":913,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"لماذا وصفوا الأنعام والحرث بـ﴿حجر﴾؟","answer":"الحِجر هو المنع والتحجير؛ وصفوا الأنعام والحرث به لأنهم جعلوها محظورة لا يأكلها إلا من يختارونه، كأن المنع صفة ثابتة فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص217–218، تحت «سر اختيار كلمة: ﴿حجر﴾»","url":""}]},{"id":"s6-914","number":914,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"لماذا تكرر ﴿أنعام﴾ ثلاث مرات؟","answer":"تكررت ﴿أنعام﴾ لأن كل جملة تتناول طائفة ذات حكم مستقل اخترعوه: ممنوعة الأكل، أو محرمة الظهور، أو لا يذكرون اسم الله عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص230، تحت «الغرض من تكرار لفظ (أنعام)، في سياق النكرة»","url":""}]},{"id":"s6-915","number":915,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"ماذا يكشف إسناد المنع إلى مشيئتهم في قولهم: ﴿لا يطعمها إلا من نشاء﴾؟","answer":"يكشف أنهم جعلوا التحليل والتحريم تابعين لأهوائهم، واغتصبوا حق التشريع من غير وحي؛ ففضح لفظ المشيئة تحكمهم في رزق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص222، تحت عنوان «دلالة اصطفاء فعل المشيئة وإيحاءاته المعنوية»","url":""}]},{"id":"s6-1364","number":1364,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"لماذا قالوا ﴿نشاء﴾ بالمضارع لا بالماضي؟","answer":"لأن المضارع يصور مشيئة تتجدد كلما أرادوا منع أحد أو الإذن له، فكأن التشريع عندهم قرار متكرر تحكمه الأهواء لا حكم ثابت من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص223، تحت عنوان «نكتة اختيار الفعل ﴿نشاء﴾ مضارعًا لا ماضيًا»","url":""}]},{"id":"s6-916","number":916,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"لماذا اقتصر التحريم المزعوم على ذكر ﴿ظهورها﴾؟","answer":"لأن الظهر موضع الركوب والحمل، وهما أبرز وجوه الانتفاع التي منعوها؛ فذكر الظهور كناية عن حظر استعمال تلك الأنعام في الحمل والركوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص232، تحت عنوان «علة الاقتصار على ذكر (الظهور) دون سائرها»","url":""}]},{"id":"s6-917","number":917,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"ما الذي يضيفه قوله تعالى: ﴿افتراء عليه﴾ إلى وصف تحريمهم للأنعام؟","answer":"يبين أن جريمتهم لم تقف عند تحريم الرزق، بل تجاوزته إلى اختلاق حكم ونسبته إلى الله؛ فصار فعلهم كذبًا متعمدًا على المشرّع سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص237–238، تحت عنوان «مغزى قوله سبحانه في الآية: ﴿افتراء عليه﴾»","url":""}]},{"id":"s6-1365","number":1365,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"ما دلالة تذييل الآية بقوله تعالى: ﴿سيجزيهم بما كانوا يفترون﴾؟","answer":"حوّل كشف افترائهم إلى وعيد بالجزاء، وربط العقوبة بما داوموا على اختلاقه؛ فختم بيان الجريمة بإثبات عاقبتها المحتومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص239، تحت عنوان «مغزى تذييل الآية بجملة الجزاء، ودلالة ذلك»","url":""}]},{"id":"s6-918","number":918,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"لماذا عبّروا بقولهم ﴿خالصة لذكورنا﴾ بدل حلال أو خاص؟","answer":"لأن ﴿خالصة﴾ تفيد أنهم زعموا قصر ما في البطون على الذكور قصرًا تامًا لا تشاركهم فيه النساء؛ فتكشف شدة تحكمهم في القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص254، تحت عنوان «وجه التعبير بـ﴿خالصة﴾ على (حلال) و(خاص)»","url":""}]},{"id":"s6-1366","number":1366,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"كيف عرّضت الآية بذم أصحاب هذا التحريم ومن يتبعهم؟","answer":"حكت تناقض حكمهم نفسه: يخصون الذكور بما في البطون، ويحرمونه على النساء، ثم يشركونهم فيه إن خرج ميتًا؛ فكان عرض التناقض أبلغ في ذمهم وذم من يسلك طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص261، تحت عنوان «بلاغة الآية في التعريض بذم القائلين، ومن لف لفهم»","url":""}]},{"id":"s6-919","number":919,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"لماذا قالوا: ﴿خالصة لذكورنا﴾ بالتأنيث ثم ﴿ومحرم على أزواجنا﴾ بالتذكير؟","answer":"من توجيه ذلك أن التأنيث في ﴿خالصة﴾ راعى معنى ﴿ما﴾، أي الأجنة، ثم راعى التذكير في ﴿محرم﴾ لفظ ﴿ما﴾. ويذكر المصدر وجهًا آخر: أن التاء في ﴿خالصة﴾ للمبالغة؛ فلا تكون المقابلة حينئذ اختلافًا في مراعاة جنس الموصوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص254–255، تحت «علة تأنيث ﴿خالصة﴾، وتذكير ﴿ومحرم﴾»","url":""}]},{"id":"s6-920","number":920,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"لماذا قيل في الميتة ﴿فهم فيه شركاء﴾ بدل أن يقال: فهم سواء؟","answer":"لأن الشراكة تصور اجتماع الذكور والإناث في الانتفاع بالشيء نفسه بعد أن زعموا اختصاص الذكور به حيًا؛ فكان اللفظ أكشف لتناقض حكمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص260–261، تحت عنوان «علة إيراد الخبر كلمة ﴿شركاء﴾ دون (سواء)»","url":""}]},{"id":"s6-921","number":921,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿سيجزيهم وصفهم﴾، فجعل الوصف نفسه مجزيًا؟","answer":"فيه حذف مضاف أو مجاز؛ أي سيجزيهم جزاء وصفهم الكاذب، وجُعل الوصف نفسه كأنه الجزاء لمبالغة في تحقق العقوبة وملازمتها لافترائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص263–264، تحت «نكتة الإيجاز بالحذف، في جعل الجزاء متعديًا للوصف بنفسه»","url":""}]},{"id":"s6-922","number":922,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"لماذا وصف قتل الأولاد وتحريم الرزق بأنه ﴿سفهًا﴾؟","answer":"لأن السفه خفة عقل تحمل صاحبها على ما يضره؛ وقتل الأولاد وإبطال نعم الله خسارة لا تصدر عن رأي رشيد، ففضح اللفظ فساد تقديرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص274، تحت عنوان «علة إيثار لفظ السفه»","url":""}]},{"id":"s6-1367","number":1367,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"ماذا يضيف الجمع بين ﴿سفهًا﴾ و﴿بغير علم﴾؟","answer":"كشف القيدان فسادهم من جهتين: السفه يبين خفة العقل وسوء القصد، وغياب العلم ينفي الوحي والبرهان؛ فلا حكمة في فعلهم ولا حجة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص275–276، تحت عنوان «دلالة الجمع بين الحالين ﴿سفهًا﴾ و﴿بغير علم﴾»","url":""}]},{"id":"s6-923","number":923,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"لماذا صُرّح باسم ﴿الله﴾ في قوله تعالى: ﴿ما رزقهم الله﴾؟","answer":"ليظهر التناقض بين رازق النعمة ومن يحرمها؛ فما دام الله هو الذي رزقهم فلا يملك أحد أن ينسب إليه منعها بغير وحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص277، تحت عنوان «إيثار الاسم الأعظم ﴿الله﴾ في قوله تعالى ﴿رزقهم الله﴾»","url":""}]},{"id":"s6-924","number":924,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"لماذا وُضع اسم ﴿الله﴾ ظاهرًا في قوله تعالى: ﴿افتراء على الله﴾ بدل الضمير؟","answer":"لتهويل جريمتهم؛ فهم لم يكذبوا على مجهول، بل نسبوا تشريعهم إلى الله صاحب الحق وحده في التحليل والتحريم، فكان التصريح أبلغ في التقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص279، تحت عنوان «سر وضع الاسم الظاهر ﴿الله﴾ موضع الضمير»","url":""}]},{"id":"s6-925","number":925,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"لماذا جمع بين ﴿قد ضلوا﴾ و﴿وما كانوا مهتدين﴾؟","answer":"﴿قد ضلوا﴾ يثبت وقوعهم في الضلال، و﴿وما كانوا مهتدين﴾ ينفي عنهم أصل الاهتداء واستمراره؛ فجمع إثبات الفساد ونفي ضده توكيدًا لتمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص281–282، تحت «الوصل بين الجملتين الأخيرتين بالواو العاطفة؛ دلالة النفي بـ(ما) دون (لم)، قبل (كان) الماضية»","url":""}]},{"id":"s6-926","number":926,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿أنشأ جنات معروشات وغير معروشات﴾؟","answer":"المعروشات ما يُرفع نباتها على عروش أو ما يعتني الناس بإنشائه، وغير المعروشات ما يقوم على سوقه أو ينبت دون تعريش؛ فالمقابلة تستوعب صور الجنات وتنوع الصنعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص295–296، تحت «مغزى الوصف بلفظي ﴿معروشات وغير معروشات﴾»","url":""}]},{"id":"s6-927","number":927,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما الحكمة من ترتيب النخل والزرع والزيتون والرمان في الآية؟","answer":"قُدّم النخل والزرع لأنهما أصل القوت وأوسع نفعًا، وقدم النخل لما له من ثمرة وغذاء متجدد، ثم جاء الزيتون والرمان من الفواكه المكملة؛ فانتظم التعداد بحسب الحاجة والمنفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص298–299، تحت عنوان «بلاغة ترتيب المتعاطفات»","url":""}]},{"id":"s6-928","number":928,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما بلاغة التعقيب بقوله تعالى: ﴿مختلفًا أكله﴾ بعد ذكر أصناف النبات؟","answer":"نقل النظر من مجرد تعداد النبات إلى تنوع طعمه ولونه وهيئته ومنافعه، فصار الاختلاف نفسه آية تدعو إلى التفكر في دقة الخلق وسعة النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص301–302، تحت عنوان «بلاغة التعقيب بالحال على أصناف المأكولات»","url":""}]},{"id":"s6-929","number":929,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"لماذا قيل في آية: ﴿انظروا إلى ثمره﴾، وفي الأخرى: ﴿كلوا من ثمره﴾؟","answer":"لأن الأولى في سياق الاستدلال بخلق النبات فناسبها النظر والاعتبار، والثانية في سياق إباحة الطيبات وإبطال التحريم المفتَرى فناسبها الأكل؛ فاختار كل موضع ما يخدم غرضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص309–310، تحت عنوان «بيان التشابه بين الفعلين: ﴿كلوا﴾ و﴿انظروا﴾»","url":""}]},{"id":"s6-930","number":930,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما دلالة الأمر في قوله تعالى: ﴿كلوا من ثمره إذا أثمر﴾؟","answer":"هو إذن بالانتفاع وإبطال لما ابتدعه المشركون من التحريم، وفيه امتنان بالرزق مع تذكيرهم أن الإباحة من الله لا من أهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص309، تحت عنوان «دلالة الأمر في قوله: ﴿كلوا﴾»","url":""}]},{"id":"s6-931","number":931,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"لماذا أعقب الأمر بالأكل وإيتاء الحق بالنهي عن الإسراف؟","answer":"حتى لا تتحول النعمة أو الصدقة إلى تجاوز للحد؛ فالمطلوب انتفاع معتدل وأداء للحق بلا تبذير ولا إتلاف ولا منع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص311، تحت عنوان «دلالة النهي عن الإسراف»","url":""}]},{"id":"s6-1368","number":1368,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما أثر توكيد الفاصلة: ﴿إنه لا يحب المسرفين﴾؟","answer":"ثبّت أن النهي ليس إرشادًا عابرًا، بل حد يحبه الله لعباده؛ وربط الإسراف بحرمان محبته فاشتد الزجر عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص312، تحت عنوان «بلاغة التوكيد في جملة الفاصلة»","url":""}]},{"id":"s6-932","number":932,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"لماذا سميت كبار الأنعام ﴿حمولة﴾؟","answer":"لأنها تحمل الأثقال ويركبها الناس، فاختار لها الاسم الذي يستحضر أبرز منفعتها وقوتها، ويذكّر بما سخره الله لهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص321، تحت عنوان «توجيه التعبير بـ﴿حمولة﴾ في الآية الكريمة»","url":""}]},{"id":"s6-1369","number":1369,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"لماذا عبّر عن صغار الأنعام بلفظ ﴿فرشًا﴾؟","answer":"لأنها لقربها من الأرض وصغرها كأنها مفروشة عليها، وقيل لما يُفرش من أصوافها؛ فجمع اللفظ صورة صغرها وما ينتفع به منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص322–323، تحت عنوان «علة التعبير بالفرش من الإبل»","url":""}]},{"id":"s6-933","number":933,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"ما بلاغة التصريح باسم ﴿الله﴾ في قوله تعالى: ﴿مما رزقكم الله﴾؟","answer":"ذكّر بأن الأنعام والرزق عطية من الله، فاستوجب شكره واتباع حكمه، وفضح من ينسب إلى نفسه حق تحريم ما رزقه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص325، تحت عنوان «بلاغة التصريح بلفظ الجلالة ﴿الله﴾»","url":""}]},{"id":"s6-934","number":934,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"لماذا صُورت وساوس الشيطان بـ﴿خطوات﴾؟","answer":"تصور اتباع الشيطان في التحريم الباطل بصورة من يتبع آثار سائر في طريق معوج وخطر؛ فالمقصود التحذير من سلوك طريقه كما يحذر العاقل من تقفي خطوات من يسلك مسلك الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص326، تحت «بلاغة الاستعارة التمثيلية في ﴿خطوات الشيطان﴾»","url":""}]},{"id":"s6-935","number":935,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"لماذا وُصفت عداوة الشيطان بأنها ﴿مبين﴾؟","answer":"لأن آثارها ظاهرة في إغوائه وإفساده وعداوته للإنسان، فلا عذر لمن يتبع خطوات عدو انكشف قصده وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص327، تحت عنوان «نكتة وصف عداوة الشيطان بأنه ﴿مبين﴾»","url":""}]},{"id":"s6-936","number":936,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"لماذا فُصّلت الأنعام نوعًا نوعًا بعد إجمالها في ﴿ثمانية أزواج﴾؟","answer":"لإحاطة الحجة بكل صنف ومنع المشركين من الاحتماء بإجمال الدعوى؛ فذُكر من الضأن والمعز والإبل والبقر ذكر وأنثى، ثم سئلوا عن دليل تحريم أي واحد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص333، تحت عنوان «دلالة الإطناب بالتفصيل بعد الإجمال»","url":""}]},{"id":"s6-1370","number":1370,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"ما الصورة التي أفادها إطلاق ﴿أزواج﴾ على أصناف الأنعام؟","answer":"استعمل الزوج في كل فرد يقترن بنظيره من ذكر وأنثى، فصوّر الأنواع في نظام من التقابل والتكامل، وبيّن أن الثمانية أربعة أصناف من كل صنف اثنان.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص334–335، تحت عنوان «بلاغة الاستعارة في لفظ ﴿أزواج﴾»","url":""}]},{"id":"s6-937","number":937,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"لماذا بدأ بالضأن ثم المعز؟","answer":"يذكر المصدر تقديم الضأن لطيب لحمها وعظم الانتفاع بصوفها؛ فالتقديم يلفت إلى ما تمتاز به من منفعة محسوسة، ضمن تفصيل الأنعام التي أبطل القرآن تحريمها بالهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص335، تحت «فائدة التفصيل في قوله: ﴿من الضأن اثنين ومن المعز اثنين﴾»","url":""}]},{"id":"s6-938","number":938,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"كيف يبطل سؤال ﴿قل آلذكرين حرم أم الأنثيين﴾ دعوى المشركين؟","answer":"يحصر أمامهم وجوه التحريم: أللذكورة أم للأنوثة أم لما في الأرحام؟ وكل جواب يلزمهم بتعميم لا يقولون به؛ فينكشف أن تخصيصهم بعض الأنعام بلا دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص336–337، تحت عنوان «دلالة الوضع البياني لقوله: ﴿قل آلذكرين حرم﴾»","url":""}]},{"id":"s6-939","number":939,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"لماذا نُكّر لفظ ﴿علم﴾ في قوله تعالى: ﴿نبئوني بعلم﴾؟","answer":"ليطالبهم بأي قدر معتبر من البرهان، ولو كان قليلًا؛ فلما عجزوا عن أدنى علم ظهر أن تحريمهم دعوى لا أصل لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص340–341، تحت عنوان «نكتة تنكير لفظ (علم)»","url":""}]},{"id":"s6-1371","number":1371,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"لماذا قيل ﴿نبئوني﴾ ولم يكتف بطلب الخبر؟","answer":"لأن النبأ خبر ذو شأن وفائدة يقتضي العلم والوضوح، فناسب تحديهم أن يأتوا بخبر عظيم موثق يثبت دعوى التحريم، لا بمجرد قول يتناقلونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص343–344، تحت عنوان «(النبأ) و(الخبر)»","url":""}]},{"id":"s6-940","number":940,"surah":6,"verses":[144],"references":[{"surah":6,"verses":[144]}],"verseLabel":"الأنعام: 144","question":"ما دلالة الانتقال بقوله تعالى: ﴿ومن الإبل اثنين ومن البقر اثنين﴾؟","answer":"أتم الانتقال استيعاب الأزواج الثمانية، ونقل الحجة نفسها من الضأن والمعز إلى الإبل والبقر حتى لا يبقى صنف تعلق به تحريمهم خارج المحاكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص348–349، تحت عنوان «دلالة العطف في قوله تعالى: ﴿ومن الإبل اثنين﴾»","url":""}]},{"id":"s6-941","number":941,"surah":6,"verses":[144],"references":[{"surah":6,"verses":[144]}],"verseLabel":"الأنعام: 144","question":"لماذا انتقل الخطاب إلى سؤالهم: ﴿أم كنتم شهداء إذ وصاكم الله بهذا﴾؟","answer":"بعد إسقاط حجتهم العقلية سألهم عن آخر طريق ممكن للعلم: هل شهدوا وحي الله؟ والاستفهام الإنكاري يفضح أنهم لا يملكون دليلًا ولا شهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص350–351، تحت عنوان «دلالة الاستفهام في قوله: ﴿أم كنتم شهداء﴾»","url":""}]},{"id":"s6-942","number":942,"surah":6,"verses":[144],"references":[{"surah":6,"verses":[144]}],"verseLabel":"الأنعام: 144","question":"لماذا قُيّد إضلال الناس بقوله تعالى: ﴿بغير علم﴾؟","answer":"ليكشف أن من نسب التحريم إلى الله لم يعتمد وحيًا ولا برهانًا، بل أضل الناس بجهل وافتراء؛ فالقيد يسجل فساد المصدر وسوء الأثر معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص357–358، تحت عنوان «علة مجيء القيد ﴿بغير علم﴾»","url":""}]},{"id":"s6-943","number":943,"surah":6,"verses":[144],"references":[{"surah":6,"verses":[144]}],"verseLabel":"الأنعام: 144","question":"لماذا ختمت الآية بقوله تعالى: ﴿إن الله لا يهدي القوم الظالمين﴾؟","answer":"لأن افتراء التشريع وإضلال الناس ظلم، ومن يصر على هذا الطريق يسد على نفسه باب هداية التوفيق؛ فجاءت الفاصلة جزاء مناسبًا للفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص358–359، تحت عنوان «مناسبة الفاصلة لما قبلها»","url":""}]},{"id":"s6-944","number":944,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"ما الصورة التي يفيدها قوله تعالى: ﴿لا أجد فيما أوحي إلي محرمًا﴾؟","answer":"صوّر مراجعة الوحي والبحث فيه حتى كأن الحكم شيء يطلب ويعثر عليه؛ والنتيجة أنه لا تحريم فيه إلا لما نص الله عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص369، تحت عنوان «نكتة المجاز في الفعل ﴿لا أجد﴾»","url":""}]},{"id":"s6-1372","number":1372,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"كيف أدمجت الآية الرد على المشركين في بيان المحرمات للمسلمين؟","answer":"بينما تسرد الآية ما حُرّم حقًا، جاء قول ﴿لا أجد﴾ ردًا ضمنيًا على تحريم المشركين؛ فجمع السياق تعليم المؤمنين وإبطال الافتراء في عبارة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص369–370، تحت عنوان «بلاغة إدماج في سياق ذكر ما حرم على المسلمين»","url":""}]},{"id":"s6-945","number":945,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا قيل ﴿على طاعم يطعمه﴾ بدل آكل يأكله؟","answer":"لأن الطعم يشمل كل ما يتناوله الإنسان غذاءً، ويستحضر الذوق والانتفاع؛ فعمم الحكم في كل طاعم وأكد أن التحريم متعلق بتناول الشيء طعامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص371–372، تحت عنوان «سر التعبير بـ﴿على طاعم يطعمه﴾ بدل (آكل يأكله)»","url":""}]},{"id":"s6-946","number":946,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا قُيد الدم بـ﴿مسفوحًا﴾؟","answer":"المسفوح هو الدم الجاري المصبوب عند الذبح؛ فالقيد يخرج الدم الباقي في العروق واللحم مما لا يمكن الاحتراز منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص375، تحت «علة تقييد الدم بـ(المسفوح)»","url":""}]},{"id":"s6-947","number":947,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا وصف لحم الخنزير بأنه ﴿رجس﴾؟","answer":"لأن الرجس ما تستقذره الفطرة ويجب اجتنابه، فبيّن اللفظ خبث المحرّم وشدة النفرة منه، ولم يكتف بمجرد ذكر المنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص377، تحت عنوان «نكتة ذكر لفظ ﴿رجس﴾»","url":""}]},{"id":"s6-948","number":948,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا وصف ما أُهل لغير الله به بأنه ﴿فسقًا﴾؟","answer":"لأن الفسق خروج عن طاعة الله، والذبح باسم غيره يجمع المعصية والشرك؛ فجعله اللفظ عين الفسق مبالغة في كشف قبحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص378، تحت عنوان «سر التعبير بلفظ (الفسق)»","url":""}]},{"id":"s6-949","number":949,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"ماذا يفيد ختم حكم المضطر بقوله تعالى: ﴿غفور رحيم﴾؟","answer":"يبين أن الله رفع الإثم عمن ألجأته الضرورة من غير بغي ولا تجاوز؛ فالمغفرة تمحو المؤاخذة، والرحمة أباحت ما يحفظ الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص384–385، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿غفور رحيم﴾»","url":""}]},{"id":"s6-950","number":950,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"ما دلالة التعريف في كلمة ﴿والدم﴾ في آية المائدة؟","answer":"التعريف للعهد؛ فالمراد الدم المعهود الذي بينته آية الأنعام بأنه المسفوح، لا كل أثر من الدم يبقى في اللحم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص533–534، تحت «دلالة (الـ) في كلمة ﴿والدم﴾»","url":""}]},{"id":"s6-1419","number":1419,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا قُيِّد الدم في آية الأنعام بكونه ﴿مسفوحًا﴾؟","answer":"ليختص التحريم بالدم السائل المصبوب، ويخرج الدم الذي يبقى في العروق أو يخالط اللحم ولا يمكن الاحتراز منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص375، تحت «علة تقييد الدم بـ(المسفوح)»","url":""}]},{"id":"s6-951","number":951,"surah":6,"verses":[146],"references":[{"surah":6,"verses":[146]}],"verseLabel":"الأنعام: 146","question":"لماذا خص ﴿الذين هادوا﴾ بتحريم كل ذي ظفر؟","answer":"خُص اليهود لأن التحريم كان عقوبة لهم على بغيهم، لا حكمًا أصليًا عامًا في جميع الأمم؛ فالتخصيص يمهد لتعليل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص392–393، 396–397، تحت «نكتة تقديم شبه الجملة على متعلقها؛ الموقع البياني لقوله: ﴿ذلك جزيناهم ببغيهم﴾؛ معنى الباء في عبارة ﴿ببغيهم﴾»","url":""}]},{"id":"s6-952","number":952,"surah":6,"verses":[146],"references":[{"surah":6,"verses":[146]}],"verseLabel":"الأنعام: 146","question":"لماذا جُمعت شحوم البقر والغنم ثم استثنيت ثلاثة مواضع؟","answer":"ذُكر التحريم أولًا، ثم فُصلت مواضع الاستثناء: ما تعلق بالظهور، والحوايا، وما اختلط بعظم. فانتقل البيان من الإجمال إلى تعيين المستثنى، ليُعرف موضع التحريم وموضع الإباحة، ولا يعمم أحد الحكمين على جميع الشحوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص394–396، تحت «دلالة الاستثناء في قوله: ﴿إلا ما حملت ظهورهما﴾؛ إفادة ﴿أو﴾ معنى العطف أو الإباحة في قوله ﴿أو الحوايا﴾؛ معنى الباء في قوله: ﴿أو ما اختلط بعظم﴾»","url":""}]},{"id":"s6-953","number":953,"surah":6,"verses":[146],"references":[{"surah":6,"verses":[146]}],"verseLabel":"الأنعام: 146","question":"لماذا جُعل تحريم بعض الطيبات على اليهود جزاءً لبغيهم؟","answer":"لأنه عقوبة على تجاوزهم وعصيانهم؛ فسُلبوا بعض ما كان حلالًا لهم، وربط قوله ﴿ببغيهم﴾ شدة الحكم بسببها حتى لا يظن أنه تشريع عام أصلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص396–397، تحت عنوان «الموقع البياني لقوله: ﴿ذلك جزيناهم ببغيهم﴾»","url":""}]},{"id":"s6-954","number":954,"surah":6,"verses":[146],"references":[{"surah":6,"verses":[146]}],"verseLabel":"الأنعام: 146","question":"ما أثر تتابع المؤكدات في قوله تعالى: ﴿وإنا لصادقون﴾؟","answer":"اجتمعت إن واللام والجملة الاسمية لتثبيت صدق الخبر والرد على تكذيب اليهود وتحريفهم سبب التحريم؛ فلا يبقى مجال للشك في أن الحكم جزاء بغيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص397–398، تحت عنوان «بلاغة تتابع المؤكدات للمبالغة»","url":""}]},{"id":"s6-955","number":955,"surah":6,"verses":[147],"references":[{"surah":6,"verses":[147]}],"verseLabel":"الأنعام: 147","question":"لماذا أُخبر المكذبون بأن ربهم ﴿ذو رحمة واسعة﴾؟","answer":"ليفتح لهم باب الرجاء قبل الوعيد؛ فإمهالهم مع التكذيب مظهر من رحمته ودعوة إلى التوبة، لا علامة رضا عن باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص406، تحت عنوان «فائدة الإخبار عن الرب بقوله ﴿ذو رحمة واسعة﴾»","url":""}]},{"id":"s6-1373","number":1373,"surah":6,"verses":[147],"references":[{"surah":6,"verses":[147]}],"verseLabel":"الأنعام: 147","question":"ما الذي يوحي به وصف رحمة الله بأنها ﴿واسعة﴾؟","answer":"يوحي بأنها تعم الخلق وتسبق العقوبة، فلا يضيق بها ذنب من رجع إلى الله؛ ومع سعتها لا يجوز الاغترار بها والإصرار على التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص408، تحت عنوان «نكتة وصف رحمة الله تعالى بالاتساع»","url":""}]},{"id":"s6-956","number":956,"surah":6,"verses":[147],"references":[{"surah":6,"verses":[147]}],"verseLabel":"الأنعام: 147","question":"ما الذي تضيفه كلمة ﴿ذو﴾ في قوله: ﴿ربكم ذو رحمة واسعة﴾؟","answer":"يبين المصدر أن ﴿ذو﴾ تدل هنا على ملازمة الصفة وثبوتها، وتضاف إلى اسم يدل على معنى كالرحمة والعلم. فالتعبير يقرر أن الرحمة صفة ثابتة لله، ثم يأتي وصفها بالسعة ليزيد الرجاء في رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص407، تحت «نكتة التعبير بـ﴿ذو﴾ دون (صاحب)»","url":""}]},{"id":"s6-957","number":957,"surah":6,"verses":[147],"references":[{"surah":6,"verses":[147]}],"verseLabel":"الأنعام: 147","question":"لماذا عُبر عن الرحمة بالجملة الاسمية وعن البأس بالجملة الفعلية؟","answer":"لأن الرحمة صفة ثابتة واسعة لربهم، فناسبها الأسلوب الدال على الثبوت؛ أما البأس فوعيد بحدث يقع إذا أصر المجرمون، فناسبه التعبير بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص409، تحت عنوان «مناسبة التعبير عن اتساع رحمة الله بالجملة الاسمية، وعن الترهيب بالجملة الفعلية»","url":""}]},{"id":"s6-958","number":958,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"ما دلالة احتجاج المشركين بقولهم: ﴿لو شاء الله ما أشركنا﴾؟","answer":"أرادوا أن يجعلوا وقوع الشرك والتحريم دليلًا على رضا الله بهما، وأن يسقطوا مسؤوليتهم بالمشيئة؛ فخلطوا بين مشيئة وقوع الشيء وبين محبته والأمر به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص417، تحت عنوان «دلالة احتجاج المشركين بالمشيئة»","url":""}]},{"id":"s6-1374","number":1374,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"لماذا سمّى القرآن احتجاجهم بالمشيئة تكذيبًا؟","answer":"لأنهم لم يكتفوا بالمعصية، بل نسبوا إلى الله الرضا بها واتخذوا مشيئته حجة على باطلهم؛ فكذبوا الرسل وخالفوا ما جاءهم من أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص420–421، تحت عنوان «نكتة التعبير بالكذب عن احتجاجهم»","url":""}]},{"id":"s6-1375","number":1375,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"لماذا جُعل ذوق البأس غاية لتكذيب الأمم السابقة؟","answer":"لأنهم استمروا على التكذيب حتى انتهى بهم إلى معاينة العقوبة؛ فبيّن التعبير أن الإمهال لم يكن رضا، وأن عاقبة الإصرار كانت ذوق البأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص421، تحت عنوان «علة جعل ﴿حتى ذاقوا بأسنا﴾ غاية للتكذيب»","url":""}]},{"id":"s6-1376","number":1376,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"ماذا يفيد الاستفهام في قوله تعالى: ﴿قل هل عندكم من علم﴾؟","answer":"يتحداهم أن يبرزوا أي علم يثبت دعواهم، وفيه إنكار أن يكون عندهم وحي أو برهان؛ فلا يبقى لهم إلا الظن والافتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص423، تحت عنوان «دلالة الاستفهام في ﴿قل هل عندكم﴾»","url":""}]},{"id":"s6-959","number":959,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"لماذا أدخل المشركون آباءهم في قولهم: ﴿ولا آباؤنا﴾؟","answer":"ليجعلوا قدم ما ورثوه وكثرة من سبقهم إليه سندًا لدعواهم؛ فجمعوا تقليد الآباء إلى الاحتجاج بالمشيئة، مع أن شيوع الباطل لا يصيره حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص419، تحت عنوان «علة ذكر آبائهم معهم»","url":""}]},{"id":"s6-960","number":960,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى ذاقوا بأسنا﴾؟","answer":"الذوق أصله إدراك المطعوم مباشرة، فاستعير لمباشرة العذاب ومعاناة أثره؛ ليبين أن حجتهم لم تمنع عن السابقين بأس الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص421، تحت «بلاغة المجاز في قوله: ﴿حتى ذاقوا بأسنا﴾»","url":""}]},{"id":"s6-961","number":961,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"ما الصورة في قوله تعالى عن العلم: ﴿فتخرجوه لنا﴾؟","answer":"صوّر العلم بحجة مخبوءة يمكن إخراجها وإظهارها للناس؛ وفي هذا تحدٍّ يكشف أنهم لا يملكون شيئًا يخرجونه دليلًا على دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص425، تحت عنوان «بلاغة الاستعارة التصريحية في قوله ﴿فتخرجوه﴾»","url":""}]},{"id":"s6-962","number":962,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"لماذا قُدّم اتباع الظن على الخرص في وصف حجتهم؟","answer":"لأن الظن هو الأصل الفاسد الذي اعتمدوه، ثم نشأ عنه الخرص والكلام بلا علم؛ فرتبت الآية فساد الاعتقاد قبل فساد القول الناتج منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص429، تحت عنوان «نكتة تقديم اتباع الظن على الخرص»","url":""}]},{"id":"s6-963","number":963,"surah":6,"verses":[149],"references":[{"surah":6,"verses":[149]}],"verseLabel":"الأنعام: 149","question":"ما سرّ تقديم ﴿لله﴾ في ﴿فلله الحجة البالغة﴾؟","answer":"تقديم ﴿لله﴾ يفيد الاختصاص: الحجة الكاملة له وحده، لا لمن يحتج بالظن على الشرك والمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص435، تحت «دلالة الفاء في قوله: ﴿فلله﴾، وتقديم المسند على المسند إليه»","url":""}]},{"id":"s6-964","number":964,"surah":6,"verses":[149],"references":[{"surah":6,"verses":[149]}],"verseLabel":"الأنعام: 149","question":"لماذا عُرّفت ﴿الحجة﴾ ووُصفت بأنها ﴿البالغة﴾؟","answer":"لأنها حجة الله المعهودة التي تبلغ غاية البيان والإلزام وتقطع العذر؛ فقد منح الاختيار وأرسل الرسل وبيّن الطريق، فلا تبقى حجة لمخالف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص435–436، تحت عنوان «بلاغة تعريف لفظ ﴿الحجة﴾، وعلة وصفها بـ﴿البالغة﴾»","url":""}]},{"id":"s6-965","number":965,"surah":6,"verses":[149],"references":[{"surah":6,"verses":[149]}],"verseLabel":"الأنعام: 149","question":"لماذا عبّر بالمشيئة في قوله تعالى: ﴿فلو شاء لهداكم أجمعين﴾؟","answer":"لأن المشيئة تتعلق بوقوع الهداية في الكون؛ فلو شاء الله إلجاء الناس إليها لوقعت، لكنه شاء أن يكلّفهم ويختبر اختيارهم بعد إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص437، تحت عنوان «سر إيثار فعل المشيئة دون الإرادة، والتعبير بصيغة الماضي»","url":""}]},{"id":"s6-1377","number":1377,"surah":6,"verses":[149],"references":[{"surah":6,"verses":[149]}],"verseLabel":"الأنعام: 149","question":"ما الفرق بين قول الله: ﴿فلو شاء لهداكم أجمعين﴾ وقول المشركين: ﴿لو شاء الله ما أشركنا﴾؟","answer":"قول الله يقرر قدرته على هداية الإلجاء مع إبقاء التكليف والاختيار، أما قولهم فيجعل المشيئة عذرًا للشرك ودليلًا على الرضا به؛ فالأول حجة عليهم والثاني تهرب من المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص437–438، تحت عنوان «الفرق بين الجملتين: ﴿فلو شاء لهداكم﴾ و﴿لو شاء الله ما أشركنا﴾»","url":""}]},{"id":"s6-966","number":966,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿هلم شهداءكم﴾، دون أن يقال: أحضروا؟","answer":"﴿هلم﴾ لفظ دعوة واستحضار، ومعناه هنا: أحضروا شهداءكم. ويذكر المصدر أن فيه استدعاءً للمأمور وتقريبًا له للإقبال على الأمر؛ فالمقام ينقل دعواهم إلى امتحان مباشر: من يشهد أن الله حرم هذا؟","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص443–444، تحت «معنى ﴿هلم﴾، ودلالة التعبير به دون غيره»","url":""}]},{"id":"s6-967","number":967,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"لماذا قيل: ﴿فإن شهدوا فلا تشهد معهم﴾ مع أن شهادتهم باطلة؟","answer":"لأن الموافقة الظاهرة قد توهم تصديقهم، فنُهي الرسول عن مشاركتهم شهادتهم أو إقرارها؛ فصدور الشهادة منهم لا يمنح الباطل حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص448، تحت عنوان «علة التعبير بقوله تعالى: ﴿فإن شهدوا فلا تشهد معهم﴾»","url":""}]},{"id":"s6-968","number":968,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"لماذا عُطف النهي عن اتباع أهوائهم على النهي عن موافقتهم في الشهادة؟","answer":"لأن شهادتهم الباطلة ثمرة أهوائهم؛ فبعد منع تصديق القول نهى عن اتباع الأصل الذي ولّده، ليُغلق طريق الباطل من جذره.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص448، تحت عنوان «دلالة عطف جملة ﴿ولا تتبع﴾ على ما قبلها»","url":""}]},{"id":"s6-1378","number":1378,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"لماذا قيل: ﴿أهواء الذين كذبوا بآياتنا﴾ ولم يقل: أهواءهم؟","answer":"ليبيّن الوصف سبب النهي: أهواؤهم قادتهم إلى تكذيب الآيات، وليعم التحذير كل من جعل الهوى مقدمًا على الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص449، تحت عنوان «وضع المظهر موضع المضمر»","url":""}]},{"id":"s6-969","number":969,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"لماذا صُرّح بلفظ ﴿ربهم﴾ في قوله تعالى: ﴿وهم بربهم يعدلون﴾؟","answer":"ليستحضر ما للرب من تربية وإنعام عليهم، فيشتد استنكار أن يسووا به من لا يخلق ولا يرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص451، تحت عنوان «دلالة التعبير بالاسم الظاهر في ﴿وهم بربهم يعدلون﴾»","url":""}]},{"id":"s6-970","number":970,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا افتتح بيان المحرمات بقوله تعالى: ﴿تعالوا﴾؟","answer":"لأنها دعوة إلى الإقبال والارتفاع عن افتراء التحريم إلى تلقي حكم الله، وفيها استدعاء للسامعين كي يصغوا إلى الوصايا الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص460، تحت عنوان «إيثار التعبير بقوله: ﴿تعالوا﴾، والعدول عن مرادفاته»","url":""}]},{"id":"s6-1379","number":1379,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"ما دلالة اختيار الفعل ﴿أتل﴾ في قوله تعالى: ﴿أتل ما حرم ربكم عليكم﴾؟","answer":"يدل على أن البيان وحي يُقرأ ويتبع، لا رأي يبتدعه البشر؛ فالمتكلم يتلو أمر الله في الحلال والحرام كما أُنزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص461–462، تحت عنوان «دلالة الفعل ﴿أتل﴾ ووجه جزمه»","url":""}]},{"id":"s6-1380","number":1380,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا بدأت الوصايا بالنهي عن الشرك؟","answer":"لأن التوحيد أصل صلاح الاعتقاد والعمل، فإذا فسد الأصل لم تنفع الأعمال المبنية عليه؛ فكان إصلاحه مقدمًا على سائر الوصايا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص466، تحت عنوان «بلاغة البدء بالنهي عن الشرك دون ما بعده»","url":""}]},{"id":"s6-971","number":971,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا جاء الإحسان إلى الوالدين بعد النهي عن الشرك؟","answer":"لأن حق الوالدين أعظم حقوق الخلق بعد حق الله، فانتقل من إصلاح الاعتقاد إلى الوفاء بمن كانا سبب الوجود والرعاية، ليجتمع صلاح الدين وصلاح الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص466–467، تحت عنوان «دلالة عطف جملة ﴿وبالوالدين إحسانًا﴾ على ما قبلها»","url":""}]},{"id":"s6-972","number":972,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا قال في الأنعام: ﴿نحن نرزقكم وإياهم﴾، وفي الإسراء: ﴿نحن نرزقهم وإياكم﴾؟","answer":"في الأنعام كان الفقر واقعًا بالآباء فقدم ضمان رزقهم، أما في الإسراء فكان الخوف من فقر متوقع بسبب الأولاد فقدم ضمان رزقهم؛ فجاء كل ترتيب على موضع القلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص471–472، تحت عنوان «بلاغة فن التغاير بين آيتي الأنعام والإسراء»","url":""}]},{"id":"s6-973","number":973,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا نهى الله عن قرب الفواحش لا عن فعلها فقط؟","answer":"لأن النهي عن القرب يسد المقدمات والذرائع التي تقود إليها، فيحمي الإنسان قبل الوقوع بدل أن يقتصر على تحريم الفعل بعد بلوغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص473، تحت عنوان «بلاغة النهي عن قرب الفواحش»","url":""}]},{"id":"s6-974","number":974,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا ذُكر ﴿ما ظهر﴾ و﴿ما بطن﴾ بعد النهي العام عن الفواحش؟","answer":"لتأكيد استيعاب النهي للفواحش المعلنة والمستترة، ولأعمال الجوارح وخفايا القلوب؛ فلا يخفف قبح المعصية أن تُستر عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص474، تحت عنوان «النهي عما ظهر وما بطن بعد النهي العام عن الفواحش»","url":""}]},{"id":"s6-975","number":975,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا خُتمت هذه الوصايا بـ﴿لعلكم تعقلون﴾، واختلفت عن الفواصل اللاحقة؟","answer":"لأن هذه الوصايا أصول يدرك العقل قبح أضدادها، فدعت الفاصلة إلى تشغيل العقل فيها؛ ثم جاءت التذكر والتقوى في المواضع اللاحقة بحسب مضمون كل مجموعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص480–481، تحت عنوان «بلاغة التذييل هنا وسر اختلافه عن لواحقه»","url":""}]},{"id":"s6-976","number":976,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تقربوا مال اليتيم﴾ كما قال في الفواحش؟","answer":"النهي عن القرب يمنع كل تصرف يعرض مال اليتيم للنقص، لا مجرد أكله؛ ثم استثنى التصرف الذي يحقق مصلحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص492، تحت «بلاغة الكناية في قوله: ﴿ولا تقربوا مال اليتيم﴾»","url":""}]},{"id":"s6-977","number":977,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"لماذا قيل في مال اليتيم: ﴿إلا بالتي هي أحسن﴾؟","answer":"ليجعل المسموح به أخصّ وجوه التصرف وأنفعها لليتيم، فلا يكفي أن يكون التصرف حسنًا في الجملة، بل يجب أن يكون هو الأبعد عن الضرر والأقرب إلى تنمية ماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص495، تحت عنوان «نكتة التعبير بالاسم الموصول في قوله: ﴿إلا بالتي هي أحسن﴾»","url":""}]},{"id":"s6-1381","number":1381,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما دلالة قوله: ﴿هي أحسن﴾ في حماية مال اليتيم؟","answer":"الجملة تثبت أن الخصلة المختارة هي الأحسن على وجه مستقر، واسم التفضيل يلزم الولي بموازنة البدائل واختيار أصلحها لليتيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص496، تحت عنوان «دلالة اسمية الجملة واختيار اسم التفضيل في قوله: ﴿هي أحسن﴾»","url":""}]},{"id":"s6-978","number":978,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ماذا يفيد قوله تعالى في مال اليتيم: ﴿حتى يبلغ أشده﴾؟","answer":"يجعل بلوغ القوة والرشد غايةً للمنع من تسليم المال؛ فإذا اكتمل استعداد اليتيم لحسن التصرف دُفع إليه ماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص497، تحت عنوان «دلالة تركيب ﴿حتى يبلغ أشده﴾ ونوع المجاز فيه»","url":""}]},{"id":"s6-1382","number":1382,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما الفرق بين أشد اليتيم وأشد الرجل؟","answer":"أشد اليتيم هو بلوغه حدّ الرشد الذي يؤهله لتدبير ماله، أما أشد الرجل فهو اكتمال قوته ونضجه بعد ذلك؛ فلكل سياق الغاية المناسبة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص498، تحت عنوان «الفرق بين أشد اليتيم وأشد الرجل»","url":""}]},{"id":"s6-979","number":979,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما بلاغة قوله تعالى: ﴿لا نكلف نفسًا إلا وسعها﴾ بعد الأمر بالعدل في الكيل والميزان؟","answer":"هو احتراس يرفع الحرج عن الخطأ الذي لا يمكن التحرز منه بعد بذل الجهد، من غير أن يرخّص في التطفيف؛ فجمع وجوب العدل وسماحة التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص502–503، تحت عنوان «بلاغة الاحتراس في قوله: ﴿لا نكلف نفسًا إلا وسعها﴾»","url":""}]},{"id":"s6-980","number":980,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو كان ذا قربى﴾، دون أن يقال: ولو كان قريبًا؟","answer":"يذكر المصدر أن التعبير يتسع لأنواع الصلة، كقرابة النسب والمصاهرة وغيرها، فيشمل ما قد يميل بسببه الإنسان إلى صاحبه. والمعنى أن هذه الروابط كلها لا تسوغ المحاباة في القول والحكم؛ فالعدل واجب معها أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص512–513، تحت «نكتة التعبير بقوله: ﴿ذا قربى﴾»","url":""}]},{"id":"s6-981","number":981,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"لماذا خُتمت الوصايا بقوله تعالى: ﴿لعلكم تذكرون﴾؟","answer":"لأن الوصايا عهد مركوز في الفطرة وتؤكده الرسالات، فالمطلوب أن يستحضرها الإنسان ولا تغلبه الغفلة والهوى؛ وجاء التذييل حاثًا على دوام التذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص517–518، تحت عنوان «سر ختم الآية بقوله: ﴿لعلكم تذكرون﴾»","url":""}]},{"id":"s6-982","number":982,"surah":6,"verses":[153],"references":[{"surah":6,"verses":[153]}],"verseLabel":"الأنعام: 153","question":"لماذا أُفرد ﴿الصراط﴾ وجُمعت ﴿السبل﴾؟","answer":"لأن الحق طريق واحد مستقيم يوصل إلى الله، أما طرق البدع والضلال فكثيرة متفرقة؛ فدل اختلاف العدد على وحدة الهدى وتشعب الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص530، تحت عنوان «غرض العدول من الصراط إلى السبل بالجمع»","url":""}]},{"id":"s6-983","number":983,"surah":6,"verses":[153],"references":[{"surah":6,"verses":[153]}],"verseLabel":"الأنعام: 153","question":"لماذا أضيف الصراط إلى الله: ﴿صراطي﴾؟","answer":"إضافته إلى الله تشريف وتعيين لمصدره: هذا طريقه الذي شرعه الموصل إليه، فلا يلتبس بطرق البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص527، تحت «نكتة إضافة الصراط إلى الياء»","url":""}]},{"id":"s6-984","number":984,"surah":6,"verses":[153],"references":[{"surah":6,"verses":[153]}],"verseLabel":"الأنعام: 153","question":"ما الصورة التي يرسمها قوله تعالى: ﴿فتفرق بكم عن سبيله﴾؟","answer":"يمثل السبل المتشعبة بطرق تسحب سالكيها بعيدًا عن الطريق المستقيم، فتفرّق الجماعة وتبعدها عن الغاية؛ فتتحول الضلالة إلى مشهد محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص530–531، تحت عنوان «بلاغة التمثيل»","url":""}]},{"id":"s6-985","number":985,"surah":6,"verses":[153],"references":[{"surah":6,"verses":[153]}],"verseLabel":"الأنعام: 153","question":"لماذا خُتمت وصية الصراط بقوله تعالى: ﴿لعلكم تتقون﴾؟","answer":"لأن لزوم الطريق الواحد وترك السبل هو العمل الذي يحمي من الضلال ويجدد التقوى؛ فجاء الرجاء متعلقًا باستمرارهم على أسباب الوقاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص534، تحت عنوان «نكتة التعبير بـ(لعل) دون غيرها في قوله: ﴿لعلكم تتقون﴾»","url":""}]},{"id":"s6-986","number":986,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"لماذا بدأ بـ﴿ثم آتينا موسى الكتاب﴾ مع أن إيتاء موسى أسبق زمنًا؟","answer":"﴿ثم﴾ لترتيب الأخبار أو للانتقال الرتبي إلى شاهد آخر على تمام الحجة، لا للترتيب الزمني؛ فإيتاء موسى سابق معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص538–539، تحت «دلالة العطف بـ﴿ثم﴾»","url":""}]},{"id":"s6-987","number":987,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"لماذا وُصف إيتاء موسى الكتاب بأنه ﴿تمامًا﴾؟","answer":"لأنه أتم النعمة والبيان لبني إسرائيل، فجمع لهم أصول الشريعة وما يحتاجون إليه من الهداية والتفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص541، تحت عنوان «نكتة التعبير بـ﴿تمامًا﴾»","url":""}]},{"id":"s6-1383","number":1383,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"من الذي يشمله قوله تعالى: ﴿على الذي أحسن﴾، وما فائدة التعبير بالموصول؟","answer":"يحتمل موسى الذي أحسن الطاعة، ويحتمل جنس المحسنين؛ وفي الحالتين يعلق الموصول تمام النعمة بصفة الإحسان، فيفتح المعنى لكل من تحققت فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص541–542، تحت عنوان «غرض التعبير بالاسم الموصول»","url":""}]},{"id":"s6-988","number":988,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"ماذا يضيف قوله تعالى عن الكتاب: ﴿وتفصيلًا لكل شيء﴾؟","answer":"يبين أن الكتاب لم يأت مجملًا مبهمًا، بل فصل لبني إسرائيل ما يحتاجون إليه في شريعتهم وأحكامهم؛ فتم به البيان بعد تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص542، تحت عنوان «دلالة العطف في ﴿وتفصيلًا لكل شيء﴾»","url":""}]},{"id":"s6-1384","number":1384,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"لماذا جمع في وصف الكتاب بين ﴿هدى ورحمة﴾؟","answer":"لأنه يرشد إلى الحق فيكون هدى، ويثمر النجاة والخير لمن اتبعه فيكون رحمة؛ فجمع الدلالة على الطريق وأثر سلوكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص543–544، تحت عنوان «دلالة العطف والتنكير في قوله ﴿وهدى ورحمة﴾»","url":""}]},{"id":"s6-989","number":989,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿لعلهم بلقاء ربهم يؤمنون﴾ بتقديم ﴿بلقاء ربهم﴾؟","answer":"قُدّم الجار والمجرور للاهتمام بلقاء الله وما فيه من بعث وجزاء؛ فاستحضار هذا اللقاء يدفع إلى الإيمان والاستقامة على شرعه والعمل بهدى الكتاب. ويذكر المصدر أيضًا مراعاة الفواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص546، تحت «بلاغة تقديم شبه الجملة في قوله: ﴿بلقاء ربهم يؤمنون﴾»","url":""}]},{"id":"s6-990","number":990,"surah":6,"verses":[155],"references":[{"surah":6,"verses":[155]}],"verseLabel":"الأنعام: 155","question":"لماذا جاء قوله تعالى: ﴿وهذا كتاب أنزلناه مبارك﴾ بعد ذكر كتاب موسى؟","answer":"ليصل القرآن بسلسلة الوحي قبله، ويبين أن مصدر الكتابين واحد، ثم ينتقل من خبر الكتاب السابق إلى دعوة المخاطبين لاتباع الكتاب المنزل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص550، تحت عنوان «وجه عطف جملة ﴿وهذا كتاب﴾ على ما تقدم»","url":""}]},{"id":"s6-1385","number":1385,"surah":6,"verses":[155],"references":[{"surah":6,"verses":[155]}],"verseLabel":"الأنعام: 155","question":"ما فائدة تنكير ﴿كتاب﴾ في قوله تعالى: ﴿وهذا كتاب أنزلناه مبارك﴾؟","answer":"للتعظيم؛ فهو كتاب عظيم الشأن كثير البركة، مهيمن على ما سبقه وجدير بأن يُتبع ويُعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص551، تحت عنوان «فائدة تنكير لفظ ﴿كتاب﴾»","url":""}]},{"id":"s6-991","number":991,"surah":6,"verses":[155],"references":[{"surah":6,"verses":[155]}],"verseLabel":"الأنعام: 155","question":"لماذا فُرّع على بركة القرآن قوله تعالى: ﴿فاتبعوه واتقوا﴾؟","answer":"لأن كونه كتابًا منزلًا مباركًا يقتضي العمل به: اتباع أوامره وهديه، واتقاء مخالفته وما حذر منه؛ فكانت الأوامر ثمرة مباشرة لوصفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص552–553، تحت عنوان «التفريع في قوله تعالى: ﴿فاتبعوه واتقوا﴾»","url":""}]},{"id":"s6-992","number":992,"surah":6,"verses":[155],"references":[{"surah":6,"verses":[155]}],"verseLabel":"الأنعام: 155","question":"ما وجه الترقي في قوله تعالى: ﴿فاتبعوه واتقوا لعلكم ترحمون﴾؟","answer":"بدأ باتباع الكتاب عملًا، ثم بالتقوى وقايةً من المخالفة، ثم جعل الرحمة ثمرة لذلك؛ فانتقل من السبب إلى كماله ثم إلى الجزاء المرجو.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص554–555، تحت عنوان «الترقي في قوله: ﴿فاتبعوه واتقوا لعلكم ترحمون﴾»","url":""}]},{"id":"s6-993","number":993,"surah":6,"verses":[156],"references":[{"surah":6,"verses":[156]}],"verseLabel":"الأنعام: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تقولوا إنما أنزل الكتاب على طائفتين من قبلنا﴾؟","answer":"أنزل القرآن لقطع عذرهم أن الكتب السابقة نزلت على اليهود والنصارى وحدهم وأن العرب غافلون عن قراءتها وفهمها؛ فقد جاءهم كتاب بلغتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص558، 561–562، تحت «غرض حذف لام التعليل في قوله: ﴿أن تقولوا﴾؛ المجاز المرسل في قوله: ﴿عن دراستهم﴾»","url":""}]},{"id":"s6-994","number":994,"surah":6,"verses":[156],"references":[{"surah":6,"verses":[156]}],"verseLabel":"الأنعام: 156","question":"لماذا قيل: ﴿على طائفتين من قبلنا﴾ من غير تسمية اليهود والنصارى؟","answer":"لأن الطائفتين معلومتان للمخاطبين بكونهما أهل التوراة والإنجيل، فدل التنكير عليهما مع إبراز أنهما جماعتان سبقتا العرب إلى تلقي الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص559، تحت عنوان «دلالة التنكير في لفظ ﴿طائفتين﴾»","url":""}]},{"id":"s6-995","number":995,"surah":6,"verses":[156],"references":[{"surah":6,"verses":[156]}],"verseLabel":"الأنعام: 156","question":"ماذا تكني عبارة ﴿عن دراستهم لغافلين﴾؟","answer":"تكني عن بعد العرب عن قراءة كتب الطائفتين وفهمها واتباع ما فيها، فلا يملكون علمًا مباشرًا بها؛ وقد جاءهم القرآن بلسانهم فقطع هذا العذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص562، تحت عنوان «الكناية عن الاتباع أو عدمه في لفظ ﴿لغافلين﴾»","url":""}]},{"id":"s6-996","number":996,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"كيف تدرجت أعذار المشركين قبل نزول القرآن؟","answer":"انتقلوا من الاحتجاج بأن الكتاب نزل على طائفتين غيرهم، إلى دعوى الغفلة عن دراسته، ثم إلى زعم أنهم لو نزل عليهم كتاب لكانوا أهدى؛ فقطع القرآن الأعذار درجة بعد درجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص567، تحت عنوان «الترقي والتدرج في الاعتلال»","url":""}]},{"id":"s6-1386","number":1386,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما دلالة قولهم على سبيل الشرط: ﴿لو أنا أنزل علينا الكتاب لكنا أهدى منهم﴾؟","answer":"صاغوا وعدًا مفترضًا يزعمون فيه أن نزول كتاب عليهم سيجعلهم أشد اهتداء، فلما جاءتهم البينة صار قولهم حجة عليهم لا عذرًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص568، تحت عنوان «غرض التعبير بالشرطية في قولهم: ﴿لو أنا أنزل﴾»","url":""}]},{"id":"s6-997","number":997,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"لماذا كُنّي عن القرآن بقوله تعالى: ﴿بينة من ربكم﴾؟","answer":"لأن القرآن هو الحجة الواضحة التي تكشف الحق وتقطع العذر، فدل وصف البينة عليه بما اشتمل عليه من بيان وإعجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص572، تحت عنوان «البينة كناية عن موصوف هو القرآن في هذه الآية الكريمة»","url":""}]},{"id":"s6-1387","number":1387,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما فائدة الجمع بين ﴿البينة﴾ و﴿الهدى﴾ في وصف القرآن؟","answer":"هو بينة تقيم الحجة وتظهر صدق الرسالة، وهدى يرشد من يقبلها إلى الطريق؛ فجمع وضوح الدليل وثمرة الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص572–573، تحت عنوان «فائدة الجمع بين البينة والهدى»","url":""}]},{"id":"s6-998","number":998,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما دلالة الاستفهام في قوله تعالى: ﴿فمن أظلم ممن كذب بآيات الله﴾؟","answer":"هو إنكار ونفي أن يكون أحد أشد ظلمًا ممن عرف الآيات ثم كذب بها وأعرض عنها؛ فقد جمع رد الحق ومنع النفس من الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص574، تحت عنوان «بلاغة الاستفهام الإنكاري ودلالته في قوله: ﴿فمن أظلم﴾»","url":""}]},{"id":"s6-1388","number":1388,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما الفرق بين الإعراض والصد والصدوف؟","answer":"الإعراض ترك الالتفات إلى الشيء، والصد قد يكون انصرافًا عنه أو منعًا لغيره، أما الصدوف فهو أشدها دلالة على الميل والانحراف عن الحق؛ فاختياره يصور قوة إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص580، تحت عنوان «(الإعراض) و(الصد) و(الصدوف)»","url":""}]},{"id":"s6-999","number":999,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ماذا تفيد صيغة ﴿يصدفون﴾ والانتقال إلى الحديث عنهم بضمير الغائب؟","answer":"المضارع يصور إعراضهم فعلًا يتجدد، والالتفات يبعدهم عن مقام الخطاب كأنهم غير أهل للمواجهة بعد إصرارهم؛ فيتجدد مشهد الجريمة ويشتد تقريعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص577، تحت عنوان «فعلية جملة ﴿يصدفون﴾ ودلالة الالتفات»","url":""}]},{"id":"s6-1389","number":1389,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"لماذا أعيد فعل الصدوف في قوله تعالى: ﴿بما كانوا يصدفون﴾ بدل الإضمار؟","answer":"ليصرح بسبب الجزاء ويثبته في الذهن: سوء العذاب نتيجة صدوفهم نفسه، لا أمر آخر؛ فكان تكرار الفعل أبلغ في التوكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص577، تحت عنوان «الذكر في موضع الإضمار توكيدًا»","url":""}]},{"id":"s6-1000","number":1000,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما دلالة القصر في قوله تعالى: ﴿هل ينظرون إلا أن تأتيهم الملائكة أو يأتي ربك أو يأتي بعض آيات ربك﴾؟","answer":"يبين أنه لم يبق لهم بعد قيام الحجة إلا انتظار ما ينهي زمن الاختيار: حضور الملائكة، أو أمر الله، أو بعض العلامات الحاسمة؛ فهو قصر تهديد لا عذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص585، تحت عنوان «نكتة أسلوب القصر»","url":""}]},{"id":"s6-1001","number":1001,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما دلالة ترتيب إتيان الملائكة ثم ﴿يأتي ربك﴾ ثم إتيان بعض آياته في مشهد الوعيد؟","answer":"يذكر المصدر أن ترتيب هذه الجمل يرفع وقع التهديد في النفس؛ فالمشهد يتدرج في ذكر ما يواجه المكذبين من هول، ولا يبقى مجرد انتظار لآية يقترحونها. فالغرض تفخيم الوعيد وتخويفهم من عاقبة إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص587–588، تحت «سر تقديم بعض الجمل على بعض في الآية الكريمة»","url":""}]},{"id":"s6-1002","number":1002,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"لماذا أبهمت الآية علامات القيامة بقولها: ﴿بعض آيات ربك﴾؟","answer":"لأن المقصود ليس تعداد العلامات، بل التحذير من آية حاسمة ينتهي عند ظهورها زمن الاختيار وقبول الإيمان؛ فالإبهام يوقظ الترقب والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص587، تحت عنوان «غرض إبهام علامات القيامة»","url":""}]},{"id":"s6-1390","number":1390,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"لماذا أعيد لفظ ﴿بعض آيات ربك﴾ ظاهرًا بدل الضمير؟","answer":"للاحتراس من توهم أن المقصود في الموضع الثاني آية أخرى، ولتثبيت أن الحكم متعلق بتلك العلامة الحاسمة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص590، تحت عنوان «دلالة الاحتراس في التعبير بالظاهر بدل المضمر»","url":""}]},{"id":"s6-1003","number":1003,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"كيف أوجزت الآية أحوال الناس عند مجيء بعض آيات الله؟","answer":"قسمتهم إلى نفس لم تؤمن من قبل، ونفس آمنت لكنها لم تكسب خيرًا؛ فاستوعبت بإيجاز من فاتها أصل الإيمان ومن فرّط في ثمرة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص595، تحت عنوان «بلاغة الإيجاز في استعمال أسلوب التقسيم»","url":""}]},{"id":"s6-1391","number":1391,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما الذي أدمجه قوله تعالى: ﴿أو كسبت في إيمانها خيرًا﴾ في الوعيد؟","answer":"أدخل تحذير المؤمن من تأخير العمل الصالح داخل وعيد المكذب؛ فليس المطلوب سبق الإيمان وحده، بل أن يثمر خيرًا قبل فوات زمن الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص595، تحت عنوان «بلاغة الإدماج في قوله ﴿أو كسبت في إيمانها خيرًا﴾»","url":""}]},{"id":"s6-1004","number":1004,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما الغرض من الأمر في قوله تعالى: ﴿قل انتظروا﴾؟","answer":"هو تهديد للمكذبين: امضوا في انتظار الآيات والعقاب بعد قيام الحجة، فستظهر عاقبة التكذيب التي لا تنفع عندها المعاذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص596، تحت عنوان «الغرض البياني من الأمر بالانتظار»","url":""}]},{"id":"s6-1392","number":1392,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما دلالة جواب المؤمنين: ﴿إنا منتظرون﴾؟","answer":"يثبت يقينهم بوعد الله؛ فكما ينتظر المكذبون ما اقترحوه، ينتظر المؤمنون نصر الله ووقوع وعيده، والجملة الخبرية تؤكد ثباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص597، تحت عنوان «غرض الجملة الخبرية في قوله ﴿إنا منتظرون﴾»","url":""}]},{"id":"s6-1005","number":1005,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"لماذا عبّر عن مجيء الآيات بالفعل المضارع؟","answer":"ليستحضر المشهد المنتظر كأنه يتجدد أمام السامع، فيظل الوعيد حاضرًا في النفس ولا يتحول إلى خبر بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص586، تحت عنوان «سر التعبير بالمضارع بدلًا من الاسم»","url":""}]},{"id":"s6-1393","number":1393,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما أثر إسناد الإتيان إلى لفظ ﴿الرب﴾؟","answer":"يهوّل الموقف لأن الآتي هو ربهم المالك المدبر الذي لا يعجزه شيء، ويذكّرهم بأن من كفروا بآياته هو صاحب الحكم والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص587، تحت عنوان «أثر إسناد فعل الإتيان إلى لفظ (الرب)»","url":""}]},{"id":"s6-1006","number":1006,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"لماذا صُوّر صنيعهم بالدين بقوله تعالى: ﴿فرقوا دينهم﴾؟","answer":"صُوّر الدين الجامع كشيء واحد مزقوه أجزاء؛ إذ أخذوا بعضه وتركوا بعضه وخلطوا الحق بالباطل، فبددوا وحدته بعد أن كان سبب اجتماعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص603، تحت عنوان «دلالة المجاز من باب الاستعارة في قوله: ﴿فرقوا دينهم﴾»","url":""}]},{"id":"s6-1394","number":1394,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"لماذا قيل بعد تفريق الدين: ﴿وكانوا شيعًا﴾؟","answer":"لأن تفريق الدين لم يبق خلافًا عابرًا، بل حوّلهم فرقًا يتبع بعضها بعضًا ويناصر كل فريق رأيه؛ فبيّن التعبير ثمرة التفريق في واقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص604، تحت عنوان «نكتة التعبير بقوله ﴿شيعًا﴾ بعد وصفهم بتفريق الدين»","url":""}]},{"id":"s6-1007","number":1007,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"لماذا أعقب وصف المفرقين لدينهم بقوله تعالى: ﴿لست منهم في شيء﴾؟","answer":"ليعلن براءة الرسول ﷺ الكاملة من طريقتهم، ويقطع توهم أن التفرق والتحزب يمكن أن ينتسبا إلى الدين الذي جاء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص607، تحت عنوان «الموقع البياني لقوله: ﴿لست منهم في شيء﴾»","url":""}]},{"id":"s6-1395","number":1395,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"ما الذي يفيده تنكير ﴿شيء﴾ في قوله تعالى: ﴿لست منهم في شيء﴾؟","answer":"يفيد عموم البراءة: ليست بين منهجه وبين تفريقهم للدين أدنى صلة، فلا يلتقي معهم في قليل ولا كثير من باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص608، تحت عنوان «نكتة تنكير ﴿شيء﴾»","url":""}]},{"id":"s6-1396","number":1396,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"ما دلالة القصر في قوله تعالى: ﴿إنما أمرهم إلى الله﴾؟","answer":"يقصر الفصل في شأنهم وجزاءهم على الله وحده؛ فالرسول يبلّغ ويتبرأ من التفرق، أما السرائر والحساب النهائي فإلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص609، تحت عنوان «القصر وطريقته ونوعه في جملة ﴿إنما أمرهم إلى الله﴾»","url":""}]},{"id":"s6-1008","number":1008,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم ينبئهم بما كانوا يفعلون﴾؟","answer":"تنقل من إمهالهم في الدنيا إلى حسابهم بعد مهلة؛ فالتراخي لا يعني إهمال العمل، بل يؤكد أن الجزاء آت في موعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص609، تحت عنوان «دلالة الحرف ﴿ثم﴾ في قوله: ﴿ثم ينبئهم﴾»","url":""}]},{"id":"s6-1397","number":1397,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"لماذا عُبّر بالإنباء في قوله تعالى: ﴿ثم ينبئهم بما كانوا يفعلون﴾؟","answer":"لأن إخبارهم بأعمالهم يوم القيامة ليس خبرًا مجردًا، بل كشف لها وإقامة للحجة ثم معاقبة عليها؛ فكنّى الإنباء عن تمام المحاسبة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص610، تحت عنوان «التعبير بـ﴿ينبئهم﴾ كناية عن معاقبتهم جزاء أفعالهم»","url":""}]},{"id":"s6-1009","number":1009,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"لماذا أُفردت ﴿الحسنة﴾ و﴿السيئة﴾ في آية الجزاء؟","answer":"ليدخل في الحكم أدنى عمل من الجنسين: فالحسنة الواحدة تنال التضعيف، والسيئة الواحدة لا يزاد في جزائها على مثلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص618، تحت عنوان «نكتة إفراد الحسنة والسيئة في الآية الكريمة»","url":""}]},{"id":"s6-1398","number":1398,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"ما دلالة القصر في قوله تعالى عن السيئة: ﴿فلا يجزى إلا مثلها﴾؟","answer":"يحصر جزاء السيئة في قدرها، فيطمئن إلى عدل الله: لا يضاعف العقوبة كما تضاعف الحسنة، ولا يحمل أحد فوق ما عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص622، تحت عنوان «بلاغة القصر ونوعه في الاستثناء بعد النفي»","url":""}]},{"id":"s6-1010","number":1010,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"ما سرّ تقديم ﴿له﴾ في قوله تعالى: ﴿فله عشر أمثالها﴾؟","answer":"قُدّم للاختصاص والاهتمام: جزاء صاحب الحسنة ثابت له، وفيه إشعار بمنزلته حتى نال هذا التضعيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص620، تحت «غرض تقديم شبه الجملة في ﴿فله عشر أمثالها﴾»","url":""}]},{"id":"s6-1011","number":1011,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"ما سرّ بناء ﴿فلا يجزى﴾ للمجهول في جزاء السيئة؟","answer":"لأن المقصود إبراز مقدار الجزاء وعدله، لا ذكر المجازي المعلوم من السياق؛ فالسيئة لا يقابلها إلا مثلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص622، تحت «نكتة التعبير عن فعل الجزاء بالبناء للمفعول في ﴿يجزى﴾»","url":""}]},{"id":"s6-1012","number":1012,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"ما مناسبة ختام الآية بقوله تعالى: ﴿وهم لا يظلمون﴾؟","answer":"يقرر عدل الجزاء: لا تُنقص حسنة ولا تُزاد سيئة على مثلها؛ فالتضعيف فضل، وعدم زيادة العقاب عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص623–624، تحت «معنى الواو في ﴿وهم لا يظلمون﴾ وموقع الجملة بعدها؛ دلالة الضمير (هم) ومرجعيته في قوله: ﴿وهم لا يظلمون﴾»","url":""}]},{"id":"s6-1013","number":1013,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"كيف تكون مضاعفة الحسنة بين العشر والسبع مئة؟","answer":"العشر أصل عام لمضاعفة الحسنة، ثم تزيد المضاعفة إلى سبع مئة وأكثر بحسب العمل والإخلاص وفضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص621، تحت «مضاعفة الحسنات بين العشر والسبع مئة»","url":""}]},{"id":"s6-1420","number":1420,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"لماذا أطلقت آية البقرة المضاعفة من غير تقييدها بعشر أمثالها؟","answer":"لأن الخيرات تتفاوت باختلاف العاملين ونياتهم وأعمالهم، فناسب الإطلاق ما يفتحه الله من زيادة تبلغ سبع مئة أو أكثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص202، تحت «سر إطلاق المضاعفة دون تقييدها بعشر أمثالها»","url":""}]},{"id":"s6-1014","number":1014,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا انتقل ختام السورة من محاجة المشركين إلى إعلان الهداية في قوله: ﴿قل إنني هداني ربي﴾؟","answer":"لأن الحجج قد استوفت غرضها، فطُوي سجل الجدال بإعلان الطريق الذي ثبّت الله رسوله عليه، ليكون الختام موقفًا عمليًا واضحًا لا جدلًا ممتدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص628، تحت عنوان «طي سجل المحاجة مؤذن باختتام السورة الكريمة»","url":""}]},{"id":"s6-1399","number":1399,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"ما أثر المؤكدات في قوله تعالى: ﴿قل إنني هداني ربي﴾؟","answer":"تثبت يقين الرسول ﷺ بهداية ربه أمام إنكار المشركين، وتبرز رسوخ موقفه من غير تردد أو احتمال لمساومتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص629، تحت عنوان «نكتة اشتمال جملة ﴿إنني هداني﴾ على مؤكدات عدة»","url":""}]},{"id":"s6-1015","number":1015,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا استُعير ﴿الصراط المستقيم﴾ للدين الحق؟","answer":"لأن الدين يوصل سالكه إلى رضوان الله كما يوصل الطريق المستقيم إلى الغاية، ولا يضل سالكه بتعرج أو تشعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص630، تحت عنوان «بلاغة استعارة الصراط للدين القويم بجامع المشاكلة»","url":""}]},{"id":"s6-1400","number":1400,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا عُرّف الدين بأنه ﴿ملة إبراهيم﴾ بطريق الإضافة؟","answer":"لإبراز صلته بإبراهيم عليه السلام الذي يعظمه العرب وأهل الكتاب، وإقامة الحجة بأن التوحيد الخالص هو ملته الحقيقية لا ما نسبه المشركون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص632–633، تحت عنوان «حكمة التعبير بملة إبراهيم بطريق الإضافة»","url":""}]},{"id":"s6-1016","number":1016,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا وُصف الدين بأنه ﴿قِيَمًا﴾؟","answer":"للمبالغة في استقامته وثباته على الحق، فهو دين مستقيم في ذاته ومقيم لمصالح من يتبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص632، تحت عنوان «وصف الدين بأنه قيم من باب الاستعارة»","url":""}]},{"id":"s6-1017","number":1017,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا عُدل من نفي الشرك عن إبراهيم مفردًا إلى قوله: ﴿وما كان من المشركين﴾؟","answer":"لينفي عنه الانتماء إلى جماعة المشركين ومنهجهم كله، لا مجرد وقوع فعل شرك منه؛ وفيه إبطال لادعائهم أنهم على ملته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص635، تحت عنوان «نكتة العدول عن نفي الإشراك إفرادًا إلى نفي الإشراك جمعًا»","url":""}]},{"id":"s6-1018","number":1018,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"ما الفرق بين قوله في الأنعام: ﴿دينًا قيمًا﴾ وقوله في الفاتحة: ﴿الصراط المستقيم﴾؟","answer":"في الفاتحة طلب للهداية إلى ﴿الصراط المستقيم﴾ والثبات عليه. أما في الأنعام فالمقام بيان مزية الدين الذي هدى الله إليه نبيه؛ فجاء ﴿دينًا قِيَمًا﴾ وصفًا بالمصدر للمبالغة، كأن الدين هو الاستقامة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص401، تحت «مستقيم وقيم»","url":""}]},{"id":"s6-1019","number":1019,"surah":6,"verses":[162],"references":[{"surah":6,"verses":[162]}],"verseLabel":"الأنعام: 162","question":"ما دلالة التعبير بالمصدر الميمي في قوله تعالى: ﴿محياي ومماتي﴾؟","answer":"يجمع زمن الحياة وما يقع فيه من أعمال، وحال الموت وما يتصل به من مصير؛ ليعلن أن الوجود كله لله لا لحظة عبادة منفصلة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص640–641، تحت عنوان «دلالات التعبير بالمصدر الميمي ﴿ومحياي ومماتي﴾»","url":""}]},{"id":"s6-1020","number":1020,"surah":6,"verses":[162],"references":[{"surah":6,"verses":[162]}],"verseLabel":"الأنعام: 162","question":"لماذا قُدمت الصلاة والنسك على المحيا والممات؟","answer":"لأن العبادة هي المقصد الذي ينبغي أن تنتظم به الحياة كلها، فبدأ بأظهر أعمال الإخلاص ثم عمّ الحياة والموت وما يتصل بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص639، تحت عنوان «بلاغة الترتيب بين (الصلاة) و(النسك) و(المحيا) و(الممات)»","url":""}]},{"id":"s6-1401","number":1401,"surah":6,"verses":[162],"references":[{"surah":6,"verses":[162]}],"verseLabel":"الأنعام: 162","question":"لماذا عُطف ﴿نسكي﴾ على ﴿صلاتي﴾؟","answer":"لإبراز إخلاص النسك لله مع الصلاة؛ فإن أريد به الذبح خُص بعد أعظم العبادات، وإن أريد مطلق العبادة جمع الخاص والعام لتأكيد الشمول.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص640، تحت عنوان «نكتة عطف النسك على الصلاة»","url":""}]},{"id":"s6-1021","number":1021,"surah":6,"verses":[162],"references":[{"surah":6,"verses":[162]}],"verseLabel":"الأنعام: 162","question":"ما سرّ الجمع بين الألوهية والربوبية في قوله تعالى: ﴿لله رب العالمين﴾؟","answer":"إفراد العبادة له يقتضيه كونه رب العالمين؛ فهو المستحق لها بما تفضل به من الخلق والرزق، وبيده الحياة والموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص642، تحت «نكتة الجمع بين الألوهية والربوبية في ﴿لله رب العالمين﴾»","url":""}]},{"id":"s6-1022","number":1022,"surah":6,"verses":[163],"references":[{"surah":6,"verses":[163]}],"verseLabel":"الأنعام: 163","question":"لماذا جاءت جملة ﴿لا شريك له﴾ بعد إعلان أن العبادة والمحيا والممات لله؟","answer":"لتبين أن هذا الإخلاص خالص من كل مشاركة؛ فلا يتوجه شيء من العبادة أو الحياة أو المصير إلى غير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص642، تحت عنوان «الموقع النحوي والبياني لجملة التوحيد ﴿لا شريك له﴾»","url":""}]},{"id":"s6-1023","number":1023,"surah":6,"verses":[163],"references":[{"surah":6,"verses":[163]}],"verseLabel":"الأنعام: 163","question":"ما سرّ بناء ﴿وبذلك أمرت﴾ للمجهول؟","answer":"لم يسم الآمر لأن كونه الله معلوم من السياق لا يلتبس بغيره؛ فحذف الفاعل يحقق الإيجاز ويعتمد على شدة ظهوره في المقام. وبهذا يعلن الرسول أن هذا الإخلاص امتثال لما أمره الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص644، تحت «سر العدول في فعل الأمر إلى البناء للمفعول ﴿أمرت﴾»","url":""}]},{"id":"s6-1024","number":1024,"surah":6,"verses":[163],"references":[{"surah":6,"verses":[163]}],"verseLabel":"الأنعام: 163","question":"ما فائدة إضافة ﴿أول﴾ إلى ﴿المسلمين﴾ في قوله تعالى: ﴿وأنا أول المسلمين﴾؟","answer":"تحدد الأولية داخل جماعة المخاطبين وأمة النبي ﷺ؛ أي أنه أسبقهم استجابة وامتثالًا، من غير نفي إسلام الأنبياء قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص645، تحت عنوان «فائدة الإضافة في قوله تعالى: ﴿وأنا أول المسلمين﴾»","url":""}]},{"id":"s6-1025","number":1025,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"لماذا قُدّم ﴿غير الله﴾ في قوله تعالى: ﴿أغير الله أبغي ربًا﴾؟","answer":"لأنه موضع الإنكار والتوبيخ؛ فطلب رب غير الله هو المستنكر مع أنه رب كل شيء، فقدم لإبراز بطلانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص651، تحت عنوان «تقديم المفعول به على الفعل والفاعل»","url":""}]},{"id":"s6-1026","number":1026,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"ما دلالة القصر في قوله تعالى: ﴿ولا تكسب كل نفس إلا عليها﴾؟","answer":"يحصر تبعة الكسب في صاحبه؛ فلا يحمل الإنسان غيره نتيجة شره، ولا يتجاوز ذنبه إلى نفس بريئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص654، تحت عنوان «بلاغة القصر في ﴿ولا تكسب كل نفس إلا عليها﴾»","url":""}]},{"id":"s6-1027","number":1027,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"ما الغرض من الإخبار بقوله تعالى: ﴿ولا تزر وازرة وزر أخرى﴾؟","answer":"يقرر عدل المسؤولية الفردية: لا تحمل نفس إثم غيرها ولا تنجو بإلقاء تبعتها عليه، فكل إنسان يلقى أثر اختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص655، تحت عنوان «غرض الإخبار بنفي الوزر»","url":""}]},{"id":"s6-1402","number":1402,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"لماذا صُوّر الإثم بالوزر في قوله تعالى: ﴿ولا تزر وازرة وزر أخرى﴾؟","answer":"لأن الوزر حمل ثقيل، فصورت الاستعارة الذنب عبئًا يثقل صاحبه ولا يستطيع أن ينقله إلى سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص656، تحت عنوان «تشبيه الإثم بالوزر في الآية الكريمة من باب الاستعارة»","url":""}]},{"id":"s6-1028","number":1028,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم إلى ربكم مرجعكم﴾؟","answer":"تفيد الانتقال بعد انقضاء الحياة إلى الرجوع والحساب؛ فمهما طال الإمهال تبقى النهاية الموعودة آتية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص656، تحت عنوان «دلالة ﴿ثم﴾ العاطفة في قوله: ﴿ثم إلى ربكم مرجعكم﴾»","url":""}]},{"id":"s6-1403","number":1403,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"لماذا قُدّم قوله تعالى: ﴿إلى ربكم﴾ على ﴿مرجعكم﴾؟","answer":"للاهتمام والاختصاص: المرجع النهائي إلى الله وحده، وفي وصفه بربهم تذكير بسلطانه وتربيته ووعده ووعيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص657، تحت عنوان «بلاغة تقديم الجار والمجرور»","url":""}]},{"id":"s6-1029","number":1029,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"لماذا عُبّر بالموصول العام ﴿ما﴾ في قوله تعالى: ﴿بما كنتم فيه تختلفون﴾؟","answer":"ليشمل كل ما وقع فيه اختلاف من أمر الدين والحق والباطل، من غير حصر في مسألة واحدة؛ وسيكشف الله حقيقته ويحكم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص659، تحت عنوان «دلالة التعبير بالموصول (ما)»","url":""}]},{"id":"s6-1030","number":1030,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما دلالة التعبير بقوله تعالى: ﴿جعلكم خلائف الأرض﴾؟","answer":"يصور الناس أجيالًا يخلف بعضها بعضًا في عمارة الأرض، وفيه تكريم بالتمكين وتذكير بأن المقام مؤقت ينتقل إلى من بعدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص665، تحت عنوان «نكتة التعبير بقوله ﴿خلائف﴾ مادة وصيغة»","url":""}]},{"id":"s6-1404","number":1404,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما الغرض من إخبار الناس بأن الله جعلهم خلائف الأرض؟","answer":"ليوقظهم إلى نعمة التمكين ومسؤوليته؛ فمن ورث الأرض ممن قبله سيتركها لمن بعده ويحاسب على ما صنع فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص667، تحت عنوان «غرض المجيء بخبر جعلهم خلائف»","url":""}]},{"id":"s6-1031","number":1031,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما الصورة في قوله تعالى: ﴿ورفع بعضكم فوق بعض﴾؟","answer":"استعير الرفع الحسي لتفاوت الناس في المواهب والرزق والمكانة، ليصبح اختلاف أحوالهم كدرجات يعلو بعضها بعضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص668، تحت عنوان «بلاغة الاستعارة في رفع الدرجات في الآية الكريمة»","url":""}]},{"id":"s6-1405","number":1405,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"لماذا جاءت ﴿درجات﴾ جمعًا منكرة؟","answer":"لتدل على كثرة مراتب التفاوت وتنوعها، فهي ليست منزلة واحدة ولا نوعًا واحدًا من العطاء، بل درجات لا يحصيها وصف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص669، تحت عنوان «نكتة ورود كلمة درجات بالجمع والتنكير»","url":""}]},{"id":"s6-1032","number":1032,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ماذا يكشف قوله تعالى: ﴿ليبلوكم﴾ عن حكمة تفاوت العطايا؟","answer":"يكشف أن التفاوت امتحان لا معيار كرامة مطلقًا؛ ليظهر شكر من وُسّع عليه وصبر من ضُيق عليه، ويحاسب كلٌ على ما أُعطي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص669، تحت عنوان «دلالة (اللام) في قوله: ﴿ليبلوكم﴾ على التعليل»","url":""}]},{"id":"s6-1406","number":1406,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما دلالة التعبير بالإيتاء في قوله تعالى: ﴿فيما آتاكم﴾؟","answer":"يصوّر ما في أيدي الناس عطية من الله لا ملكًا مستقلًا، فيستدعي الشكر وحسن التصرف ويمنع الاغترار بالتفاوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص670، تحت عنوان «بلاغة التعبير بالإيتاء مادة وصيغة»","url":""}]},{"id":"s6-1033","number":1033,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما سرّ وصف العقاب بالسرعة مع تأخره أحيانًا؟","answer":"استعيرت السرعة لعدم التردد وكمال القدرة حين يحين وقت العقاب؛ فليس المراد وجوب وقوعه فورًا في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص671، تحت «غرض إضافة الصفة إلى الموصوف في ﴿سريع العقاب﴾»","url":""}]},{"id":"s6-1034","number":1034,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"لماذا خُتمت السورة بصفات العقاب والمغفرة والرحمة معًا؟","answer":"ليظل العبد بين الخوف والرجاء: لا يغتر بسعة الرحمة، ولا يقنط بسبب الذنب، بل يبادر إلى التوبة والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص671، تحت عنوان «نكتة ختم الآية بصفات العقاب والمغفرة والرحمة»","url":""}]},{"id":"s6-1407","number":1407,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"لماذا قُدّم الوعيد ﴿سريع العقاب﴾ على الوعد ﴿لغفور رحيم﴾؟","answer":"لأن السياق يواجه التكذيب ويحذر من عاقبته، فناسب تقديم الزجر؛ ثم أعقبه الوعد ليفتح باب الرجوع ولا يختم السورة على اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص672، تحت عنوان «نكتة تقديم الوعيد على الوعد في أسمائه»","url":""}]},{"id":"s6-1035","number":1035,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"لماذا دخلت اللام على ﴿لغفور﴾ ولم تدخل على ﴿سريع العقاب﴾؟","answer":"لترجيح جانب المغفرة والرحمة وتوكيده بعد الوعيد؛ فالعقاب ثابت في موضعه، لكن باب الرجاء أُبرز بتوكيد زائد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص672، تحت عنوان «دخول اللام على لفظ ﴿لغفور﴾ وعدم دخولها على ﴿سريع﴾»","url":""}]},{"id":"s7-1","number":1,"surah":7,"verses":[1],"references":[{"surah":7,"verses":[1]}],"verseLabel":"الأعراف: السورة","question":"ما مناسبة مجيء سورة الأعراف بعد الأنعام، وكيف تفصل ما أُجمل فيها؟","answer":"تأتي الأعراف بعد الأنعام لتفصيل ما أُجمل فيها من أحوال الأمم والرسل وقصة آدم وإبليس ومشاهد الرحمة والعذاب؛ فكانت بسطًا لمقاصد سبقتها إجمالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص198–199، تحت «مناسبة السورة الكريمة مع السورة بعدها»","url":""}]},{"id":"s7-2","number":2,"surah":7,"verses":[1],"references":[{"surah":7,"verses":[1]}],"verseLabel":"الأعراف: 1","question":"ما وجه افتتاح الأعراف بالحروف المقطعة ﴿المص﴾؟","answer":"من وجوه تفسيرها التنبيه إلى إعجاز القرآن؛ فهو مؤلف من الحروف التي يعرفها العرب ويستعملونها، ومع ذلك يعجزون عن الإتيان بمثله. ويذكر المصدر تعدد الأقوال في هذه الحروف، فلا يجزم بتعيين معنى واحد لكل حرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–691، تحت «شرح المفردات: ﴿المص﴾»","url":""}]},{"id":"s7-3","number":3,"surah":7,"verses":[1,2],"references":[{"surah":7,"verses":[1,2]}],"verseLabel":"الأعراف: 1–2","question":"ماذا توحي الحروف المقطعة ﴿المص﴾ في مطلع سورة الأعراف؟","answer":"توقظ السامع وتلفته إلى القرآن، وتشير إلى أن هذا الكتاب المعجز مؤلف من الحروف التي يعرفها العرب ومع ذلك عجزوا عن الإتيان بمثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–691، تحت عنوان «شرح المفردات: ﴿المص﴾»","url":""}]},{"id":"s7-4","number":4,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما الأغراض البلاغية لتنكير ﴿كتاب﴾ في مطلع السورة؟","answer":"يفيد التعظيم والتنويه بجلال القرآن، ويشير إلى أنه كتاب من جنس الكتب التي ينزلها الله على رسله، فيرد استبعادهم نزول الوحي على بشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص693، تحت عنوان «الأغراض البلاغية لتنكير لفظ ﴿كتاب﴾ بناء على تعدد المعاني»","url":""}]},{"id":"s7-5","number":5,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما سرّ بناء ﴿أنزل إليك﴾ للمجهول؟","answer":"بُني ﴿أنزل﴾ للمفعول لأن فاعل الإنزال متعين معلوم، وهو الله تعالى، فاستغني عن التصريح به اختصارًا. ويذكر المصدر جريان الأسلوب على سنن الكبرياء، مع ما توحي به مادة الإنزال من الوحي الآتي من العالم العلوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص695، تحت «نكتة بناء الفعل ﴿أنزل﴾ لما لم يسم فاعله»","url":""}]},{"id":"s7-6","number":6,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا يكن في صدرك حرج منه﴾، دون أن يقال: فلا تحرج منه؟","answer":"وُجه النهي ظاهرًا إلى الحرج نفسه مبالغة في نفيه، كأنه منهي عن أن يحل بصدر الرسول ﷺ. فالتعبير يقتلع الضيق من أصله، ويقوي معنى انشراح صدره لتبليغ الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص699–700، تحت «نكتة توجيه النهي إلى الحرج في الآية الكريمة»","url":""}]},{"id":"s7-7","number":7,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"لماذا جعل القرآن الحرج في الصدر بقوله: ﴿فلا يكن في صدرك حرج منه﴾؟","answer":"عبّر بالصدر عن موطن الشعور، وصوّر الحزن والضيق النفسي كأنه مكان ضيق يحبس صاحبه؛ فنهى عن الاستسلام لهذا الأثر عند تبليغ الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص698–699، تحت عنوان «بلاغة الاستعارة في قوله: ﴿فلا يكن في صدرك حرج منه﴾»","url":""}]},{"id":"s7-8","number":8,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما سرّ تقديم ﴿في صدرك﴾ على اسم ﴿يكن﴾؟","answer":"قُدّم ﴿في صدرك﴾ للاهتمام بصدر الرسول ﷺ، ولتقوية معنى ألا يكون محلًا لأي حرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص698، تحت «غرض تقديم شبه الجملة في ﴿فلا يكن في صدرك﴾»","url":""}]},{"id":"s7-9","number":9,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"إلى ماذا يعود الضمير في ﴿منه﴾: إلى الكتاب أم إلى الإنذار؟","answer":"يحتمل عوده إلى الكتاب، وهو الأقرب لفظًا، أي لا يكن حرج بسببه أو من تبليغه؛ ويدخل فيه الإنذار الذي أنزل لأجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص698، تحت «بلاغة المجاز أو الكناية في قوله: ﴿فلا يكن في صدرك حرج منه﴾»","url":""},{"label":"موسوعة التفسير البلاغي، ج12، ص700، تحت «معنى (من) في قوله تعالى: ﴿حرج منه﴾؛ وتعلق الجار في شبه الجملة ﴿منه﴾ وصلة الفاء به»","url":""}]},{"id":"s7-10","number":10,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿لتنذر به وذكرى للمؤمنين﴾، فعبّر عن الإنذار بالفعل وعن التذكير بالاسم؟","answer":"جاء ﴿لتنذر﴾ فعلًا مقترنًا بلام التعليل ليبين غاية إنزال الكتاب إلى الرسول ﷺ. وجاءت ﴿ذكرى﴾ مصدرًا، وهو أدل على أن التذكير من مهام القرآن الأساسية في حياة المؤمنين، فيبرز اختلاف الصياغة مهمة الإنذار ومهمة التذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص703، تحت «نكتة العدول الصرفي بين المعطوف والمعطوف عليه»","url":""}]},{"id":"s7-11","number":11,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"لماذا خُص المؤمنون بالذكرى مع أن الكتاب أُنزل للناس؟","answer":"لأن المؤمنين هم الذين ينتفعون بالتذكير، وفي التصريح بهم تنويه بشأنهم ومكانتهم عند الله، وتعريض بالكافرين الذين لا ينتفعون به. فالتخصيص يكرم أهل القبول مع عموم رسالة الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص701، تحت «بلاغة التصريح بمتعلق ﴿وذكرى﴾ دون متعلق ﴿لتنذر﴾»","url":""}]},{"id":"s7-12","number":12,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لماذا انتقل من خطاب النبي في ﴿إليك﴾ إلى خطاب الناس: ﴿اتبعوا ما أنزل إليكم﴾؟","answer":"انتقل من خطاب الرسول ﷺ متلقي الكتاب إلى خطاب الناس المكلفين باتباعه؛ فالتبليغ للنبي والاتباع للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص709، تحت «فائدة العدول من ضمير المخاطب المفرد إلى الجمع ﴿إليكم﴾»","url":""}]},{"id":"s7-13","number":13,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لماذا عُبّر عن القرآن بقوله تعالى: ﴿ما أنزل إليكم من ربكم﴾؟","answer":"ليعلق وجوب الاتباع بوصف الإنزال من الرب، ويعم كل ما أنزله من هداية وأحكام، فيستدعي تلقيه بالطاعة لا بمجرد المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص708، تحت عنوان «نكتة التعبير بالاسم الموصول ﴿ما﴾ عن الكتاب»","url":""}]},{"id":"s7-14","number":14,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لماذا اختير اسم الرب في ﴿من ربكم﴾؟","answer":"اختير ﴿ربكم﴾ لاستمالتهم إلى الاتباع بتذكيرهم بأن المنزل مربيهم والمنعم عليهم والعالم بمصالحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص710، تحت «نكتة مجيء لفظ الرب وإضافته إلى ضمير (هم)»","url":""}]},{"id":"s7-15","number":15,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لماذا عُطف النهي ﴿ولا تتبعوا﴾ على الأمر ﴿اتبعوا﴾؟","answer":"ليجمع طريق الهداية من جهتيه: ملازمة الوحي وترك كل ولاية تخالفه؛ فاتباع الحق لا يكتمل مع طاعة من يصرف عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص710، تحت عنوان «بلاغة عطف النهي ﴿ولا تتبعوا﴾ على الأمر ﴿اتبعوا﴾»","url":""}]},{"id":"s7-16","number":16,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿من دونه أولياء﴾، دون أن يقال: غيره؟","answer":"تصور ﴿من دونه﴾ الإعراض عن الله باتباع ما لم يأذن به، مع أن المشركين كانوا يزعمون أنهم يقصدون التقرب إليه بعبادة أصنامهم. فالتعبير يكشف أن هذا الاتباع إعراض عما أمر به، لا طريق قرب إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص712، تحت «نكتة الاستعارة في قوله تعالى: ﴿من دونه﴾»","url":""}]},{"id":"s7-17","number":17,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لم نُهي عن اتباع ﴿أولياء﴾ دون الاقتصار على تسمية الشركاء والآلهة؟","answer":"الولاية تتضمن القرب والنصرة والاتباع، والمقصود هنا النهي عن اتباع غير الوحي في الهداية والدين والأحكام. فلفظ الأولياء يلائم هذا الاتباع، ولا يقصر النهي على دعوى الشراكة في الألوهية وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص715–716، تحت «(أولياء) و(شركاء) و(أنداد) و(آلهة)»","url":""}]},{"id":"s7-18","number":18,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"ما دلالة لفظ ﴿قليلًا﴾ في قوله تعالى: ﴿قليلًا ما تذكرون﴾؟","answer":"يوبخهم على ندرة اتعاظهم؛ فلو استحضروا نعمة الرب وحقيقة الوحي لما اتبعوا أولياء من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص713–714، تحت عنوان «بلاغة لفظ ﴿قليلًا﴾ في سياق الآية الكريمة»","url":""}]},{"id":"s7-19","number":19,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"ما سرّ التعبير هنا في قوله تعالى ﴿تذكرون﴾، وفي الآية 10 ﴿تشكرون﴾؟","answer":"جاء ﴿تذكرون﴾ بعد الأمر باتباع الوحي لأن المطلوب الاتعاظ، و﴿تشكرون﴾ بعد التمكين والمعايش لأنها نعم تستوجب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص764، تحت «نكتة التعبير بالشكر في هذا الموضع والتذكر في الموضع السابق»","url":""}]},{"id":"s7-20","number":20,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿وكم من قرية أهلكناها﴾، والمراد أهلها؟","answer":"أُطلقت القرية وأريد أهلها بعلاقة المحل والحال؛ وفي ذلك تصوير للهلاك مستوعبًا المكان ومن فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص721–722، تحت «دلالة قوله: ﴿أهلكناها﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s7-21","number":21,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"لماذا اختيرت ﴿كم﴾ الخبرية؟","answer":"﴿كم﴾ الخبرية للتكثير، فتستحضر كثرة القرى الهالكة للتهديد والعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص720، تحت «فائدة مجيء (كم) الخبرية»","url":""}]},{"id":"s7-22","number":22,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"لماذا ذُكر إهلاك القرية قبل مجيء البأس في قوله: ﴿وكم من قرية أهلكناها فجاءها بأسنا﴾؟","answer":"لأن الإهلاك ذُكر أولًا حكمًا مجملًا، ثم فُصلت كيفيته بمجيء البأس؛ فالترتيب في عرض الخبر لا في وقوع الحدث.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص722–723، تحت عنوان «علة تقديم الإهلاك على مجيء البأس في الآية الكريمة»","url":""}]}]);
